_STARTUP_LOG_DIR = (
    _Path(_os.environ.get("APPDATA") or (_Path.home() / "AppData" / "Roaming"))
    / "GitHubOpenSourceBrowser"
    / "logs"
)
_STARTUP_LOG_PATH = _STARTUP_LOG_DIR / "startup.log"
_STARTUP_LOG_MAX_BYTES = 512 * 1024
_STARTUP_LOG_KEEP_BYTES = 256 * 1024


def _sanitize_startup_text(value: _Any) -> str:
    " 隐藏异常信息中可能出现的令牌、密码和密钥。"
    text = str(value or "")
    replacements = (
        (r"(?i)(authorization\s*[:=]\s*bearer\s+)[^\s,;]+", r"\1<已隐藏>"),
        (r"(?i)((?:token|secret|password|passwd|api[_-]?key|access[_-]?key)\s*[:=]\s*)[^\s,;]+", r"\1<已隐藏>"),
        (r"(?:gh[pousr]_|github_pat_)[A-Za-z0-9_]+", "<已隐藏令牌>"),
    )
    for pattern, replacement in replacements:
        text = _re.sub(pattern, replacement, text)
    return text


def _write_startup_log(message: str, exc_info=None) -> None:
    "写入启动和后台异常日志，日志失败时不影响程序继续运行。"
    try:
        _STARTUP_LOG_DIR.mkdir(parents=True, exist_ok=True)
        if _STARTUP_LOG_PATH.is_file() and _STARTUP_LOG_PATH.stat().st_size > _STARTUP_LOG_MAX_BYTES:
            old_data = _STARTUP_LOG_PATH.read_bytes()
            _STARTUP_LOG_PATH.write_bytes(old_data[-_STARTUP_LOG_KEEP_BYTES:])
        timestamp = _Datetime.now().astimezone().isoformat(timespec="seconds")
        entry = f"[{timestamp}] {_sanitize_startup_text(message)}\n"
        if exc_info is not None:
            entry += _sanitize_startup_text("".join(_traceback.format_exception(*exc_info)))
        with _STARTUP_LOG_PATH.open("a", encoding="utf-8") as log_file:
            log_file.write(entry)
    except BaseException:
        pass


_SCROLL_DEBUG_ENABLED = _os.environ.get("GOBS_DEBUG_SCROLL") == "1"


def _scroll_debug(message) -> None:
    if _SCROLL_DEBUG_ENABLED:
        _write_startup_log("滚动调试：" + str(message))


_ORIGINAL_SYS_EXCEP_HOOK = _sys.excepthook
def _startup_excepthook(exc_type, exc_value, exc_traceback):
    _write_startup_log("检测到未处理异常", (exc_type, exc_value, exc_traceback))
    try:
        _ORIGINAL_SYS_EXCEP_HOOK(exc_type, exc_value, exc_traceback)
    except BaseException:
        pass


_sys.excepthook = _startup_excepthook

_ORIGINAL_THREADING_EXCEP_HOOK = _threading.excepthook
def _startup_threading_excepthook(args):
    _write_startup_log(
        "后台线程出现未处理异常：" + str(getattr(args, "thread", None)),
        (args.exc_type, args.exc_value, args.exc_traceback),
    )
    try:
        _ORIGINAL_THREADING_EXCEP_HOOK(args)
    except BaseException:
        pass


_threading.excepthook = _startup_threading_excepthook
