class _CappedThreadPoolExecutor(_OriginalThreadPoolExecutor):
    """限制后台并发数，避免翻译、测速和图片任务同时占满机器。"""

    def __init__(self, max_workers=None, *args, **kwargs):
        try:
            requested = BACKGROUND_MAX_WORKERS if max_workers is None else int(max_workers)
        except (TypeError, ValueError):
            requested = BACKGROUND_MAX_WORKERS
        super().__init__(max_workers=max(1, min(requested, BACKGROUND_MAX_WORKERS)), *args, **kwargs)


# 恢复代码中的批量翻译、镜像测速等逻辑会查找这个名称。
_RECOVERED_NAMESPACE["ThreadPoolExecutor"] = _CappedThreadPoolExecutor
ThreadPoolExecutor = _CappedThreadPoolExecutor


def _normalize_topics(value: _Any) -> list[str]:
    """把 GitHub 主题标签统一成去重后的字符串列表。"""
    if value is None:
        return []
    if isinstance(value, str):
        values = _re.split(r"[,;\n]", value)
    elif isinstance(value, (list, tuple, set)):
        values = list(value)
    else:
        values = [value]
    result: list[str] = []
    seen: set[str] = set()
    for item in values:
        topic = str(item or "").strip()
        if not topic:
            continue
        key = topic.casefold()
        if key in seen:
            continue
        seen.add(key)
        result.append(topic)
    return result


def _repo_identity(item: dict) -> str:
    return str(item.get("full_name") or item.get("html_url") or "").strip().casefold()


def _attach_topics(repos: list[dict], raw_items: list[dict]) -> list[dict]:
    """把原始 API 返回的 topics 合并回界面使用的项目字典。"""
    raw_map: dict[str, dict] = {}
    for item in raw_items or []:
        if isinstance(item, dict):
            identity = _repo_identity(item)
            if identity:
                raw_map[identity] = item
    for repo in repos or []:
        if not isinstance(repo, dict):
            continue
        raw = raw_map.get(_repo_identity(repo))
        if raw is not None:
            repo["topics"] = _normalize_topics(raw.get("topics"))
        else:
            repo.setdefault("topics", [])
    return repos


def _call_with_raw_items(method, service, *args, **kwargs):
    """调用恢复方法，同时捕获它交给映射逻辑前的原始项目。"""
    captured: list[dict] = []
    http = getattr(service, "http", None)
    original_get = getattr(http, "get", None)
    if http is None or original_get is None:
        return method(service, *args, **kwargs), captured

    def capture_get(*request_args, **request_kwargs):
        response = original_get(*request_args, **request_kwargs)
        try:
            payload = response.json()
        except Exception:
            payload = {}
        if isinstance(payload, dict):
            items = payload.get("items")
            if isinstance(items, list):
                captured.extend(item for item in items if isinstance(item, dict))
        return response

    http.get = capture_get
    try:
        result = method(service, *args, **kwargs)
    finally:
        http.get = original_get
    return result, captured


_ORIGINAL_SEARCH_REPOS = GitHubService.search_repos
_ORIGINAL_SCRAPE_TRENDING = GitHubService.scrape_trending


def _search_cache_key(service, keyword: str, page: int, per_page: int) -> str:
    normalized = (keyword or "").strip()
    try:
        normalized_page = max(1, int(page))
    except (TypeError, ValueError):
        normalized_page = 1
    try:
        page_size = max(1, min(int(per_page), 100))
    except (TypeError, ValueError):
        page_size = REPOSITORY_PAGE_SIZE
    config = getattr(service, "config", {}) or {}
    return (
        f"search::{normalized}::{config.get('language', '')}::"
        f"{config.get('sort', '')}::{normalized_page}::{page_size}"
    )


def _search_repos_with_topics(self, keyword: str = "", page: int = 1, per_page: int = REPOSITORY_PAGE_SIZE) -> list[dict]:
    cache_key = _search_cache_key(self, keyword, page, per_page)
    repos, raw_items = _call_with_raw_items(_ORIGINAL_SEARCH_REPOS, self, keyword, page, per_page)
    missing_topics = bool(repos) and any(
        isinstance(repo, dict) and "topics" not in repo for repo in repos
    )
    # 旧缓存没有 topics 时只重拉当前页，避免分类继续使用残缺缓存。
    if missing_topics and not raw_items:
        cache = getattr(self, "_search_cache", None)
        if isinstance(cache, dict):
            cache.pop(cache_key, None)
        repos, raw_items = _call_with_raw_items(_ORIGINAL_SEARCH_REPOS, self, keyword, page, per_page)
    return _attach_topics(repos or [], raw_items)


def _scrape_trending_with_topics(
    self,
    since: str = "daily",
    language: str = "",
    page: int = 1,
    per_page: int = TRENDING_PAGE_SIZE,
) -> list[dict]:
    repos, raw_items = _call_with_raw_items(
        _ORIGINAL_SCRAPE_TRENDING,
        self,
        since,
        language,
        page,
        per_page,
    )
    return _attach_topics(repos or [], raw_items)


GitHubService.search_repos = _search_repos_with_topics
GitHubService.scrape_trending = _scrape_trending_with_topics


