def _normalize_topic_for_category(value: _Any) -> str:
    return str(value or "").strip().casefold().replace("_", "-").replace(" ", "-")


def _filter_repos_by_category_with_topics(self, repos: list[dict], category: str) -> list[dict]:
    if not category:
        return list(repos or [])
    category_key = str(category).strip().casefold()
    target_languages = _CATEGORY_LANGUAGES.get(category_key, set())
    target_keywords = _CATEGORY_KEYWORDS.get(category_key, set())
    target_topics = _CATEGORY_TOPICS.get(category_key, set())
    filtered: list[dict] = []
    for repo in repos or []:
        if not isinstance(repo, dict):
            continue
        language = str(repo.get("language") or "").strip().casefold()
        searchable = " ".join(
            str(repo.get(field) or "")
            for field in ("full_name", "name", "description", "description_zh", "tags")
        ).casefold()
        topics = {
            _normalize_topic_for_category(topic)
            for topic in _normalize_topics(repo.get("topics"))
        }
        if (
            language in target_languages
            or bool(topics & target_topics)
            or any(keyword in searchable for keyword in target_keywords)
        ):
            filtered.append(repo)
    return filtered


MainWindow._filter_repos_by_category = _filter_repos_by_category_with_topics


_ORIGINAL_APPLY_CATEGORY_FILTER = MainWindow._apply_category_filter


def _apply_category_filter_with_prefetch(self):
    current_view = self.view_combo.currentData()
    if current_view == "discover":
        source = list(getattr(self, "_repos", []) or [])
        visible_attr = "_display_repos"
        target_list = self.repo_list
        render = self._render_discover_items
        has_more = bool(getattr(self, "_search_has_more", False))
        loading_more = bool(getattr(self, "_search_loading_more", False))
        load_more = self._load_more_discover
        loading_attr = "_search_loading_more"
    elif current_view == "trending":
        source = list(getattr(self, "_trending_items", []) or [])
        visible_attr = "_display_trending_items"
        target_list = self.trending_list
        render = self._render_trending_items
        has_more = bool(getattr(self, "_trending_has_more", False))
        loading_more = bool(getattr(self, "_trending_loading_more", False))
        load_more = self._load_more_trending
        loading_attr = "_trending_loading_more"
    else:
        return

    category = str(getattr(self, "_current_category", "") or "")
    visible = self._filter_repos_by_category(source, category)
    setattr(self, visible_attr, visible)
    self._update_list_summary()

    if not source:
        self._stop_search_rendering()
        self._stop_trending_rendering()
        target_list.clear()
        return

    if category and has_more and not loading_more and len(visible) < CATEGORY_PREFETCH_TARGET:
        if visible:
            render(visible)
        else:
            self._stop_search_rendering()
            self._stop_trending_rendering()
            target_list.clear()
        self.status_label.setText(
            f"正在继续加载分类“{self._category_label(category)}”"
            f"（已匹配 {len(visible)} 个）…"
        )
        scheduled_attr = "_category_prefetch_scheduled"
        if not getattr(self, scheduled_attr, False) and not getattr(self, loading_attr, False):
            setattr(self, scheduled_attr, True)

            def trigger_load_more():
                setattr(self, scheduled_attr, False)
                if not getattr(self, loading_attr, False):
                    load_more()

            _QTimer.singleShot(0, trigger_load_more)
        self._update_list_summary()
        return

    if category and not visible:
        self._stop_search_rendering()
        self._stop_trending_rendering()
        target_list.clear()
        self.status_label.setText(f"分类“{self._category_label(category)}”没有匹配项目")
        self._update_list_summary()
        return

    render(visible)


MainWindow._apply_category_filter = _apply_category_filter_with_prefetch


