_STARTUP_IDLE_INITIAL_DELAY_MS = 2500
_STARTUP_IDLE_RETRY_MS = 1000
_STARTUP_IDLE_MAX_WAIT_SECONDS = 30.0
_STARTUP_IDLE_TIMER_ATTR = "_startup_idle_timers"
_STARTUP_IDLE_CLOSING_ATTR = "_startup_idle_closing"


def _startup_idle_is_busy(window) -> bool:
    """判断首屏核心任务是否仍在运行。"""
    try:
        if int(getattr(window, "_busy_count", 0) or 0) > 0:
            return True
    except (TypeError, ValueError):
        pass

    for attr in (
        "_search_loading_more",
        "_trending_loading_more",
        "_detail_translation_running",
    ):
        try:
            if bool(getattr(window, attr, False)):
                return True
        except BaseException:
            continue
    return False


def _startup_idle_timers(window) -> dict:
    """取得窗口持有的启动空闲任务计时器。"""
    timers = getattr(window, _STARTUP_IDLE_TIMER_ATTR, None)
    if not isinstance(timers, dict):
        timers = {}
        setattr(window, _STARTUP_IDLE_TIMER_ATTR, timers)
    return timers


def _stop_startup_idle_timer(timer) -> None:
    """停止并安排释放一个启动空闲任务计时器。"""
    if timer is None:
        return
    try:
        timer.stop()
    except BaseException:
        pass
    try:
        timer.deleteLater()
    except BaseException:
        pass


def _cancel_startup_idle_tasks(window) -> None:
    """关闭窗口时取消尚未执行的非核心后台任务。"""
    setattr(window, _STARTUP_IDLE_CLOSING_ATTR, True)
    timers = getattr(window, _STARTUP_IDLE_TIMER_ATTR, None)
    if not isinstance(timers, dict):
        return
    for timer in list(timers.values()):
        _stop_startup_idle_timer(timer)
    timers.clear()


def _schedule_startup_idle_task(window, key, callback, initial_delay_ms: int) -> None:
    """等首屏空闲后再启动镜像测速或版本检查。"""
    if bool(getattr(window, _STARTUP_IDLE_CLOSING_ATTR, False)):
        return

    timers = _startup_idle_timers(window)
    task_key = str(key)
    _stop_startup_idle_timer(timers.pop(task_key, None))
    started_at = _time.monotonic()
    timer = _QTimer(window)
    timer.setSingleShot(True)

    def trigger():
        if bool(getattr(window, _STARTUP_IDLE_CLOSING_ATTR, False)):
            timers.pop(task_key, None)
            _stop_startup_idle_timer(timer)
            return

        elapsed = _time.monotonic() - started_at
        if _startup_idle_is_busy(window) and elapsed < _STARTUP_IDLE_MAX_WAIT_SECONDS:
            try:
                timer.start(_STARTUP_IDLE_RETRY_MS)
            except BaseException:
                timers.pop(task_key, None)
                _stop_startup_idle_timer(timer)
                _write_startup_log("无法重新安排启动空闲后台任务", _sys.exc_info())
            return

        try:
            callback(window)
        except BaseException:
            _write_startup_log("延迟后台任务启动失败", _sys.exc_info())
        finally:
            timers.pop(task_key, None)
            _stop_startup_idle_timer(timer)

    try:
        timer.timeout.connect(trigger)
        timers[task_key] = timer
        timer.start(max(0, int(initial_delay_ms)))
    except BaseException:
        timers.pop(task_key, None)
        _stop_startup_idle_timer(timer)
        _write_startup_log("无法安排启动空闲后台任务", _sys.exc_info())


def _optimized_mainwindow_init(self, service):
    """先完成窗口绘制，再在首屏空闲后启动非核心网络任务。"""
    setattr(self, _STARTUP_IDLE_CLOSING_ATTR, False)
    setattr(self, _STARTUP_IDLE_TIMER_ATTR, {})

    def defer_refresh(instance):
        _QTimer.singleShot(0, lambda: _ORIGINAL_REFRESH_REPOS(instance))

    def defer_mirror(instance):
        _schedule_startup_idle_task(
            instance,
            "mirror",
            _ORIGINAL_START_MIRROR_AUTOTEST,
            _STARTUP_IDLE_INITIAL_DELAY_MS,
        )

    def defer_release(instance):
        _schedule_startup_idle_task(
            instance,
            "release",
            _ORIGINAL_START_RELEASE_NOTIFY,
            _STARTUP_IDLE_INITIAL_DELAY_MS,
        )

    original_refresh = MainWindow.refresh_repos
    original_mirror = MainWindow._start_mirror_autotest
    original_release = MainWindow._start_release_notify
    MainWindow.refresh_repos = defer_refresh
    MainWindow._start_mirror_autotest = defer_mirror
    MainWindow._start_release_notify = defer_release
    try:
        _ORIGINAL_MAINWINDOW_INIT(self, service)
    finally:
        MainWindow.refresh_repos = original_refresh
        MainWindow._start_mirror_autotest = original_mirror
        MainWindow._start_release_notify = original_release

    try:
        self.thread_pool.setMaxThreadCount(UI_MAX_THREAD_COUNT)
    except Exception:
        pass


def _close_event_with_startup_idle(self, event):
    """退出程序前停止尚未触发的启动空闲任务。"""
    _cancel_startup_idle_tasks(self)
    return _ORIGINAL_CLOSE_EVENT_FOR_STARTUP_IDLE(self, event)


MainWindow.__init__ = _optimized_mainwindow_init
MainWindow.closeEvent = _close_event_with_startup_idle
try:
    _QThreadPool.globalInstance().setMaxThreadCount(UI_MAX_THREAD_COUNT)
except Exception:
    pass


# 让源代码直接运行、包内入口和打包后的程序都使用同一个模块入口。

# ------------------------------ 网络请求、缓存与并发保护 ------------------------------
import math as _math

_HTTP_TOTAL_TIMEOUT_CAP = 15.0
_HTTP_DIRECT_TIMEOUT_CAP = 10.0
_HTTP_MIRROR_PROBE_TIMEOUT_CAP = 3.0
_HTTP_MIN_TIMEOUT = 0.25
_HTTP_MIN_REQUEST_BUDGET = _HTTP_MIN_TIMEOUT * 2
_HTTP_CACHE_SCHEMA_VERSION = "http-cache-v2"
_HTTP_CACHE_DEFAULT_TTL = 300
_HTTP_CACHE_MAX_ENTRIES = 64
_HTTP_CACHE_MAX_PERSIST_BYTES = 1_500_000
_ASYNC_CONTEXT_ATTRS = (
    "_search_request_id",
    "_trending_request_id",
    "_detail_request_id",
)
_STALE_TASK_RESULT = object()
_HTTP_STATE_INIT_LOCK = _threading.Lock()


def _timeout_number(value, fallback: float) -> float:
    """把请求超时参数转换为可参与计算的正数。"""
    values = []
    if isinstance(value, (tuple, list)):
        for part in value:
            try:
                number = float(part)
            except (TypeError, ValueError):
                continue
            if _math.isfinite(number) and number > 0:
                values.append(number)
    else:
        try:
            number = float(value)
        except (TypeError, ValueError):
            number = 0.0
        if _math.isfinite(number) and number > 0:
            values.append(number)
    if not values:
        return float(fallback)
    return max(values)


class _HttpInflightRequest:
    """记录同一个网络请求的执行状态，让并发调用共享一次请求。"""

    __slots__ = ("event", "response", "error")

    def __init__(self):
        self.event = _threading.Event()
        self.response = None
        self.error = None


def _ensure_http_cache_state(client) -> None:
    """兼容旧对象并初始化缓存、请求去重所需的线程状态。"""
    if (
        hasattr(client, "_cache_lock")
        and hasattr(client, "_inflight_requests")
        and hasattr(client, "_cache_epoch")
    ):
        return
    with _HTTP_STATE_INIT_LOCK:
        if not hasattr(client, "_cache_lock"):
            client._cache_lock = _threading.RLock()
        if not isinstance(getattr(client, "_cache", None), dict):
            client._cache = {}
        if not isinstance(getattr(client, "_inflight_requests", None), dict):
            client._inflight_requests = {}
        if not isinstance(getattr(client, "_cache_epoch", None), int):
            client._cache_epoch = 0
        if not hasattr(client, "_api_cache_db"):
            client._api_cache_db = None
        if not hasattr(client, "_cache_ttl"):
            client._cache_ttl = _HTTP_CACHE_DEFAULT_TTL


def _stable_cache_value(value) -> str:
    """把请求参数转换成稳定且不泄露令牌的缓存键片段。"""
    try:
        return _json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
    except Exception:
        return repr(value)


def _build_http_cache_key(client, url: str, params=None) -> str:
    """按网址、参数和令牌指纹生成稳定的持久化缓存键。"""
    if isinstance(params, dict):
        normalized_params = {
            str(key): params[key]
            for key in sorted(params, key=lambda item: str(item))
        }
    else:
        normalized_params = params
    token = str((getattr(client, "config", {}) or {}).get("github_token") or "")
    token_fingerprint = (
        _hashlib.sha256(token.encode("utf-8", "ignore")).hexdigest()[:16]
        if token
        else "public"
    )
    return (
        f"{_HTTP_CACHE_SCHEMA_VERSION}::{str(url or '').strip()}::"
        f"{_stable_cache_value(normalized_params)}::auth={token_fingerprint}"
    )


def _http_cache_ttl(client, url: str) -> int:
    """根据接口类型选择缓存时长，详情数据比列表数据稍长。"""
    try:
        base_ttl = max(30, int(getattr(client, "_cache_ttl", _HTTP_CACHE_DEFAULT_TTL)))
    except (TypeError, ValueError):
        base_ttl = _HTTP_CACHE_DEFAULT_TTL
    normalized_url = str(url or "").casefold()
    if "/readme" in normalized_url:
        return max(base_ttl, 900)
    if "/repos/" in normalized_url and "/search/" not in normalized_url:
        return max(base_ttl, 600)
    return base_ttl


def _memory_cache_get(client, cache_key: str, ttl: int):
    """读取线程安全的内存缓存，并及时移除过期条目。"""
    now = _time.time()
    with client._cache_lock:
        cached = client._cache.get(cache_key)
        if not cached:
            return None
        try:
            timestamp, response = cached
        except (TypeError, ValueError):
            client._cache.pop(cache_key, None)
            return None
        if now - float(timestamp) < ttl:
            return response
        client._cache.pop(cache_key, None)
    return None


def _memory_cache_put(client, cache_key: str, response) -> None:
    """写入内存缓存并限制条目数量，避免长期运行占用过多内存。"""
    with client._cache_lock:
        client._cache[cache_key] = (_time.time(), response)
        while len(client._cache) > _HTTP_CACHE_MAX_ENTRIES:
            oldest_key = min(
                client._cache,
                key=lambda key: client._cache[key][0],
            )
            client._cache.pop(oldest_key, None)


def _serialize_cached_response(response):
    """将可缓存的文本或接口响应序列化为数据库记录。"""
    try:
        status_code = int(getattr(response, "status_code", 0) or 0)
        content = bytes(getattr(response, "content", b"") or b"")
        headers = dict(getattr(response, "headers", {}) or {})
    except Exception:
        return None
    if status_code != 200 or len(content) > _HTTP_CACHE_MAX_PERSIST_BYTES:
        return None
    content_type = str(headers.get("Content-Type", "")).casefold()
    if content_type.startswith(("image/", "audio/", "video/")):
        return None
    if any(
        marker in content_type
        for marker in ("application/octet-stream", "application/zip", "application/pdf")
    ):
        return None
    payload = {
        "version": _HTTP_CACHE_SCHEMA_VERSION,
        "status_code": status_code,
        "url": str(getattr(response, "url", "") or ""),
        "reason": str(getattr(response, "reason", "") or ""),
        "encoding": getattr(response, "encoding", None),
        "headers": {str(key): str(value) for key, value in headers.items()},
        "content": _base64.b64encode(content).decode("ascii"),
    }
    try:
        return _json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    except Exception:
        return None


def _restore_cached_response(serialized):
    """从数据库记录还原一个可供调用方读取的响应对象。"""
    if not isinstance(serialized, str) or not serialized:
        return None
    try:
        payload = _json.loads(serialized)
        if not isinstance(payload, dict) or payload.get("version") != _HTTP_CACHE_SCHEMA_VERSION:
            return None
        content = _base64.b64decode(str(payload.get("content") or ""), validate=True)
        if len(content) > _HTTP_CACHE_MAX_PERSIST_BYTES:
            return None
        response = _requests.Response()
        response.status_code = int(payload.get("status_code") or 200)
        response.url = str(payload.get("url") or "")
        response.reason = str(payload.get("reason") or "")
        encoding = payload.get("encoding")
        if encoding:
            response.encoding = str(encoding)
        headers = payload.get("headers")
        if isinstance(headers, dict):
            response.headers.update({str(key): str(value) for key, value in headers.items()})
        response._content = content
        response._content_consumed = True
        return response
    except Exception:
        return None


def _load_persistent_http_cache(client, cache_key: str):
    """从现有应用数据库读取未过期的接口缓存。"""
    cache_db = getattr(client, "_api_cache_db", None)
    getter = getattr(cache_db, "get_api_cache", None)
    if not callable(getter):
        return None
    try:
        response = _restore_cached_response(getter(cache_key))
    except Exception:
        return None
    if response is not None:
        _memory_cache_put(client, cache_key, response)
    return response


def _save_persistent_http_cache(client, cache_key: str, response, ttl: int, epoch: int) -> None:
    """将小型文本接口响应保存到应用数据库，失败时不影响正常请求。"""
    with client._cache_lock:
        if client._cache_epoch != epoch:
            return
    cache_db = getattr(client, "_api_cache_db", None)
    setter = getattr(cache_db, "set_api_cache", None)
    if not callable(setter):
        return
    serialized = _serialize_cached_response(response)
    if serialized is None:
        return
    try:
        setter(cache_key, serialized, ttl=int(ttl))
    except Exception:
        pass


def _clear_http_cache(self, clear_persistent: bool = True) -> None:
    """清空缓存并递增代数，使旧请求完成后不能重新写入缓存。"""
    _ensure_http_cache_state(self)
    with self._cache_lock:
        self._cache_epoch += 1
        self._cache.clear()
    if not clear_persistent:
        return
    cache_db = getattr(self, "_api_cache_db", None)
    clear_method = getattr(cache_db, "clear_api_cache", None)
    try:
        if callable(clear_method):
            clear_method()
            return
        connection = getattr(cache_db, "conn", None)
        if connection is not None:
            connection.execute("DELETE FROM api_cache")
            connection.commit()
    except Exception:
        pass


_ORIGINAL_HTTPCLIENT_INIT = HttpClient.__init__
_ORIGINAL_HTTPCLIENT_UPDATE_CONFIG = HttpClient.update_config
_ORIGINAL_HTTPCLIENT_GET = HttpClient.get
_ORIGINAL_GITHUBSERVICE_INIT = GitHubService.__init__


