def _bounded_timeout(value, remaining: float, fallback: float) -> tuple[float, float]:
    """把连接和读取超时压缩到同一个剩余时间预算内。"""
    try:
        budget = float(remaining)
    except (TypeError, ValueError):
        budget = float(fallback)
    if not _math.isfinite(budget) or budget <= 0:
        budget = _HTTP_MIN_TIMEOUT
    budget = max(budget, 0.01)

    safe_fallback = max(_HTTP_MIN_TIMEOUT, _timeout_number(fallback, 12.0))
    if isinstance(value, (tuple, list)):
        parts = list(value)[:2]
        connect_requested = _timeout_number(
            parts[0] if parts else None,
            safe_fallback,
        )
        read_requested = _timeout_number(
            parts[1] if len(parts) > 1 else None,
            safe_fallback,
        )
    else:
        requested = _timeout_number(value, safe_fallback)
        connect_requested = min(requested, 3.0)
        read_requested = requested

    # 预算不足两个最小超时时，按比例分配，确保二元组之和仍不超过预算。
    if budget < _HTTP_MIN_REQUEST_BUDGET:
        pair_floor = max(0.005, budget / 2.0)
        connect_timeout = min(connect_requested, max(pair_floor, budget * 0.35))
        connect_timeout = min(connect_timeout, max(0.001, budget - pair_floor))
        read_timeout = min(
            read_requested,
            max(0.001, budget - connect_timeout),
        )
        if connect_timeout + read_timeout > budget:
            read_timeout = max(0.001, budget - connect_timeout)
        return (connect_timeout, read_timeout)

    connect_timeout = min(
        connect_requested,
        max(_HTTP_MIN_TIMEOUT, budget * 0.35),
        budget - _HTTP_MIN_TIMEOUT,
    )
    connect_timeout = max(_HTTP_MIN_TIMEOUT, connect_timeout)
    read_timeout = min(
        read_requested,
        budget - connect_timeout,
    )
    read_timeout = max(_HTTP_MIN_TIMEOUT, read_timeout)
    if connect_timeout + read_timeout > budget:
        read_timeout = max(_HTTP_MIN_TIMEOUT, budget - connect_timeout)
    return (connect_timeout, read_timeout)


def _request_http_without_cache(self, url: str, params=None, timeout=20):
    """执行一次不读取、不写入缓存的官网和镜像请求。"""
    requested_timeout = _timeout_number(timeout, 12.0)
    total_timeout = min(
        max(requested_timeout, _HTTP_MIN_REQUEST_BUDGET),
        _HTTP_TOTAL_TIMEOUT_CAP,
    )
    deadline = _time.monotonic() + total_timeout
    direct_timeout = min(total_timeout, _HTTP_DIRECT_TIMEOUT_CAP)
    direct_error = None

    try:
        remaining = deadline - _time.monotonic()
        if remaining <= 0:
            raise TimeoutError("网络请求超时，请稍后重试")
        response = self.session.get(
            url,
            params=params,
            timeout=_bounded_timeout(
                timeout,
                min(remaining, direct_timeout),
                12.0,
            ),
        )
        response.raise_for_status()
        return response
    except Exception as exc:
        direct_error = exc

    mode = str(self.config.get("mirror_mode", "auto") or "auto").strip().lower()
    if mode == "none":
        raise direct_error

    remaining = deadline - _time.monotonic()
    if remaining <= _HTTP_MIN_REQUEST_BUDGET:
        raise direct_error

    try:
        if mode == "fixed":
            mirrors = getattr(self.mirror, "mirrors", None) or []
            prefix = mirrors[0] if mirrors else ""
        else:
            # 为镜像测速预留至少一次镜像请求的时间，避免测速后没有时间真正请求。
            probe_budget = min(
                _HTTP_MIRROR_PROBE_TIMEOUT_CAP,
                remaining - _HTTP_MIN_REQUEST_BUDGET,
            )
            if probe_budget < _HTTP_MIN_REQUEST_BUDGET:
                raise direct_error
            prefix = self.mirror.get_best(timeout=probe_budget) or ""
    except Exception:
        raise direct_error

    if not prefix:
        raise direct_error

    remaining = deadline - _time.monotonic()
    if remaining <= _HTTP_MIN_REQUEST_BUDGET:
        raise direct_error
    response = self.session.get(
        str(prefix).rstrip(chr(47)) + "/" + str(url),
        params=params,
        timeout=_bounded_timeout(timeout, remaining, 12.0),
    )
    response.raise_for_status()
    return response


def _optimized_httpclient_get(self, url: str, params=None, timeout=20, force_refresh=False):
    """提供内存缓存、持久化缓存和相同请求去重，同时保留总超时控制。"""
    _ensure_http_cache_state(self)
    cache_key = _build_http_cache_key(self, url, params)
    cache_ttl = _http_cache_ttl(self, url)
    requested_timeout = _timeout_number(timeout, 12.0)
    total_timeout = min(
        max(requested_timeout, _HTTP_MIN_REQUEST_BUDGET),
        _HTTP_TOTAL_TIMEOUT_CAP,
    )

    with self._cache_lock:
        request_epoch = self._cache_epoch

    if not force_refresh:
        cached = _memory_cache_get(self, cache_key, cache_ttl)
        if cached is not None:
            return cached
        cached = _load_persistent_http_cache(self, cache_key)
        if cached is not None:
            with self._cache_lock:
                if self._cache_epoch == request_epoch:
                    return cached

    # 清理缓存或切换配置后，新的请求使用新的代数，旧任务不会被合并进来。
    with self._cache_lock:
        request_epoch = self._cache_epoch
        if not force_refresh:
            cached = _memory_cache_get(self, cache_key, cache_ttl)
            if cached is not None:
                return cached
        inflight_key = (request_epoch, cache_key)
        pending = self._inflight_requests.get(inflight_key)
        if pending is None:
            pending = _HttpInflightRequest()
            self._inflight_requests[inflight_key] = pending
            request_owner = True
        else:
            request_owner = False

    if not request_owner:
        if not pending.event.wait(total_timeout):
            raise TimeoutError("等待相同网络请求超时，请稍后重试")
        if pending.error is not None:
            raise pending.error
        if pending.response is not None:
            return pending.response
        raise RuntimeError("网络请求未返回有效结果，请稍后重试")

    try:
        response = _request_http_without_cache(self, url, params=params, timeout=timeout)
    except BaseException as exc:
        with self._cache_lock:
            pending.error = exc
            self._inflight_requests.pop(inflight_key, None)
        pending.event.set()
        raise

    with self._cache_lock:
        cache_is_current = self._cache_epoch == request_epoch
    can_cache = (
        cache_is_current
        and int(getattr(response, "status_code", 0) or 0) == 200
    )
    if can_cache:
        _memory_cache_put(self, cache_key, response)

    with self._cache_lock:
        pending.response = response
        self._inflight_requests.pop(inflight_key, None)
    pending.event.set()

    if can_cache:
        _save_persistent_http_cache(self, cache_key, response, cache_ttl, request_epoch)
    return response


# ------------------------------ 批量翻译缓存与去重 ------------------------------

_ORIGINAL_GITHUBSERVICE_BATCH_TRANSLATE = GitHubService.batch_translate


def _translation_cache_key(target_language, text: str) -> str:
    """按版本、目标语言和原文生成统一翻译缓存键。"""
    return (
        f"desc_{README_TRANSLATION_CACHE_VERSION}::"
        f"{target_language}::{text}"
    )


def _read_translation_cache_value(self, key: str, source: str):
    """按数据库、内存缓存顺序读取有效翻译。"""
    database = getattr(self, "db", None)
    get_translation = getattr(database, "get_translation", None)
    if callable(get_translation):
        try:
            value = get_translation(key)
        except Exception:
            value = None
        if isinstance(value, str) and _is_valid_translation(source, value):
            return value

    cache = getattr(self, "cache", None)
    get_cached = getattr(cache, "get", None)
    if callable(get_cached):
        try:
            value = get_cached(key)
        except Exception:
            value = None
        if isinstance(value, str) and _is_valid_translation(source, value):
            return value
    return None


def _write_translation_cache_value(self, key: str, value: str) -> None:
    """把有效翻译写入内存缓存和数据库，缓存异常不阻断界面展示。"""
    cache = getattr(self, "cache", None)
    set_cached = getattr(cache, "set", None)
    if callable(set_cached):
        try:
            set_cached(key, value)
        except Exception:
            pass

    database = getattr(self, "db", None)
    set_translation = getattr(database, "set_translation", None)
    if callable(set_translation):
        try:
            set_translation(key, value)
        except Exception:
            pass


def _batch_translate_with_cache(self, texts: list[str]) -> list[str]:
    """复用翻译缓存并按原顺序返回结果，保持原有批量请求逻辑。"""
    if not texts:
        return []

    config = getattr(self, "config", {}) or {}
    target_language = config.get("target_language", "zh-CN")
    if not target_language:
        target_language = "zh-CN"

    translatable_texts = [text for text in texts if text and text.strip()]
    if not translatable_texts:
        return texts

    unique_texts = list(dict.fromkeys(translatable_texts))
    translated_map = {}
    missing_texts = []
    cache_keys = {}

    for text in unique_texts:
        cache_key = _translation_cache_key(target_language, text)
        cache_keys[text] = cache_key
        cached = _read_translation_cache_value(self, cache_key, text)
        if cached is None:
            missing_texts.append(text)
        else:
            translated_map[text] = cached

    if missing_texts:
        translated_values = _ORIGINAL_GITHUBSERVICE_BATCH_TRANSLATE(
            self,
            missing_texts,
        )
        try:
            translated_values = list(translated_values or [])
        except TypeError:
            translated_values = []

        for index, source in enumerate(missing_texts):
            result = (
                translated_values[index]
                if index < len(translated_values)
                else ""
            )
            if isinstance(result, str) and _is_valid_translation(source, result):
                translated_map[source] = result
                _write_translation_cache_value(self, cache_keys[source], result)
            else:
                translated_map[source] = source

    return [
        translated_map.get(text, text)
        if text and text.strip()
        else text
        for text in texts
    ]


