def _optimized_probe_mirror(self, mirror, timeout=None):
    """限制单个镜像测速的连接和读取总等待时间。"""
    requested = _timeout_number(
        timeout,
        _timeout_number(getattr(self, "probe_timeout", None), 3.0),
    )
    safe_timeout = min(
        max(requested, _HTTP_MIN_REQUEST_BUDGET),
        _HTTP_MIRROR_PROBE_TIMEOUT_CAP,
    )
    # 原实现会把连接和读取分别设置为同样的时长，这里传入一半，保持总预算不变。
    return _ORIGINAL_MIRROR_PROBE_MIRROR(
        self,
        mirror,
        timeout=safe_timeout / 2.0,
    )


def _optimized_probe_mirrors(self, timeout=None):
    """限制镜像测速的总等待时间，避免测速任务拖住界面请求。"""
    requested = _timeout_number(
        timeout,
        _timeout_number(getattr(self, "probe_timeout", None), 3.0),
    )
    safe_timeout = min(
        max(requested, _HTTP_MIN_REQUEST_BUDGET),
        _HTTP_MIRROR_PROBE_TIMEOUT_CAP,
    )
    return _ORIGINAL_MIRROR_PROBE_MIRRORS(self, timeout=safe_timeout)


MirrorManager.probe_mirror = _optimized_probe_mirror
