def _current_async_view(self):
    """安全读取当前页面，窗口尚未完成初始化时返回空值。"""
    try:
        return self.view_combo.currentData()
    except Exception:
        return None


def _capture_async_context(self):
    """记录任务所属的页面请求上下文。"""
    return tuple(getattr(self, name, None) for name in _ASYNC_CONTEXT_ATTRS) + (
        _current_async_view(self),
    )


def _is_async_ids_current(self, context) -> bool:
    """只使用普通请求编号判断后台任务，避免工作线程读取 Qt 控件。"""
    return tuple(
        getattr(self, name, None)
        for name in _ASYNC_CONTEXT_ATTRS
    ) == context[:len(_ASYNC_CONTEXT_ATTRS)]


def _is_async_context_current(self, context) -> bool:
    """在界面回调中同时核对请求编号和当前页面。"""
    return (
        _is_async_ids_current(self, context)
        and _current_async_view(self) == context[-1]
    )


_ORIGINAL_MAINWINDOW_RUN_IN_THREAD = MainWindow.run_in_thread


def _optimized_run_in_thread(self, fn, on_done=None, on_error=None):
    """让排队任务在执行前和回调前都检查上下文，过期任务只结束自身。"""
    context = _capture_async_context(self)

    def guarded_task():
        if not _is_async_ids_current(self, context):
            return _STALE_TASK_RESULT
        return fn()

    def guarded_done(result):
        if result is _STALE_TASK_RESULT:
            return
        if not _is_async_context_current(self, context):
            return
        if on_done:
            on_done(result)

    def guarded_error(message):
        if not _is_async_context_current(self, context):
            return
        if on_error:
            on_error(message)

    return _ORIGINAL_MAINWINDOW_RUN_IN_THREAD(
        self,
        guarded_task,
        guarded_done,
        guarded_error,
    )


MainWindow.run_in_thread = _optimized_run_in_thread

# ------------------------------ 详情页图片加载优化 ------------------------------

_ORIGINAL_GITHUBSERVICE_DOWNLOAD_README_IMAGE = GitHubService._download_readme_image
_README_IMAGE_CACHE_LIMIT = 128
_README_IMAGE_FAILURE_CACHE_LIMIT = 256
_README_IMAGE_FAILURE_TTL = 8.0
_README_IMAGE_TIMEOUT_MIN = 0.75
_README_IMAGE_TIMEOUT_CAP = 2.5
_README_IMAGE_WAIT_GRACE = 0.5
_README_IMAGE_STATE_INIT_LOCK = _threading.Lock()


def _ensure_readme_image_state(service):
    '''补齐图片请求共享状态，避免旧实例或测试对象缺少属性。'''
    with _README_IMAGE_STATE_INIT_LOCK:
        image_lock = getattr(service, '_readme_image_cache_lock', None)
        if not callable(getattr(image_lock, 'acquire', None)):
            image_lock = _threading.Lock()
            setattr(service, '_readme_image_cache_lock', image_lock)

        image_cache = getattr(service, '_readme_image_cache', None)
        if not isinstance(image_cache, dict):
            image_cache = {}
            setattr(service, '_readme_image_cache', image_cache)

        inflight = getattr(service, '_readme_image_inflight', None)
        if not isinstance(inflight, dict):
            inflight = {}
            setattr(service, '_readme_image_inflight', inflight)

        failures = getattr(service, '_readme_image_failures', None)
        if not isinstance(failures, dict):
            failures = {}
            setattr(service, '_readme_image_failures', failures)
    return image_lock, image_cache, inflight, failures


def _readme_image_timeout(service, timeout) -> float:
    '''把单张图片请求限制在较小的等待预算内。'''
    config = getattr(service, 'config', {}) or {}
    configured = config.get('readme_image_timeout', timeout)
    try:
        requested = float(configured)
    except (TypeError, ValueError):
        requested = _README_IMAGE_TIMEOUT_CAP
    if requested <= 0:
        requested = _README_IMAGE_TIMEOUT_CAP
    return min(
        max(requested, _README_IMAGE_TIMEOUT_MIN),
        _README_IMAGE_TIMEOUT_CAP,
    )


def _readme_image_cache_get(image_lock, image_cache, url: str) -> str:
    '''读取并刷新图片缓存，保持缓存大小可控。'''
    with image_lock:
        value = image_cache.get(url)
        if isinstance(value, str) and value:
            # 命中后移到末尾，形成轻量的最近最少使用淘汰顺序。
            image_cache.pop(url, None)
            image_cache[url] = value
            return value
    return ''


def _readme_image_cache_put(image_lock, image_cache, url: str, value: str) -> None:
    '''写入图片缓存并淘汰最早未使用的条目。'''
    if not isinstance(value, str) or not value:
        return
    with image_lock:
        image_cache.pop(url, None)
        image_cache[url] = value
        while len(image_cache) > _README_IMAGE_CACHE_LIMIT:
            oldest = next(iter(image_cache), None)
            if oldest is None:
                break
            image_cache.pop(oldest, None)


def _trim_readme_image_failures(image_lock, failures, now: float) -> None:
    '''清除过期失败记录，避免失败缓存无限增长。'''
    with image_lock:
        for key, expires_at in list(failures.items()):
            if not isinstance(expires_at, (int, float)) or expires_at <= now:
                failures.pop(key, None)
        overflow = len(failures) - _README_IMAGE_FAILURE_CACHE_LIMIT
        if overflow > 0:
            for key in list(failures)[:overflow]:
                failures.pop(key, None)


def _optimized_download_readme_image(self, url: str, timeout: float = 3.0) -> str:
    '''图片请求增加并发去重、失败短缓存和总等待上限。'''
    normalized_url = str(url or '').strip()
    if not normalized_url:
        return ''

    image_lock, image_cache, inflight, failures = _ensure_readme_image_state(self)
    cached = _readme_image_cache_get(image_lock, image_cache, normalized_url)
    if cached:
        return cached

    safe_timeout = _readme_image_timeout(self, timeout)
    now = _time.monotonic()
    owner = False
    pending = None
    with image_lock:
        failure_until = failures.get(normalized_url, 0.0)
        if isinstance(failure_until, (int, float)) and failure_until > now:
            return ''
        failures.pop(normalized_url, None)

        pending = inflight.get(normalized_url)
        if pending is None:
            pending = {
                'event': _threading.Event(),
                'result': '',
            }
            inflight[normalized_url] = pending
            owner = True

    if not owner:
        # 等待同一图片的首个请求，超时后直接保留远程地址，不再重复发起请求。
        wait_budget = min(
            max(safe_timeout + _README_IMAGE_WAIT_GRACE, 1.0),
            _README_IMAGE_TIMEOUT_CAP + 1.0,
        )
        if not pending['event'].wait(wait_budget):
            return ''
        cached = _readme_image_cache_get(image_lock, image_cache, normalized_url)
        if cached:
            return cached
        result = pending.get('result', '')
        return result if isinstance(result, str) else ''

    result = ''
    try:
        result = _ORIGINAL_GITHUBSERVICE_DOWNLOAD_README_IMAGE(
            self,
            normalized_url,
            safe_timeout,
        )
        if not isinstance(result, str) or not result.startswith('data:'):
            result = ''
    except Exception:
        # 单图失败不向上抛出，嵌入流程会继续保留原始远程地址。
        result = ''
    finally:
        completed_at = _time.monotonic()
        if result:
            _readme_image_cache_put(
                image_lock,
                image_cache,
                normalized_url,
                result,
            )
        with image_lock:
            if result:
                failures.pop(normalized_url, None)
            else:
                failures[normalized_url] = completed_at + _README_IMAGE_FAILURE_TTL
            pending['result'] = result
            inflight.pop(normalized_url, None)
        if not result:
            try:
                _trim_readme_image_failures(image_lock, failures, completed_at)
            except Exception:
                pass
        pending['event'].set()
    return result


GitHubService._download_readme_image = _optimized_download_readme_image

# ------------------------------ 后台任务协作式取消与详情状态收敛 ------------------------------

_DETAIL_STAGE_NAMES = frozenset(("readme", "release", "image", "translation"))
_DETAIL_WATCHDOG_MS = 20_000
_DETAIL_CONTEXT_INDEX = _ASYNC_CONTEXT_ATTRS.index("_detail_request_id")
_ASYNC_TASK_STATE_INIT_LOCK = _threading.Lock()


class _AsyncTaskHandle:
    """保存后台任务的取消状态、请求上下文和所属详情阶段。"""

    __slots__ = (
        "context",
        "stage",
        "detail_request_id",
        "cancel_event",
        "worker",
        "cancelled",
        "finished",
        "lock",
    )

    def __init__(self, context, stage=None):
        self.context = context
        self.stage = stage
        self.detail_request_id = context[_DETAIL_CONTEXT_INDEX]
        self.cancel_event = _threading.Event()
        self.worker = None
        self.cancelled = False
        self.finished = False
        self.lock = _threading.Lock()

    def cancel(self):
        with self.lock:
            self.cancelled = True
        self.cancel_event.set()

    def is_cancelled(self) -> bool:
        return self.cancel_event.is_set() or self.cancelled


def _ensure_async_task_state(window):
    """初始化后台任务集合，兼容旧窗口实例和测试对象。"""
    with _ASYNC_TASK_STATE_INIT_LOCK:
        task_lock = getattr(window, "_async_task_lock", None)
        if not callable(getattr(task_lock, "acquire", None)):
            task_lock = _threading.RLock()
            setattr(window, "_async_task_lock", task_lock)

        active_tasks = getattr(window, "_active_async_tasks", None)
        if not isinstance(active_tasks, set):
            active_tasks = set()
            setattr(window, "_active_async_tasks", active_tasks)

        stage_hints = getattr(window, "_detail_stage_hints", None)
        if not isinstance(stage_hints, list):
            setattr(window, "_detail_stage_hints", [])

        submit_seq = getattr(window, "_async_submit_seq", None)
        if not isinstance(submit_seq, int):
            setattr(window, "_async_submit_seq", 0)
    return task_lock, active_tasks


def _take_detail_stage_hint(window, context):
    """取出详情流程为下一次任务提交准备的阶段标记。"""
    if context[_DETAIL_CONTEXT_INDEX] is None:
        return None
    _ensure_async_task_state(window)
    hints = getattr(window, "_detail_stage_hints", None)
    if not isinstance(hints, list) or not hints:
        return None
    stage = hints.pop(0)
    return stage if stage in _DETAIL_STAGE_NAMES else None


def _set_detail_stage_hints(window, stages):
    """临时设置详情阶段提示，调用结束后由外层恢复。"""
    _ensure_async_task_state(window)
    previous = getattr(window, "_detail_stage_hints", [])
    window._detail_stage_hints = list(stages)
    return previous


def _restore_detail_stage_hints(window, previous):
    if isinstance(previous, list):
        window._detail_stage_hints = previous
    else:
        window._detail_stage_hints = []


def _finish_async_task(window, handle) -> bool:
    """只完成一次任务收尾，避免取消和 Qt 回调重复扣减忙碌计数。"""
    task_lock, active_tasks = _ensure_async_task_state(window)
    with handle.lock:
        if handle.finished:
            return False
        handle.finished = True
    with task_lock:
        active_tasks.discard(handle)

    window._busy_count = max(0, int(getattr(window, "_busy_count", 0)) - 1)
    heartbeat = getattr(window, "_heartbeat", None)
    if window._busy_count == 0 and heartbeat is not None:
        try:
            heartbeat.stop()
        except Exception:
            pass
    try:
        window._update_busy_indicator()
    except Exception:
        pass
    return True


def _detail_state_matches(window, request_id, repo=None) -> bool:
    state = getattr(window, "_detail_load_state", None)
    if not isinstance(state, dict):
        return False
    if state.get("request_id") != request_id:
        return False
    if getattr(window, "_detail_request_id", None) != request_id:
        return False
    if repo is not None and state.get("repo") is not repo:
        return False
    return True


def _safe_set_detail_status(window, text: str) -> None:
    """统一更新详情状态，控件尚未创建时静默跳过。"""
    try:
        label = getattr(window, "status_label", None)
        if label is not None:
            label.setText(str(text))
    except Exception:
        pass
    try:
        setter = getattr(window, "_set_detail_status", None)
        if callable(setter):
            setter(str(text))
    except Exception:
        pass


def _stop_translation_ui(window) -> None:
    """停止翻译动画并恢复按钮，防止页面一直显示翻译中。"""
    try:
        timer = getattr(window, "_translate_spinner_timer", None)
        if timer is not None:
            timer.stop()
    except Exception:
        pass
    try:
        button = getattr(window, "translate_btn", None)
        if button is not None:
            button.setText("翻译详情")
            button.setEnabled(True)
    except Exception:
        pass


def _stop_detail_watchdog(window) -> None:
    timer = getattr(window, "_detail_load_watchdog", None)
    if timer is not None:
        try:
            timer.stop()
        except Exception:
            pass


def _detail_stage_info(window, stage, request_id=None):
    state = getattr(window, "_detail_load_state", None)
    if not isinstance(state, dict):
        return None
    if request_id is not None and state.get("request_id") != request_id:
        return None
    stages = state.get("stages")
    if not isinstance(stages, dict):
        return None
    info = stages.get(stage)
    return info if isinstance(info, dict) else None


def _prepare_detail_stage(window, stage, request_id, source_html=None) -> bool:
    """准备一个详情阶段，支持用户在初次加载后再次点击翻译。"""
    if not _detail_state_matches(window, request_id):
        return False
    state = window._detail_load_state
    state["finalized"] = False
    state["timed_out"] = False
    info = _detail_stage_info(window, stage, request_id)
    if info is None:
        return False
    info.update(
        submitted=False,
        done=False,
        skipped=False,
        ok=None,
        issue=False,
    )
    if source_html is not None:
        info["source_html"] = source_html
    _start_detail_watchdog(window, request_id)
    return True


def _complete_unsent_detail_stage(window, stage, request_id) -> None:
    """阶段没有实际任务时立即标记为跳过，避免看门狗无意义等待。"""
    if not _detail_state_matches(window, request_id):
        return
    info = _detail_stage_info(window, stage, request_id)
    if info is None or info.get("submitted") or info.get("done"):
        return
    info.update(done=True, skipped=True, ok=True, issue=False)
    _maybe_finalize_detail_state(window)


def _mark_detail_stage_submitted(window, handle) -> None:
    stage = handle.stage
    if stage not in _DETAIL_STAGE_NAMES:
        return
    if not _detail_state_matches(window, handle.detail_request_id):
        return
    info = _detail_stage_info(window, stage, handle.detail_request_id)
    if info is not None:
        info["submitted"] = True
        info["done"] = False
        info["skipped"] = False


def _mark_detail_stage_finished(window, handle, result=None, success=True) -> None:
    """记录阶段结果，统一处理 README、下载、图片和翻译状态。"""
    stage = handle.stage
    if stage not in _DETAIL_STAGE_NAMES:
        return
    if not _detail_state_matches(window, handle.detail_request_id):
        return
    info = _detail_stage_info(window, stage, handle.detail_request_id)
    if info is None:
        return

    info["done"] = True
    info["skipped"] = False
    info["ok"] = bool(success)
    info["issue"] = not bool(success)

    if stage == "readme":
        available = False
        readme_error = not success
        if isinstance(result, dict):
            readme_value = result.get("readme")
            available = bool(isinstance(readme_value, str) and readme_value.strip())
            readme_error = readme_error or bool(result.get("error"))
        info["available"] = available
        info["issue"] = bool(readme_error or not available)
        if not success:
            image_info = _detail_stage_info(window, "image", handle.detail_request_id)
            if image_info is not None and not image_info.get("submitted"):
                image_info.update(done=True, skipped=True, ok=True, issue=False)
    elif stage == "release":
        info["issue"] = not bool(success)
    elif stage == "image":
        source_html = str(info.get("source_html") or "")
        result_html = result if isinstance(result, str) else ""
        unchanged_with_image = bool(
            source_html
            and "<img" in source_html.lower()
            and result_html == source_html
        )
        info["issue"] = not bool(success and result_html) or unchanged_with_image
    elif stage == "translation":
        translation_error = False
        if isinstance(result, dict):
            translation_error = bool(result.get("translation_error"))
        info["issue"] = bool((not success) or translation_error)


def _maybe_finalize_detail_state(window) -> None:
    """所有阶段结束后给出唯一的详情最终状态。"""
    state = getattr(window, "_detail_load_state", None)
    if not isinstance(state, dict) or state.get("finalized"):
        return
    stages = state.get("stages")
    if not isinstance(stages, dict):
        return
    if any(not isinstance(item, dict) or not item.get("done") for item in stages.values()):
        return

    state["finalized"] = True
    _stop_detail_watchdog(window)
    _stop_translation_ui(window)

    problems = []
    if stages.get("readme", {}).get("issue"):
        problems.append("README 暂不可用")
    if stages.get("release", {}).get("issue"):
        problems.append("下载资源暂不可用")
    if stages.get("image", {}).get("issue"):
        problems.append("部分图片未能嵌入")
    if stages.get("translation", {}).get("issue"):
        problems.append("翻译服务暂时不可用，已保留原文")

    message = "详情加载完成"
    if problems:
        message += "，" + "；".join(problems)
    _safe_set_detail_status(window, message)


def _start_detail_watchdog(window, request_id) -> None:
    if not _detail_state_matches(window, request_id):
        return
    timer = getattr(window, "_detail_load_watchdog", None)
    if timer is None:
        try:
            timer = _QTimer(window)
            timer.setSingleShot(True)
            timer.timeout.connect(lambda: _detail_watchdog_timeout(window))
            window._detail_load_watchdog = timer
        except Exception:
            return
    try:
        timer.start(_DETAIL_WATCHDOG_MS)
    except Exception:
        pass


def _detail_watchdog_timeout(window) -> None:
    state = getattr(window, "_detail_load_state", None)
    if not isinstance(state, dict) or state.get("finalized"):
        return
    request_id = state.get("request_id")
    if not _detail_state_matches(window, request_id):
        return

    _cancel_async_tasks(
        window,
        lambda handle: (
            handle.stage in _DETAIL_STAGE_NAMES
            and handle.detail_request_id == request_id
        ),
    )
    state["timed_out"] = True
    state["finalized"] = True
    for info in state.get("stages", {}).values():
        if isinstance(info, dict) and not info.get("done"):
            info.update(done=True, skipped=True, ok=False, issue=False)
    _stop_detail_watchdog(window)
    _stop_translation_ui(window)
    _safe_set_detail_status(window, "详情加载超时，已显示已获取内容")


def _cancel_async_tasks(window, predicate=None) -> int:
    """设置取消事件，并尽量从线程池移除尚未开始的任务。"""
    task_lock, active_tasks = _ensure_async_task_state(window)
    with task_lock:
        handles = list(active_tasks)

    thread_pool = getattr(window, "thread_pool", None)
    cancelled_count = 0
    for handle in handles:
        if predicate is not None:
            try:
                if not predicate(handle):
                    continue
            except Exception:
                continue
        handle.cancel()
        cancelled_count += 1
        removed = False
        if thread_pool is not None and handle.worker is not None:
            try:
                removed = bool(thread_pool.tryTake(handle.worker))
            except Exception:
                removed = False
        if removed:
            _finish_async_task(window, handle)
    return cancelled_count


def _cancel_all_async_tasks(window) -> int:
    return _cancel_async_tasks(window)


def _cancelable_run_in_thread(self, fn, on_done=None, on_error=None):
    """提交可取消后台任务，旧请求不会继续占用排队线程并污染页面。"""
    context = _capture_async_context(self)
    stage = _take_detail_stage_hint(self, context)
    _ensure_async_task_state(self)
    self._async_submit_seq = int(getattr(self, "_async_submit_seq", 0)) + 1

    handle = _AsyncTaskHandle(context, stage)

    def guarded_task():
        if handle.is_cancelled() or not _is_async_ids_current(self, context):
            return _STALE_TASK_RESULT
        result = fn()
        if handle.is_cancelled() or not _is_async_ids_current(self, context):
            return _STALE_TASK_RESULT
        return result

    worker = Worker(guarded_task)
    handle.worker = worker
    try:
        worker._async_task_handle = handle
    except Exception:
        pass
    _mark_detail_stage_submitted(self, handle)

    task_lock, active_tasks = _ensure_async_task_state(self)
    with task_lock:
        active_tasks.add(handle)

    self._busy_count = int(getattr(self, "_busy_count", 0)) + 1
    try:
        self._update_busy_indicator()
    except Exception:
        pass

    # 后台任务通过线程池信号回到界面线程，不再用定时器反复调用
    # QApplication.processEvents，避免重入和无意义的高频空转。

    def handle_result(result):
        if not _finish_async_task(self, handle):
            return
        if handle.is_cancelled() or result is _STALE_TASK_RESULT:
            return
        _mark_detail_stage_finished(self, handle, result, True)
        if not _is_async_context_current(self, context):
            return
        try:
            if on_done:
                on_done(result)
        finally:
            _maybe_finalize_detail_state(self)

    def handle_error(message):
        if not _finish_async_task(self, handle):
            return
        if handle.is_cancelled():
            return
        _mark_detail_stage_finished(self, handle, None, False)
        if not _is_async_context_current(self, context):
            return
        try:
            if on_error:
                on_error(message)
            else:
                message_box = globals().get("QMessageBox")
                if message_box is not None:
                    message_box.warning(self, "请求失败", str(message))
        finally:
            _maybe_finalize_detail_state(self)

    worker.signals.result.connect(handle_result)
    worker.signals.error.connect(handle_error)
    try:
        self.thread_pool.start(worker)
    except Exception as exc:
        handle.cancel()
        _finish_async_task(self, handle)
        _mark_detail_stage_finished(self, handle, None, False)
        if on_error:
            on_error(str(exc))
        else:
            message_box = globals().get("QMessageBox")
            if message_box is not None:
                message_box.warning(self, "请求失败", str(exc))
        _maybe_finalize_detail_state(self)
    return handle


_ORIGINAL_MAINWINDOW_INVALIDATE_DETAIL_REQUEST_FOR_CANCEL = MainWindow._invalidate_detail_request
_ORIGINAL_MAINWINDOW_CLOSE_EVENT_FOR_CANCEL = MainWindow.closeEvent
_ORIGINAL_MAINWINDOW_DETAIL_LOAD_FOR_STATE = MainWindow._load_detail_content
_ORIGINAL_MAINWINDOW_DETAIL_IMAGE_FOR_STATE = MainWindow._start_detail_image_embedding
_ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_FOR_STATE = MainWindow._start_detail_translation


def _invalidate_detail_request_with_cancel(self):
    """切换项目时只取消旧详情任务，不影响搜索和热榜任务。"""
    old_request_id = getattr(self, "_detail_request_id", None)
    if old_request_id is not None:
        _cancel_async_tasks(
            self,
            lambda handle: (
                handle.stage in _DETAIL_STAGE_NAMES
                and handle.detail_request_id == old_request_id
            ),
        )
    _stop_detail_watchdog(self)
    result = _ORIGINAL_MAINWINDOW_INVALIDATE_DETAIL_REQUEST_FOR_CANCEL(self)
    self._detail_load_state = None
    return result


def _load_detail_content_with_state(self, repo, request_id):
    """建立详情阶段状态并为 README、下载任务安装阶段标记。"""
    _ensure_async_task_state(self)
    self._detail_load_state = {
        "request_id": request_id,
        "repo": repo,
        "finalized": False,
        "timed_out": False,
        "stages": {
            stage: {
                "submitted": False,
                "done": False,
                "skipped": False,
                "ok": None,
                "issue": False,
            }
            for stage in _DETAIL_STAGE_NAMES
        },
    }
    _safe_set_detail_status(self, "正在加载详情…")
    _start_detail_watchdog(self, request_id)
    previous = _set_detail_stage_hints(self, ["readme", "release"])
    try:
        return _ORIGINAL_MAINWINDOW_DETAIL_LOAD_FOR_STATE(self, repo, request_id)
    finally:
        _restore_detail_stage_hints(self, previous)


def _start_detail_image_embedding_with_state(self, repo, request_id, rendered_html):
    """登记 README 图片阶段；没有图片时立即结束该阶段。"""
    manage_state = _detail_state_matches(self, request_id, repo)
    if not manage_state:
        return _ORIGINAL_MAINWINDOW_DETAIL_IMAGE_FOR_STATE(
            self, repo, request_id, rendered_html
        )
    _prepare_detail_stage(self, "image", request_id, rendered_html)
    previous = _set_detail_stage_hints(self, ["image"])
    before = int(getattr(self, "_async_submit_seq", 0))
    try:
        return _ORIGINAL_MAINWINDOW_DETAIL_IMAGE_FOR_STATE(
            self, repo, request_id, rendered_html
        )
    finally:
        _restore_detail_stage_hints(self, previous)
        if int(getattr(self, "_async_submit_seq", 0)) == before:
            _complete_unsent_detail_stage(self, "image", request_id)


def _start_detail_translation_with_state(self, repo, request_id, source_readme):
    """登记翻译阶段，复用已有加载状态并支持再次手动翻译。"""
    already_running = bool(getattr(self, "_detail_translation_running", False))
    manage_state = (
        not already_running
        and _detail_state_matches(self, request_id, repo)
    )
    if not manage_state:
        return _ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_FOR_STATE(
            self, repo, request_id, source_readme
        )
    _prepare_detail_stage(self, "translation", request_id)
    previous = _set_detail_stage_hints(self, ["translation"])
    before = int(getattr(self, "_async_submit_seq", 0))
    try:
        return _ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_FOR_STATE(
            self, repo, request_id, source_readme
        )
    finally:
        _restore_detail_stage_hints(self, previous)
        if int(getattr(self, "_async_submit_seq", 0)) == before:
            _complete_unsent_detail_stage(self, "translation", request_id)


def _close_event_with_cancel(self, event):
    """退出程序前取消所有后台任务，避免窗口关闭后仍有回调。"""
    _cancel_all_async_tasks(self)
    _stop_detail_watchdog(self)
    _stop_translation_ui(self)
    return _ORIGINAL_MAINWINDOW_CLOSE_EVENT_FOR_CANCEL(self, event)


MainWindow.run_in_thread = _cancelable_run_in_thread
MainWindow._invalidate_detail_request = _invalidate_detail_request_with_cancel
MainWindow._load_detail_content = _load_detail_content_with_state
MainWindow._start_detail_image_embedding = _start_detail_image_embedding_with_state
MainWindow._start_detail_translation = _start_detail_translation_with_state
MainWindow.closeEvent = _close_event_with_cancel
MainWindow.cancel_background_tasks = _cancel_all_async_tasks



# ------------------------------ 项目列表分批渲染优化 ------------------------------
_LIST_RENDER_BATCH_SIZE = 16
_LIST_RENDER_INTERVAL_MS = 16


def _list_render_attributes(kind):
    if kind == "discover":
        return (
            "_discover_items_render_timer",
            "_discover_items_render_state",
        )
    return (
        "_trending_items_render_timer",
        "_trending_items_render_state",
    )


def _stop_incremental_list_render(window, kind) -> None:
    """停止指定列表的分批渲染，并清除尚未显示的项目。"""
    timer_attr, state_attr = _list_render_attributes(kind)
    timer = getattr(window, timer_attr, None)
    if timer is not None:
        try:
            timer.stop()
        except Exception:
            pass
    setattr(window, state_attr, None)


def _append_incremental_list_item(window, kind, repo) -> None:
    """在界面线程中创建并加入一个项目条目。"""
    if kind == "discover":
        brief = window._repo_list_brief(repo)
        language = repo.get("language", "")
        text = (
            f"⭐{repo.get('stars', 0)}  {repo.get('full_name', '')}  {language}\n"
            f"{brief}"
        )
        item = QListWidgetItem(text)
        window._set_repo_item_metadata(item, repo)
        window.repo_list.addItem(item)
        return

    rank_change = repo.get("rank_change", {})
    if rank_change.get("is_new"):
        prefix = "🆕"
    elif rank_change.get("change", 0) > 0:
        prefix = f"🔺{rank_change['change']}"
    elif rank_change.get("change", 0) < 0:
        prefix = f"🔻{abs(rank_change['change'])}"
    else:
        prefix = "➖"
    stars_text = (
        f"⭐{repo.get('period_stars', 0)}"
        if repo.get("period_stars")
        else ""
    )
    brief = window._repo_list_brief(repo)
    language = repo.get("language", "")
    text = (
        f"{prefix} #{repo.get('rank', '-')}  ⭐{repo.get('stars', 0)} "
        f"{stars_text}  {repo.get('full_name', '')}  {language}\n{brief}"
    )
    item = QListWidgetItem(text)
    window._set_repo_item_metadata(item, repo)
    window.trending_list.addItem(item)


def _render_next_incremental_list_batch(window, kind) -> None:
    """按固定批次推进列表渲染，避免一次性创建大量控件。"""
    timer_attr, state_attr = _list_render_attributes(kind)
    state = getattr(window, state_attr, None)
    if not isinstance(state, dict):
        timer = getattr(window, timer_attr, None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        return

    items = state.get("items", [])
    try:
        index = max(0, int(state.get("index", 0)))
    except (TypeError, ValueError):
        index = 0
    end = min(len(items), index + _LIST_RENDER_BATCH_SIZE)

    while index < end:
        repo = items[index]
        index += 1
        try:
            _append_incremental_list_item(window, kind, repo)
        except Exception:
            _write_startup_log("项目列表条目渲染失败", _sys.exc_info())

    state["index"] = index
    try:
        window._update_list_summary()
    except Exception:
        pass

    if index < len(items):
        return

    timer = getattr(window, timer_attr, None)
    if timer is not None:
        try:
            timer.stop()
        except Exception:
            pass
    try:
        list_widget = state.get("list_widget")
        if list_widget is not None:
            window._restore_list_state(
                list_widget,
                items,
                state.get("saved_state"),
            )
    except Exception:
        _write_startup_log("项目列表渲染完成后恢复界面状态失败", _sys.exc_info())
    setattr(window, state_attr, None)


def _start_incremental_list_render(window, kind, list_widget, repos, saved_state) -> None:
    """启动指定列表的可取消分批渲染。"""
    timer_attr, state_attr = _list_render_attributes(kind)
    items = list(repos or [])
    state = {
        "items": items,
        "index": 0,
        "saved_state": saved_state,
        "list_widget": list_widget,
    }
    setattr(window, state_attr, state)

    timer = getattr(window, timer_attr, None)
    if timer is None:
        try:
            timer = _QTimer(window)
            timer.setInterval(_LIST_RENDER_INTERVAL_MS)
            timer.timeout.connect(
                lambda render_window=window, render_kind=kind:
                _render_next_incremental_list_batch(render_window, render_kind)
            )
            setattr(window, timer_attr, timer)
        except Exception:
            _write_startup_log("无法创建项目列表分批渲染计时器", _sys.exc_info())
            while isinstance(getattr(window, state_attr, None), dict):
                _render_next_incremental_list_batch(window, kind)
            return

    _render_next_incremental_list_batch(window, kind)
    if isinstance(getattr(window, state_attr, None), dict):
        try:
            timer.start()
        except Exception:
            _write_startup_log("无法启动项目列表分批渲染计时器", _sys.exc_info())


def _render_discover_items_incrementally(self, repos):
    """分批绘制项目列表，保留原有的选择项和滚动位置。"""
    state = self._capture_list_state(self.repo_list)
    self._stop_search_rendering()
    self.repo_list.clear()
    _start_incremental_list_render(self, "discover", self.repo_list, repos, state)


def _render_trending_items_incrementally(self, repos):
    """分批绘制热榜列表，保留原有的选择项和滚动位置。"""
    state = self._capture_list_state(self.trending_list)
    self._stop_trending_rendering()
    self.trending_list.clear()
    _start_incremental_list_render(
        self,
        "trending",
        self.trending_list,
        repos,
        state,
    )


_ORIGINAL_STOP_SEARCH_RENDERING_FOR_INCREMENTAL_LIST = MainWindow._stop_search_rendering
_ORIGINAL_STOP_TRENDING_RENDERING_FOR_INCREMENTAL_LIST = MainWindow._stop_trending_rendering


