# ------------------------------ 列表默认置顶与主题切换顺滑优化 ------------------------------
from PyQt6.QtCore import Qt as _Qt

_LIST_DEFAULT_TOP_STATE = ("", 0, False)
_LIST_SCROLL_STATE_UNSET = object()
_THEME_APPLY_DELAY_MS = 20
_THEME_RENDER_TIMER_ATTRS = (
    "_discover_items_render_timer",
    "_trending_items_render_timer",
)


def _list_item_identity(item) -> str:
    """读取列表条目的项目标识，用于判断数据是否为连续追加。"""
    try:
        value = item.data(_Qt.ItemDataRole.UserRole)
    except Exception:
        return ""
    return str(value or "").strip().casefold()


def _is_incremental_list_append(list_widget, repos) -> bool:
    """仅当新数据完整保留旧列表前缀时，才视为加载更多。"""
    if list_widget is None:
        return False
    try:
        old_count = int(list_widget.count())
    except Exception:
        return False
    new_items = list(repos or [])
    if old_count <= 0 or len(new_items) <= old_count:
        return False

    old_identities = []
    for row in range(old_count):
        try:
            identity = _list_item_identity(list_widget.item(row))
        except Exception:
            return False
        if not identity:
            return False
        old_identities.append(identity)

    new_identities = []
    for repo in new_items:
        if not isinstance(repo, dict):
            return False
        identity = _repo_identity(repo)
        if not identity:
            return False
        new_identities.append(identity)
    return old_identities == new_identities[:old_count]


def _capture_list_state_with_default_top(self, list_widget, repos, force_top=False):
    """新列表默认置顶；只有连续加载更多时才保留原来的滚动状态。"""
    try:
        state = self._capture_list_state(list_widget)
    except Exception:
        state = _LIST_DEFAULT_TOP_STATE
    if not force_top and _is_incremental_list_append(list_widget, repos):
        return state
    return _LIST_DEFAULT_TOP_STATE


def _render_discover_items_with_default_top(self, repos):
    """分批绘制项目列表，新结果置顶，加载更多保留当前位置。"""
    force_top = bool(getattr(self, "_force_list_render_top", False))
    state = _capture_list_state_with_default_top(
        self,
        self.repo_list,
        repos,
        force_top=force_top,
    )
    self._stop_search_rendering()
    self.repo_list.clear()
    _start_incremental_list_render(self, "discover", self.repo_list, repos, state)


def _render_trending_items_with_default_top(self, repos):
    """分批绘制热榜列表，新结果置顶，加载更多保留当前位置。"""
    force_top = bool(getattr(self, "_force_list_render_top", False))
    state = _capture_list_state_with_default_top(
        self,
        self.trending_list,
        repos,
        force_top=force_top,
    )
    self._stop_trending_rendering()
    self.trending_list.clear()
    _start_incremental_list_render(
        self,
        "trending",
        self.trending_list,
        repos,
        state,
    )


_ORIGINAL_APPLY_CATEGORY_FILTER_FOR_SCROLL_TOP = MainWindow._apply_category_filter


def _apply_category_filter_with_scroll_top(self):
    """切换分类或列表时标记置顶，后台加载更多不改变当前位置。"""
    view_combo = getattr(self, "view_combo", None)
    try:
        current_view = view_combo.currentData() if view_combo is not None else ""
    except Exception:
        current_view = ""
    current_category = str(getattr(self, "_current_category", "") or "")

    previous_view = getattr(self, "_last_scroll_view", _LIST_SCROLL_STATE_UNSET)
    previous_category = getattr(self, "_last_scroll_category", _LIST_SCROLL_STATE_UNSET)
    force_top = (
        previous_view is _LIST_SCROLL_STATE_UNSET
        or previous_category is _LIST_SCROLL_STATE_UNSET
        or current_view != previous_view
        or current_category != previous_category
    )
    previous_hint = bool(getattr(self, "_force_list_render_top", False))
    self._force_list_render_top = previous_hint or force_top
    try:
        return _ORIGINAL_APPLY_CATEGORY_FILTER_FOR_SCROLL_TOP(self)
    finally:
        self._force_list_render_top = previous_hint
        self._last_scroll_view = current_view
        self._last_scroll_category = current_category


# ------------------------------ 主题切换延迟应用 ------------------------------
_ORIGINAL_APPLY_THEME_FOR_SMOOTH = MainWindow._apply_theme


def _set_theme_button_state(window, dark: bool) -> None:
    """立即更新主题按钮，完整样式稍后合并应用。"""
    button = getattr(window, "theme_btn", None)
    if button is None:
        return
    try:
        button.setText("☀️" if dark else "🌙")
        button.setToolTip("切换到亮色主题" if dark else "切换到暗色主题")
    except Exception:
        pass


def _ensure_theme_apply_timer(window):
    """创建单次主题样式计时器，连续点击时只执行最后一次。"""
    timer = getattr(window, "_theme_apply_timer", None)
    if timer is not None:
        return timer
    try:
        timer = _QTimer(window)
        timer.setSingleShot(True)
        timer.timeout.connect(
            lambda target=window: _flush_pending_theme_style(target)
        )
        window._theme_apply_timer = timer
        return timer
    except Exception:
        _write_startup_log("无法创建主题切换计时器", _sys.exc_info())
        return None


def _pause_incremental_list_timers(window):
    """主题样式更新期间暂停列表分批计时器，避免同一帧叠加工作。"""
    paused = []
    for attr in _THEME_RENDER_TIMER_ATTRS:
        timer = getattr(window, attr, None)
        if timer is None:
            continue
        try:
            if not timer.isActive():
                continue
            remaining = int(timer.remainingTime())
            timer.stop()
            paused.append((timer, remaining))
        except Exception:
            pass
    return paused


def _resume_incremental_list_timers(paused, window) -> None:
    """恢复主题样式更新前仍在运行的列表计时器。"""
    for timer, remaining in paused:
        try:
            if not timer.isActive():
                interval = remaining if remaining > 0 else _LIST_RENDER_INTERVAL_MS
                timer.start(max(1, interval))
        except Exception:
            pass


def _collect_theme_update_widgets(window):
    """收集需要暂时停止绘制的窗口和主要内容控件。"""
    widgets = []
    seen = set()

    def add(widget):
        if widget is None:
            return
        marker = id(widget)
        if marker in seen:
            return
        seen.add(marker)
        widgets.append(widget)

    add(window)
    try:
        add(window.centralWidget())
    except Exception:
        pass
    for attr in (
        "repo_list",
        "trending_list",
        "detail_browser",
        "detail_text",
        "detail_view",
        "content_stack",
        "main_splitter",
    ):
        try:
            add(getattr(window, attr, None))
        except Exception:
            pass
    return widgets


def _flush_pending_theme_style(window) -> None:
    """在事件循环空闲时应用最后一次主题样式，减少点击卡顿和重复刷新。"""
    pending = getattr(window, "_pending_theme_dark", None)
    if pending is None or getattr(window, "_theme_smooth_closing", False):
        return
    if getattr(window, "_theme_style_applying", False):
        return
    window._pending_theme_dark = None
    window._theme_style_applying = True
    paused = _pause_incremental_list_timers(window)
    frozen = []
    try:
        for widget in _collect_theme_update_widgets(window):
            try:
                widget.setUpdatesEnabled(False)
                frozen.append(widget)
            except Exception:
                pass
        _ORIGINAL_APPLY_THEME_FOR_SMOOTH(window, bool(pending))
    except BaseException:
        _write_startup_log("应用主题样式失败", _sys.exc_info())
    finally:
        for widget in reversed(frozen):
            try:
                widget.setUpdatesEnabled(True)
                widget.update()
            except Exception:
                pass
        _resume_incremental_list_timers(paused, window)
        window._theme_style_applying = False

    next_pending = getattr(window, "_pending_theme_dark", None)
    if next_pending is not None:
        timer = _ensure_theme_apply_timer(window)
        if timer is not None:
            try:
                timer.start(_THEME_APPLY_DELAY_MS)
            except Exception:
                pass


def _apply_theme_without_stall(self, dark: bool):
    """主题按钮立即反馈，完整样式延迟合并，避免同步刷新整个界面。"""
    dark = bool(dark)
    self._pending_theme_dark = dark
    _set_theme_button_state(self, dark)

    # 首次初始化仍然同步应用，避免窗口显示前短暂出现错误主题。
    if not getattr(self, "_theme_style_initialized", False):
        timer = getattr(self, "_theme_apply_timer", None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        result = _ORIGINAL_APPLY_THEME_FOR_SMOOTH(self, dark)
        self._theme_style_initialized = True
        self._pending_theme_dark = None
        return result

    if getattr(self, "_theme_smooth_closing", False):
        return None
    if _QApplication.instance() is None:
        return None
    timer = _ensure_theme_apply_timer(self)
    if timer is None:
        _flush_pending_theme_style(self)
        return None
    try:
        timer.start(_THEME_APPLY_DELAY_MS)
    except Exception:
        _flush_pending_theme_style(self)
    return None


def _toggle_theme_without_stall(self):
    """保存主题设置并交给延迟样式应用逻辑处理。"""
    dark = not self.service.config.get("dark_mode", False)
    self.service.config["dark_mode"] = dark
    self.service.save_config()
    self._apply_theme(dark)


_ORIGINAL_CLOSE_EVENT_FOR_THEME_SMOOTH = MainWindow.closeEvent


def _close_event_with_theme_smooth_cleanup(self, event):
    """关闭窗口前停止主题计时器，避免退出后触发样式回调。"""
    self._theme_smooth_closing = True
    timer = getattr(self, "_theme_apply_timer", None)
    if timer is not None:
        try:
            timer.stop()
        except Exception:
            pass
    self._pending_theme_dark = None
    return _ORIGINAL_CLOSE_EVENT_FOR_THEME_SMOOTH(self, event)


