# ------------------------------ 启动后列表布局稳定置顶 ------------------------------
_LIST_TOP_SETTLE_DELAYS_MS = (0, 60, 180, 420, 800, 1200, 1800)
_LIST_TOP_SETTLE_TOKEN_ATTR = "_list_top_settle_tokens"


def _list_top_settle_widget(window, kind):
    """根据列表类型取得对应控件。"""
    attr = {
        "discover": "repo_list",
        "trending": "trending_list",
        "favorite": "fav_list",
    }.get(str(kind or ""))
    if not attr:
        return None
    try:
        return getattr(window, attr, None)
    except Exception:
        return None


def _bump_list_top_settle_token(window, kind):
    """每次重新渲染时更新令牌，防止旧的置顶回调影响新列表。"""
    tokens = getattr(window, _LIST_TOP_SETTLE_TOKEN_ATTR, None)
    if not isinstance(tokens, dict):
        tokens = {}
    try:
        token = int(tokens.get(kind, 0)) + 1
    except (TypeError, ValueError):
        token = 1
    tokens[kind] = token
    setattr(window, _LIST_TOP_SETTLE_TOKEN_ATTR, tokens)
    return token


def _current_list_top_settle_token(window, kind):
    tokens = getattr(window, _LIST_TOP_SETTLE_TOKEN_ATTR, None)
    if not isinstance(tokens, dict):
        return 0
    try:
        return int(tokens.get(kind, 0))
    except (TypeError, ValueError):
        return 0


def _list_render_state_requests_top(state) -> bool:
    """判断本次渲染是否应该恢复到顶部，而不是保留加载更多的位置。"""
    if not isinstance(state, (tuple, list)) or len(state) < 2:
        return True
    try:
        scroll_value = int(state[1])
    except (TypeError, ValueError):
        return True
    near_bottom = bool(state[2]) if len(state) >= 3 else False
    return scroll_value <= 0 and not near_bottom


def _force_list_widget_to_top(window, list_widget, kind, token):
    """在布局完成后再次设置滚动条顶部，覆盖 Qt 延迟布局的旧位置。"""
    if list_widget is None:
        return
    if _current_list_top_settle_token(window, kind) != token:
        return
    if getattr(window, "_theme_smooth_closing", False):
        return
    # 启动阶段只有在自动分页保护仍然有效时才继续置顶；用户一旦主动滚动，立即停止后续校正。
    if str(kind or "") in ("discover", "trending") and not _is_list_autoload_blocked(window, kind):
        return
    try:
        if list_widget.count() <= 0:
            return
        scroll_bar = list_widget.verticalScrollBar()
        minimum = scroll_bar.minimum()
        list_widget.scrollToTop()
        scroll_bar.setValue(minimum)
    except BaseException:
        _write_startup_log("列表布局稳定置顶失败", _sys.exc_info())


def _schedule_list_top_settle(window, kind, list_widget=None, token=None):
    """在当前事件循环及后续布局帧中多次轻量校正列表顶部位置。"""
    if list_widget is None:
        list_widget = _list_top_settle_widget(window, kind)
    if list_widget is None:
        return
    if token is None:
        token = _current_list_top_settle_token(window, kind)
    for delay in _LIST_TOP_SETTLE_DELAYS_MS:
        try:
            _QTimer.singleShot(
                int(delay),
                lambda target=window, widget=list_widget, list_kind=kind, generation=token:
                _force_list_widget_to_top(target, widget, list_kind, generation),
            )
        except BaseException:
            _write_startup_log("无法安排列表布局置顶校正", _sys.exc_info())


_ORIGINAL_START_INCREMENTAL_LIST_RENDER_FOR_TOP_SETTLE = _start_incremental_list_render


def _start_incremental_list_render_with_top_settle_tracking(
    window,
    kind,
    list_widget,
    repos,
    saved_state,
):
    # 令牌更新后立即重建自动分页保护，避免首批条目触发滚动信号时保护失效。
    token = _bump_list_top_settle_token(window, kind)
    _set_list_autoload_block(window, kind, True, token=token)
    return _ORIGINAL_START_INCREMENTAL_LIST_RENDER_FOR_TOP_SETTLE(
        window,
        kind,
        list_widget,
        repos,
        saved_state,
    )


_start_incremental_list_render = _start_incremental_list_render_with_top_settle_tracking


_ORIGINAL_RENDER_NEXT_INCREMENTAL_LIST_BATCH_FOR_TOP_SETTLE = _render_next_incremental_list_batch


def _render_next_incremental_list_batch_with_post_layout_top(window, kind):
    """列表分批渲染完成后，在 Qt 最终布局阶段补一次置顶。"""
    _, state_attr = _list_render_attributes(kind)
    pending_state = getattr(window, state_attr, None)
    saved_state = (
        pending_state.get("saved_state")
        if isinstance(pending_state, dict)
        else None
    )
    _ORIGINAL_RENDER_NEXT_INCREMENTAL_LIST_BATCH_FOR_TOP_SETTLE(window, kind)
    if not isinstance(pending_state, dict):
        return
    if isinstance(getattr(window, state_attr, None), dict):
        return
    if not _list_render_state_requests_top(saved_state):
        return
    _schedule_list_top_settle(
        window,
        kind,
        pending_state.get("list_widget"),
        token=_current_list_top_settle_token(window, kind),
    )


_render_next_incremental_list_batch = _render_next_incremental_list_batch_with_post_layout_top


_ORIGINAL_RENDER_FAVORITE_ITEMS_FOR_TOP_SETTLE = MainWindow._render_favorite_items


def _render_favorite_items_with_post_layout_top(self, repos):
    """收藏列表使用同步渲染时，也在最终布局帧补一次置顶。"""
    _bump_list_top_settle_token(self, "favorite")
    result = _ORIGINAL_RENDER_FAVORITE_ITEMS_FOR_TOP_SETTLE(self, repos)
    _schedule_list_top_settle(
        self,
        "favorite",
        getattr(self, "fav_list", None),
        token=_current_list_top_settle_token(self, "favorite"),
    )
    return result


MainWindow._render_favorite_items = _render_favorite_items_with_post_layout_top


_ORIGINAL_SHOW_EVENT_FOR_TOP_SETTLE = MainWindow.showEvent


def _show_event_with_first_list_top_settle(self, event):
    """首次显示窗口后安排一次列表置顶，确保窗口初次布局不会落到底部。"""
    first_show = not bool(getattr(self, "_list_first_show_handled", False))
    if first_show:
        self._list_first_show_handled = True
    try:
        result = _ORIGINAL_SHOW_EVENT_FOR_TOP_SETTLE(self, event)
    finally:
        try:
            _install_list_scroll_intent_filters(self)
        except BaseException:
            _write_startup_log("首次显示时安装列表滚动保护失败", _sys.exc_info())
        if first_show:
            for kind in ("discover", "trending", "favorite"):
                _schedule_list_top_settle(
                    self,
                    kind,
                    _list_top_settle_widget(self, kind),
                    token=_current_list_top_settle_token(self, kind),
                )
    return result


MainWindow.showEvent = _show_event_with_first_list_top_settle

# ------------------------------ 列表滚动意图与启动自动加载保护 ------------------------------
_LIST_SCROLL_INTENT_ATTR = '_list_scroll_intents'
_LIST_AUTOLOAD_BLOCK_ATTR = '_list_autoload_block_until'
_LIST_AUTOLOAD_BLOCK_MS = 1800


def _list_scroll_intents(window) -> dict:
    # 取得每种列表的一次性滚动意图。
    intents = getattr(window, _LIST_SCROLL_INTENT_ATTR, None)
    if not isinstance(intents, dict):
        intents = {}
        setattr(window, _LIST_SCROLL_INTENT_ATTR, intents)
    return intents


def _set_list_scroll_intent(window, kind, preserve: bool) -> None:
    # 记录本次渲染是否来自加载更多。
    _list_scroll_intents(window)[str(kind or '')] = bool(preserve)


def _consume_list_scroll_intent(window, kind) -> bool:
    # 读取并消耗一次性滚动意图，避免旧请求影响后续刷新。
    intents = _list_scroll_intents(window)
    return bool(intents.pop(str(kind or ''), False))


def _clear_list_scroll_intents(window) -> None:
    # 刷新或关闭时清理可能残留的滚动意图。
    intents = getattr(window, _LIST_SCROLL_INTENT_ATTR, None)
    if isinstance(intents, dict):
        intents.clear()


def _set_list_autoload_block(window, kind, blocked: bool, token=None) -> None:
    # 首次渲染期间持续屏蔽滚动到底部触发的自动分页，直到用户明确滚动。
    blocks = getattr(window, _LIST_AUTOLOAD_BLOCK_ATTR, None)
    if not isinstance(blocks, dict):
        blocks = {}
        setattr(window, _LIST_AUTOLOAD_BLOCK_ATTR, blocks)
    key = str(kind or '')
    if not blocked:
        blocks.pop(key, None)
        return
    if token is None:
        token = _current_list_top_settle_token(window, key)
    try:
        normalized_token = int(token)
    except (TypeError, ValueError):
        normalized_token = 0
    # 使用持久保护，不依赖固定时长；否则首屏布局稍慢时仍会在保护结束后误触发分页。
    _scroll_debug("设置保护 kind=" + key + " token=" + str(normalized_token))
    blocks[key] = {
        "deadline": None,
        "token": normalized_token,
        "persistent": True,
    }


def _is_list_autoload_blocked(window, kind) -> bool:
    # 判断列表是否仍处于启动或重新渲染保护期。
    blocks = getattr(window, _LIST_AUTOLOAD_BLOCK_ATTR, None)
    if not isinstance(blocks, dict):
        return False
    key = str(kind or '')
    entry = blocks.get(key)
    if isinstance(entry, dict):
        deadline = entry.get("deadline")
        persistent = bool(entry.get("persistent", deadline is None))
        raw_token = entry.get("token", 0)
    elif isinstance(entry, (tuple, list)) and len(entry) >= 2:
        # 兼容旧对象状态，避免热重载或旧回调传入时出现异常。
        deadline = entry[0]
        persistent = deadline is None
        raw_token = entry[1]
    else:
        blocks.pop(key, None)
        return False
    try:
        token = int(raw_token)
    except (TypeError, ValueError):
        blocks.pop(key, None)
        return False
    if token != _current_list_top_settle_token(window, key):
        blocks.pop(key, None)
        return False
    if persistent:
        return True
    try:
        if _time.monotonic() >= float(deadline):
            blocks.pop(key, None)
            return False
    except (TypeError, ValueError):
        blocks.pop(key, None)
        return False
    return True


def _clear_list_autoload_block_if_token(window, kind, token) -> None:
    # 计时器只允许清理临时保护，持久保护必须等用户主动滚动后解除。
    blocks = getattr(window, _LIST_AUTOLOAD_BLOCK_ATTR, None)
    if not isinstance(blocks, dict):
        return
    key = str(kind or '')
    entry = blocks.get(key)
    if isinstance(entry, dict):
        try:
            current_token = int(entry.get("token", 0))
            target_token = int(token)
        except (TypeError, ValueError):
            return
        if current_token == target_token and not bool(entry.get("persistent", entry.get("deadline") is None)):
            blocks.pop(key, None)
        return
    if not isinstance(entry, (tuple, list)) or len(entry) < 2:
        blocks.pop(key, None)
        return
    try:
        current_token = int(entry[1])
        target_token = int(token)
    except (TypeError, ValueError):
        return
    # 旧格式中截止时间为空时代表持久保护，同样不能被计时器解除。
    if current_token == target_token and entry[0] is not None:
        blocks.pop(key, None)


def _capture_explicit_list_state(window, list_widget, preserve_scroll: bool):
    # 只按调用方明确的意图决定是否保留位置，不再猜测是否为加载更多。
    try:
        state = window._capture_list_state(list_widget)
    except Exception:
        state = _LIST_DEFAULT_TOP_STATE
    if preserve_scroll:
        return state
    return _LIST_DEFAULT_TOP_STATE


def _render_discover_items_with_explicit_scroll_intent(self, repos):
    # 普通刷新和切换视图置顶，只有明确加载更多时保留位置。
    preserve_scroll = _consume_list_scroll_intent(self, 'discover')
    if bool(getattr(self, '_force_list_render_top', False)):
        preserve_scroll = False
    _set_list_autoload_block(self, 'discover', True)
    state = _capture_explicit_list_state(self, self.repo_list, preserve_scroll)
    self._stop_search_rendering()
    self.repo_list.clear()
    _start_incremental_list_render(self, 'discover', self.repo_list, repos, state)
    if not preserve_scroll:
        _set_list_autoload_block(
            self,
            'discover',
            True,
            token=_current_list_top_settle_token(self, 'discover'),
        )


def _render_trending_items_with_explicit_scroll_intent(self, repos):
    # 普通刷新和切换视图置顶，只有明确加载更多时保留位置。
    preserve_scroll = _consume_list_scroll_intent(self, 'trending')
    if bool(getattr(self, '_force_list_render_top', False)):
        preserve_scroll = False
    _set_list_autoload_block(self, 'trending', True)
    state = _capture_explicit_list_state(self, self.trending_list, preserve_scroll)
    self._stop_trending_rendering()
    self.trending_list.clear()
    _start_incremental_list_render(
        self,
        'trending',
        self.trending_list,
        repos,
        state,
    )
    if not preserve_scroll:
        _set_list_autoload_block(
            self,
            'trending',
            True,
            token=_current_list_top_settle_token(self, 'trending'),
        )


MainWindow._render_discover_items = _render_discover_items_with_explicit_scroll_intent
MainWindow._render_trending_items = _render_trending_items_with_explicit_scroll_intent


_ORIGINAL_LOAD_MORE_DISCOVER_FOR_SCROLL_INTENT = MainWindow._load_more_discover
_ORIGINAL_LOAD_MORE_TRENDING_FOR_SCROLL_INTENT = MainWindow._load_more_trending


def _load_more_discover_with_scroll_intent(self):
    # 统一拦截启动布局触发的自动分页，避免绕过滚动槽函数。
    if _is_list_autoload_blocked(self, 'discover'):
        _scroll_debug('拦截启动期项目列表自动分页')
        return None
    # 只有成功开始加载下一页时才记录保留滚动位置。
    was_loading = bool(getattr(self, '_search_loading_more', False))
    result = _ORIGINAL_LOAD_MORE_DISCOVER_FOR_SCROLL_INTENT(self)
    is_loading = bool(getattr(self, '_search_loading_more', False))
    if not was_loading and is_loading:
        _set_list_scroll_intent(self, 'discover', True)
    return result


def _load_more_trending_with_scroll_intent(self):
    # 统一拦截启动布局触发的自动分页，避免绕过滚动槽函数。
    if _is_list_autoload_blocked(self, 'trending'):
        _scroll_debug('拦截启动期热榜自动分页')
        return None
    # 只有成功开始加载下一页时才记录保留滚动位置。
    was_loading = bool(getattr(self, '_trending_loading_more', False))
    result = _ORIGINAL_LOAD_MORE_TRENDING_FOR_SCROLL_INTENT(self)
    is_loading = bool(getattr(self, '_trending_loading_more', False))
    if not was_loading and is_loading:
        _set_list_scroll_intent(self, 'trending', True)
    return result


