# ------------------------------ 加载更多完成后的滚动位置延迟恢复 ------------------------------
_LIST_PENDING_SCROLL_RESTORE_ATTR = '_list_pending_scroll_restore'
_LIST_SCROLL_RESTORE_DELAYS_MS = (0, 80, 180, 360, 650)


def _pending_scroll_restores(window) -> dict:
    # 保存等待 Qt 最终布局后恢复的滚动状态。
    pending = getattr(window, _LIST_PENDING_SCROLL_RESTORE_ATTR, None)
    if not isinstance(pending, dict):
        pending = {}
        setattr(window, _LIST_PENDING_SCROLL_RESTORE_ATTR, pending)
    return pending


def _capture_scroll_restore_state(window, list_widget):
    try:
        return window._capture_list_state(list_widget)
    except Exception:
        return _LIST_DEFAULT_TOP_STATE


def _restore_list_scroll_after_layout(window, kind, list_widget, state, token):
    # 加载更多会清空后重建条目，必须在布局完成后多次恢复位置。
    if _current_list_top_settle_token(window, kind) != int(token):
        return
    _, state_attr = _list_render_attributes(kind)
    if isinstance(getattr(window, state_attr, None), dict):
        return
    if not isinstance(state, (tuple, list)) or len(state) < 3:
        return
    try:
        scroll_value = int(state[1])
        near_bottom = bool(state[2])
        scroll_bar = list_widget.verticalScrollBar()
        maximum = int(scroll_bar.maximum())
        target = maximum if near_bottom else min(max(0, scroll_value), maximum)
        scroll_bar.setValue(max(0, target))
    except BaseException:
        _write_startup_log('恢复加载更多滚动位置失败', _sys.exc_info())


def _schedule_delayed_scroll_restore(window, kind, pending) -> None:
    if not isinstance(pending, dict):
        return
    list_widget = pending.get('list_widget')
    state = pending.get('state')
    token = pending.get('token')
    if list_widget is None or token is None:
        return
    for delay in _LIST_SCROLL_RESTORE_DELAYS_MS:
        try:
            _QTimer.singleShot(
                int(delay),
                lambda target=window, list_kind=kind, widget=list_widget,
                saved_state=state, generation=token:
                _restore_list_scroll_after_layout(
                    target,
                    list_kind,
                    widget,
                    saved_state,
                    generation,
                ),
            )
        except BaseException:
            _write_startup_log('无法安排加载更多滚动位置恢复', _sys.exc_info())


_ORIGINAL_RENDER_DISCOVER_ITEMS_FOR_SCROLL_RESTORE = MainWindow._render_discover_items
_ORIGINAL_RENDER_TRENDING_ITEMS_FOR_SCROLL_RESTORE = MainWindow._render_trending_items


def _render_discover_items_with_delayed_scroll_restore(self, repos):
    # 在渲染开始前捕获位置，供加载更多的最终布局阶段恢复。
    force_top = bool(getattr(self, '_force_list_render_top', False))
    preserve_scroll = bool(_list_scroll_intents(self).get('discover', False)) and not force_top
    list_widget = self.repo_list
    saved_state = _capture_scroll_restore_state(self, list_widget) if preserve_scroll else None
    result = _ORIGINAL_RENDER_DISCOVER_ITEMS_FOR_SCROLL_RESTORE(self, repos)
    pending = _pending_scroll_restores(self)
    if preserve_scroll and saved_state is not None:
        token = _current_list_top_settle_token(self, 'discover')
        pending['discover'] = {
            'list_widget': list_widget,
            'state': saved_state,
            'token': token,
        }
        _set_list_autoload_block(self, 'discover', True, token=token)
        _, state_attr = _list_render_attributes('discover')
        if not isinstance(getattr(self, state_attr, None), dict):
            _schedule_delayed_scroll_restore(self, 'discover', pending.pop('discover'))
    else:
        pending.pop('discover', None)
    return result


def _render_trending_items_with_delayed_scroll_restore(self, repos):
    # 在渲染开始前捕获位置，供加载更多的最终布局阶段恢复。
    _scroll_debug("进入热榜渲染 count=" + str(len(repos or [])))
    force_top = bool(getattr(self, '_force_list_render_top', False))
    preserve_scroll = bool(_list_scroll_intents(self).get('trending', False)) and not force_top
    list_widget = self.trending_list
    saved_state = _capture_scroll_restore_state(self, list_widget) if preserve_scroll else None
    result = _ORIGINAL_RENDER_TRENDING_ITEMS_FOR_SCROLL_RESTORE(self, repos)
    pending = _pending_scroll_restores(self)
    if preserve_scroll and saved_state is not None:
        token = _current_list_top_settle_token(self, 'trending')
        pending['trending'] = {
            'list_widget': list_widget,
            'state': saved_state,
            'token': token,
        }
        _set_list_autoload_block(self, 'trending', True, token=token)
        _, state_attr = _list_render_attributes('trending')
        if not isinstance(getattr(self, state_attr, None), dict):
            _schedule_delayed_scroll_restore(self, 'trending', pending.pop('trending'))
    else:
        pending.pop('trending', None)
    return result


MainWindow._render_discover_items = _render_discover_items_with_delayed_scroll_restore
MainWindow._render_trending_items = _render_trending_items_with_delayed_scroll_restore


_ORIGINAL_RENDER_NEXT_INCREMENTAL_LIST_BATCH_FOR_SCROLL_RESTORE = _render_next_incremental_list_batch


def _render_next_incremental_list_batch_with_scroll_restore(window, kind):
    # 分批渲染结束后，再安排多次恢复，覆盖 Qt 延迟布局和滚动信号的影响。
    _, state_attr = _list_render_attributes(kind)
    state_before = getattr(window, state_attr, None)
    _ORIGINAL_RENDER_NEXT_INCREMENTAL_LIST_BATCH_FOR_SCROLL_RESTORE(window, kind)
    if not isinstance(state_before, dict):
        return
    if isinstance(getattr(window, state_attr, None), dict):
        return
    pending = _pending_scroll_restores(window).pop(str(kind or ''), None)
    if pending is None:
        return
    token = pending.get('token')
    if token is None:
        return
    _set_list_autoload_block(window, kind, True, token=token)
    _schedule_delayed_scroll_restore(window, kind, pending)
    _QTimer.singleShot(
        900,
        lambda target=window, list_kind=kind, generation=token:
        _clear_list_autoload_block_if_token(target, list_kind, generation),
    )


_render_next_incremental_list_batch = _render_next_incremental_list_batch_with_scroll_restore

# 恢复代码使用独立全局命名空间，必须同步最终包装函数，确保分批计时器不会绕过滚动保护。
