_RECOVERED_NAMESPACE["_load_more_trending"] = _load_more_trending_with_scroll_intent


# ------------------------------ 最终启动置顶锁 ------------------------------
# 启动阶段由 Qt 延迟布局、自动分页和条目重建共同影响滚动位置。
# 这里不再依赖某一个滚动值，而是以用户真实滚动操作作为唯一解锁条件。
from PyQt6.QtWidgets import QAbstractItemView as _QAbstractItemView

_STARTUP_TOP_LOCK_ATTR = "_startup_top_lock"
_STARTUP_TOP_SHOW_HANDLED_ATTR = "_startup_top_show_handled"
_STARTUP_TOP_KINDS = ("discover", "trending", "favorite")
_STARTUP_TOP_RETRY_DELAYS_MS = (0, 40, 100, 220, 420, 750, 1200, 1800, 2600, 4000, 6000)


def _startup_top_locks(window) -> dict:
    locks = getattr(window, _STARTUP_TOP_LOCK_ATTR, None)
    if not isinstance(locks, dict):
        locks = {}
        setattr(window, _STARTUP_TOP_LOCK_ATTR, locks)
    return locks


def _startup_top_lock_active(window, kind) -> bool:
    return bool(_startup_top_locks(window).get(str(kind or ""), False))


def _set_startup_top_lock(window, kind, locked: bool) -> None:
    key = str(kind or "")
    locks = _startup_top_locks(window)
    if locked:
        locks[key] = True
    else:
        locks.pop(key, None)


def _arm_startup_top_lock(window, kind) -> None:
    key = str(kind or "")
    if not key:
        return
    _set_startup_top_lock(window, key, True)
    if key in ("discover", "trending"):
        _set_list_autoload_block(window, key, True)
    _schedule_startup_top_lock(window, key)


def _force_startup_list_top(window, kind) -> None:
    """在启动锁仍有效时，直接把列表视口和滚动条一起校正到顶部。"""
    key = str(kind or "")
    if not _startup_top_lock_active(window, key):
        return
    list_widget = _list_top_settle_widget(window, key)
    if list_widget is None:
        return
    try:
        if int(list_widget.count()) <= 0:
            return
        first_item = list_widget.item(0)
        if first_item is not None:
            try:
                list_widget.scrollToItem(
                    first_item,
                    _QAbstractItemView.ScrollHint.PositionAtTop,
                )
            except BaseException:
                pass
        scroll_bar = list_widget.verticalScrollBar()
        minimum = int(scroll_bar.minimum())
        scroll_bar.setValue(minimum)
        list_widget.scrollToTop()
        scroll_bar.setValue(minimum)
        try:
            list_widget.viewport().update()
        except BaseException:
            pass
        _scroll_debug(
            "启动置顶校正 kind=" + key
            + " value=" + str(scroll_bar.value())
            + " maximum=" + str(scroll_bar.maximum())
        )
    except BaseException:
        _write_startup_log("启动阶段列表置顶失败", _sys.exc_info())


def _schedule_startup_top_lock(window, kind) -> None:
    key = str(kind or "")
    if not _startup_top_lock_active(window, key):
        return
    for delay in _STARTUP_TOP_RETRY_DELAYS_MS:
        try:
            _QTimer.singleShot(
                int(delay),
                lambda target=window, list_kind=key:
                _force_startup_list_top(target, list_kind),
            )
        except BaseException:
            _write_startup_log("无法安排启动阶段列表置顶", _sys.exc_info())


_ORIGINAL_MARK_LIST_USER_SCROLL_FOR_FINAL_TOP_LOCK = _mark_list_user_scroll


def _mark_list_user_scroll_with_final_top_lock(window, kind) -> None:
    _ORIGINAL_MARK_LIST_USER_SCROLL_FOR_FINAL_TOP_LOCK(window, kind)
    key = str(kind or "")
    if _startup_top_lock_active(window, key):
        _set_startup_top_lock(window, key, False)
        _scroll_debug("检测到用户滚动，解除置顶锁 kind=" + key)


