def _show_event_with_final_top_lock(self, event):
    first_show = not bool(getattr(self, _STARTUP_TOP_SHOW_HANDLED_ATTR, False))
    if first_show:
        setattr(self, _STARTUP_TOP_SHOW_HANDLED_ATTR, True)
        for key in _STARTUP_TOP_KINDS:
            _arm_startup_top_lock(self, key)
    result = _ORIGINAL_SHOW_EVENT_FOR_FINAL_TOP_LOCK(self, event)
    for key in _STARTUP_TOP_KINDS:
        if _startup_top_lock_active(self, key):
            _schedule_startup_top_lock(self, key)
    return result


