# ------------------------------ 首屏缓存优先与后台更新 ------------------------------
_STARTUP_CACHE_SEARCH_URL = "https://api.github.com/search/repositories"
_STARTUP_CACHE_RETENTION_SECONDS = 86400
_STARTUP_SERVICE_FORCE_REFRESH_ATTR = "_startup_force_search_refresh"
_STARTUP_HTTP_FORCE_REFRESH_ATTR = "_startup_force_refresh_pending"
_STARTUP_CACHE_SHOWN_ATTR = "_startup_cache_shown"


def _startup_search_params(window) -> dict:
    """按照当前配置还原搜索接口第一页的参数，确保缓存键与实际请求一致。"""
    service = getattr(window, "service", None)
    config = getattr(service, "config", {}) or {}
    query = str(config.get("query", "stars:>500") or "stars:>500").strip()
    language = str(config.get("language", "") or "").strip()
    if language:
        query = f"{query} language:{language}"
    params = {
        "q": query,
        "per_page": int(REPOSITORY_PAGE_SIZE),
        "page": 1,
    }
    sort = str(config.get("sort", "updated") or "updated").strip()
    if sort and sort.casefold() != "best match":
        params["sort"] = sort
    return params


def _startup_auth_marker(client) -> str:
    """生成只用于匹配缓存记录的认证指纹，不保存或输出令牌本身。"""
    config = getattr(client, "config", {}) or {}
    token = str(config.get("github_token") or "")
    if not token:
        return "public"
    return _hashlib.sha256(token.encode("utf-8", "ignore")).hexdigest()[:16]


def _startup_cache_repo_from_item(item: dict) -> dict | None:
    """把搜索接口缓存中的原始项目还原为界面使用的项目字典。"""
    if not isinstance(item, dict):
        return None
    full_name = str(item.get("full_name") or "").strip()
    html_url = str(item.get("html_url") or "").strip()
    if not full_name or not html_url:
        return None
    description = str(item.get("description") or "")
    releases_url = str(item.get("releases_url") or "").split("{", 1)[0]
    repo = {
        "full_name": full_name,
        "html_url": html_url,
        "description": description,
        "stars": item.get("stargazers_count", 0) or 0,
        "language": item.get("language") or "",
        "updated_at": item.get("updated_at") or "",
        "default_branch": item.get("default_branch") or "main",
        "clone_url": item.get("clone_url") or "",
        "ssh_url": item.get("ssh_url") or "",
        "releases_url": releases_url,
        "_brief": description,
        "topics": _normalize_topics(item.get("topics")),
    }
    return repo


def _startup_cache_repo_list_from_record(record: dict) -> list[dict] | None:
    """解析一条接口缓存记录，缓存损坏或格式不匹配时返回空结果。"""
    if not isinstance(record, dict):
        return None
    response = _restore_cached_response(record.get("response"))
    if response is None:
        return None
    try:
        payload = response.json()
    except Exception:
        return None
    if not isinstance(payload, dict) or not isinstance(payload.get("items"), list):
        return None
    repos = []
    for item in payload.get("items") or []:
        repo = _startup_cache_repo_from_item(item)
        if repo is not None:
            repos.append(repo)
    return repos or None


def _startup_cached_repos(window) -> list[dict] | None:
    """优先读取当天的第一页搜索缓存，供首屏先展示。"""
    service = getattr(window, "service", None)
    http = getattr(service, "http", None)
    database = getattr(service, "db", None)
    getter = getattr(database, "get_recent_api_cache_records", None)
    if not callable(getter) or http is None:
        return None

    try:
        params = _startup_search_params(window)
        exact_key = _build_http_cache_key(http, _STARTUP_CACHE_SEARCH_URL, params)
        prefix = f"{_HTTP_CACHE_SCHEMA_VERSION}::{_STARTUP_CACHE_SEARCH_URL}::"
        records = getter(
            prefix=prefix,
            max_age_seconds=_STARTUP_CACHE_RETENTION_SECONDS,
            limit=100,
        )
    except Exception:
        return None

    if not isinstance(records, list):
        return None
    auth_suffix = "::auth=" + _startup_auth_marker(http)
    records_by_key = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        key = str(record.get("url") or "")
        if not key.endswith(auth_suffix):
            continue
        if key not in records_by_key:
            records_by_key[key] = record

    ordered_records = []
    exact_record = records_by_key.get(exact_key)
    if exact_record is not None:
        ordered_records.append(exact_record)
    for key, record in records_by_key.items():
        if key == exact_key:
            continue
        if not key.startswith(prefix):
            continue
        encoded_params = key[len(prefix):]
        if "::auth=" in encoded_params:
            encoded_params = encoded_params.rsplit("::auth=", 1)[0]
        try:
            cached_params = _json.loads(encoded_params)
        except Exception:
            continue
        if not isinstance(cached_params, dict):
            continue
        try:
            cached_page = int(cached_params.get("page", 1))
        except (TypeError, ValueError):
            cached_page = 0
        if cached_page != 1:
            continue
        ordered_records.append(record)

    for record in ordered_records:
        repos = _startup_cache_repo_list_from_record(record)
        if repos:
            return repos
    return None


def _arm_startup_network_refresh(service) -> None:
    """让启动阶段的第一页请求跳过服务层、内存层和持久化层的有效缓存。"""
    if service is None:
        return
    setattr(service, _STARTUP_SERVICE_FORCE_REFRESH_ATTR, True)
    http = getattr(service, "http", None)
    if http is None:
        return
    _ensure_http_cache_state(http)
    with http._cache_lock:
        setattr(http, _STARTUP_HTTP_FORCE_REFRESH_ATTR, 1)


def _consume_startup_http_refresh(client, url: str) -> bool:
    """只消费一次启动搜索请求的强制刷新标记。"""
    if str(url or "").rstrip("/") != _STARTUP_CACHE_SEARCH_URL:
        return False
    _ensure_http_cache_state(client)
    with client._cache_lock:
        try:
            pending = int(getattr(client, _STARTUP_HTTP_FORCE_REFRESH_ATTR, 0) or 0)
        except (TypeError, ValueError):
            pending = 0
        if pending <= 0:
            return False
        setattr(client, _STARTUP_HTTP_FORCE_REFRESH_ATTR, pending - 1)
        return True


_ORIGINAL_SEARCH_REPOS_FOR_STARTUP_CACHE = GitHubService.search_repos


def _search_repos_with_startup_cache_bypass(
    self,
    keyword: str = "",
    page: int = 1,
    per_page: int = REPOSITORY_PAGE_SIZE,
) -> list[dict]:
    """启动搜索前清除服务层第一页缓存，避免下层请求未真正访问网络。"""
    if bool(getattr(self, _STARTUP_SERVICE_FORCE_REFRESH_ATTR, False)):
        try:
            cache = getattr(self, "_search_cache", None)
            if isinstance(cache, dict):
                cache.pop(_search_cache_key(self, keyword, page, per_page), None)
        except Exception:
            pass
        finally:
            setattr(self, _STARTUP_SERVICE_FORCE_REFRESH_ATTR, False)
    return _ORIGINAL_SEARCH_REPOS_FOR_STARTUP_CACHE(self, keyword, page, per_page)


GitHubService.search_repos = _search_repos_with_startup_cache_bypass


_ORIGINAL_HTTPCLIENT_GET_FOR_STARTUP_CACHE = HttpClient.get


def _httpclient_get_with_startup_cache_bypass(
    self,
    url: str,
    params=None,
    timeout=20,
    force_refresh=False,
):
    """消费启动强制刷新标记，并继续使用统一的网络超时与缓存逻辑。"""
    startup_force_refresh = False
    if not force_refresh:
        startup_force_refresh = _consume_startup_http_refresh(self, url)
    return _ORIGINAL_HTTPCLIENT_GET_FOR_STARTUP_CACHE(
        self,
        url,
        params=params,
        timeout=timeout,
        force_refresh=bool(force_refresh or startup_force_refresh),
    )


HttpClient.get = _httpclient_get_with_startup_cache_bypass


_ORIGINAL_REFRESH_REPOS_FOR_STARTUP_CACHE = _ORIGINAL_REFRESH_REPOS


def _set_startup_cache_status(window, text: str) -> None:
    """更新首屏缓存状态，并同步项目数量摘要。"""
    try:
        window.status_label.setText(str(text))
    except Exception:
        pass
    try:
        window._update_list_summary()
    except Exception:
        pass


def _refresh_repos_with_startup_cache(window, *args, **kwargs):
    """首屏先显示近期缓存，再提交后台最新请求，网络失败时不清空缓存。"""
    try:
        mode = window.view_combo.currentData()
    except Exception:
        mode = "discover"
    if mode != "discover":
        return _ORIGINAL_REFRESH_REPOS_FOR_STARTUP_CACHE(window, *args, **kwargs)

    service = getattr(window, "service", None)
    cached_repos = _startup_cached_repos(window)
    _arm_startup_network_refresh(service)
    original_run_in_thread = getattr(window, "run_in_thread", None)
    if not callable(original_run_in_thread):
        return _ORIGINAL_REFRESH_REPOS_FOR_STARTUP_CACHE(window, *args, **kwargs)

    pending_tasks = []
    window_dict = getattr(window, "__dict__", {})
    had_instance_runner = "run_in_thread" in window_dict
    old_instance_runner = window_dict.get("run_in_thread")

    def defer_run_in_thread(
        fn,
        on_done=None,
        on_error=None,
        *extra_args,
        **extra_kwargs,
    ):
        pending_tasks.append(
            (fn, on_done, on_error, extra_args, extra_kwargs)
        )
        return None

    window.run_in_thread = defer_run_in_thread
    try:
        result = _ORIGINAL_REFRESH_REPOS_FOR_STARTUP_CACHE(
            window,
            *args,
            **kwargs,
        )
    finally:
        try:
            if had_instance_runner:
                window.run_in_thread = old_instance_runner
            else:
                delattr(window, "run_in_thread")
        except Exception:
            window.run_in_thread = original_run_in_thread

    cache_shown = False
    if cached_repos and pending_tasks:
        first_task = pending_tasks[0]
        cached_callback = first_task[1]
        if callable(cached_callback):
            try:
                cached_callback(cached_repos)
                cache_shown = True
            except BaseException:
                _write_startup_log(
                    "首屏缓存展示失败",
                    _sys.exc_info(),
                )

    if cache_shown:
        setattr(window, _STARTUP_CACHE_SHOWN_ATTR, True)
        _set_startup_cache_status(
            window,
            "已显示缓存项目，正在更新最新数据…",
        )
        try:
            window._start_spinner()
        except Exception:
            pass

    for fn, on_done, on_error, extra_args, extra_kwargs in pending_tasks:
        def wrapped_done(
            *callback_args,
            _callback=on_done,
            **callback_kwargs,
        ):
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                if cache_shown:
                    setattr(window, _STARTUP_CACHE_SHOWN_ATTR, False)

        def wrapped_error(
            *callback_args,
            _callback=on_error,
            **callback_kwargs,
        ):
            if cache_shown and bool(getattr(window, _STARTUP_CACHE_SHOWN_ATTR, False)):
                message = ""
                if callback_args:
                    message = str(callback_args[0] or "")
                elif "message" in callback_kwargs:
                    message = str(callback_kwargs.get("message") or "")
                _write_startup_log(
                    "首屏缓存后的网络更新失败：" + message,
                )
                try:
                    window._stop_spinner()
                except Exception:
                    pass
                _set_startup_cache_status(
                    window,
                    "网络更新失败，已保留缓存（数据可能不是最新）",
                )
                setattr(window, _STARTUP_CACHE_SHOWN_ATTR, False)
                return None
            if callable(_callback):
                return _callback(*callback_args, **callback_kwargs)
            return None

        try:
            original_run_in_thread(
                fn,
                wrapped_done,
                wrapped_error,
                *extra_args,
                **extra_kwargs,
            )
        except BaseException:
            if cache_shown:
                _write_startup_log(
                    "提交首屏后台更新失败",
                    _sys.exc_info(),
                )
                try:
                    window._stop_spinner()
                except Exception:
                    pass
                _set_startup_cache_status(
                    window,
                    "网络更新失败，已保留缓存（数据可能不是最新）",
                )
                setattr(window, _STARTUP_CACHE_SHOWN_ATTR, False)
            else:
                raise

    service_force_pending = bool(
        getattr(service, _STARTUP_SERVICE_FORCE_REFRESH_ATTR, False)
    )
    if service_force_pending and not pending_tasks:
        setattr(service, _STARTUP_SERVICE_FORCE_REFRESH_ATTR, False)
    return result


# 启动定时回调使用这个入口，手动刷新仍沿用原有流程。
_ORIGINAL_REFRESH_REPOS = _refresh_repos_with_startup_cache



# ------------------------------ 列表翻译结果同步修复 ------------------------------
from PyQt6.QtCore import Qt as _Qt


_TRANSLATION_RESULT_UNSET = object()


def _translation_target_language(window) -> str:
    """读取当前窗口使用的目标语言，缺省使用简体中文。"""
    service = getattr(window, "service", None)
    config = getattr(service, "config", None)
    if not isinstance(config, dict):
        config = getattr(window, "config", None)
    if not isinstance(config, dict):
        config = {}
    try:
        value = config.get("target_language")
    except Exception:
        value = None
    value = str(value or "zh-CN").strip()
    return value or "zh-CN"


def _is_chinese_target_language(target_language: str) -> bool:
    """判断目标语言是否为中文，用于兼容旧版中文翻译字段。"""
    value = str(target_language or "").strip().lower()
    return value.startswith("zh") or value in {
        "中文",
        "简体中文",
        "繁体中文",
        "繁體中文",
    }


def _normalized_translation_language(target_language: str) -> str:
    """把目标语言转换为可用于字典字段的稳定名称。"""
    value = str(target_language or "zh-CN").strip().lower()
    value = value.replace("-", "_").replace(" ", "_")
    value = _re.sub(r"[^a-z0-9_]+", "_", value).strip("_")
    return value or "zh_cn"


def _translation_field_candidates(target_language: str) -> list[str]:
    """生成当前目标语言的翻译字段候选，兼容旧版 description_zh。"""
    normalized = _normalized_translation_language(target_language)
    base = normalized.split("_", 1)[0]
    fields = []

    def add(field: str) -> None:
        if field and field not in fields:
            fields.append(field)

    add(f"description_{normalized}")
    if _is_chinese_target_language(target_language):
        add("description_zh")
    else:
        add(f"description_{base}")
    return fields


def _translation_storage_field(target_language: str) -> str:
    """返回当前目标语言在内存中的专用翻译字段。"""
    if _is_chinese_target_language(target_language):
        return "description_zh"
    return f"description_{_normalized_translation_language(target_language)}"


def _text_value(value) -> str:
    """安全地读取并清理文本值。"""
    try:
        return str(value or "").strip()
    except Exception:
        return ""


def _repo_description_for_target(window, repo: dict) -> str:
    """按当前目标语言读取项目简介，找不到翻译时回退到原文。"""
    if not isinstance(repo, dict):
        return ""
    target_language = _translation_target_language(window)
    for field in _translation_field_candidates(target_language):
        value = _text_value(repo.get(field))
        if value:
            return value
    if _is_chinese_target_language(target_language):
        value = _text_value(repo.get("_brief"))
        if value:
            return value
    return _text_value(repo.get("description"))


def _truncate_repo_text(value: str, limit: int) -> str:
    """限制列表和提示中的简介长度，避免超长文本撑开界面。"""
    value = _text_value(value)
    if len(value) > limit:
        return value[: max(0, limit - 3)] + "…"
    return value


def _repo_list_brief_with_target_language(self, repo: dict) -> str:
    """列表简介使用当前语言，并保留旧版无简介提示。"""
    description = _truncate_repo_text(
        _repo_description_for_target(self, repo),
        80,
    )
    return description or "暂无简介"


_ORIGINAL_MAINWINDOW_REPO_LIST_BRIEF_FOR_TRANSLATION = MainWindow._repo_list_brief
_ORIGINAL_MAINWINDOW_SET_REPO_ITEM_METADATA_FOR_TRANSLATION = MainWindow._set_repo_item_metadata


def _set_repo_item_metadata_with_target_language(self, item, repo: dict):
    """同步设置项目标识和当前语言的悬停提示。"""
    try:
        _ORIGINAL_MAINWINDOW_SET_REPO_ITEM_METADATA_FOR_TRANSLATION(
            self,
            item,
            repo,
        )
    except Exception:
        pass

    full_name = _text_value(repo.get("full_name")) if isinstance(repo, dict) else ""
    description = _truncate_repo_text(
        _repo_description_for_target(self, repo),
        280,
    )
    html_url = ""
    if isinstance(repo, dict):
        html_url = _text_value(repo.get("html_url"))
    if not html_url and full_name:
        html_url = f"https://github.com/{full_name}"
    tooltip_parts = [part for part in (full_name, description, html_url) if part]
    try:
        item.setData(_Qt.ItemDataRole.UserRole, full_name)
        item.setToolTip("\n\n".join(tooltip_parts))
    except Exception:
        pass


def _iter_repo_dicts(value):
    """从常见列表或字典容器中提取项目字典。"""
    if isinstance(value, dict):
        values = value.values()
    elif isinstance(value, (list, tuple, set)):
        values = value
    else:
        return
    for candidate in values:
        if isinstance(candidate, dict):
            yield candidate


def _repo_index_for_window(window) -> dict[str, dict]:
    """建立项目名称索引，翻译完成后无需重新加载列表。"""
    index = {}
    attrs = (
        "_display_repos",
        "_repos",
        "_display_trending_items",
        "_trending_items",
        "_display_favorite_items",
        "_favorite_items",
        "_favorites",
    )
    containers = []
    for attr in attrs:
        try:
            containers.append(getattr(window, attr, None))
        except Exception:
            continue
    service = getattr(window, "service", None)
    containers.append(getattr(service, "favorites", None))
    for container in containers:
        for repo in _iter_repo_dicts(container):
            full_name = _text_value(repo.get("full_name"))
            if full_name:
                index[full_name.casefold()] = repo
    return index


def _list_fallback_repos(window, list_widget) -> list[dict]:
    """取得指定列表对应的数据顺序，兼容增量渲染中的多个字段名。"""
    try:
        if list_widget is getattr(window, "repo_list", None):
            attrs = ("_display_repos", "_repos")
        elif list_widget is getattr(window, "trending_list", None):
            attrs = ("_display_trending_items", "_trending_items")
        elif list_widget is getattr(window, "fav_list", None):
            attrs = (
                "_display_favorite_items",
                "_favorite_items",
                "_favorites",
            )
        else:
            attrs = (
                "_display_repos",
                "_repos",
                "_display_trending_items",
                "_trending_items",
                "_display_favorite_items",
                "_favorite_items",
            )
    except Exception:
        attrs = ("_repos",)

    for attr in attrs:
        try:
            repos = list(_iter_repo_dicts(getattr(window, attr, None)))
        except Exception:
            repos = []
        if repos:
            return repos
    return []


def _sync_translation_list_widget(window, list_widget, repo_index: dict[str, dict]) -> None:
    """只更新已有条目的简介和提示，不清空列表也不改变滚动位置。"""
    if list_widget is None:
        return
    try:
        count = int(list_widget.count())
    except Exception:
        return
    fallback_repos = _list_fallback_repos(window, list_widget)
    try:
        scroll_bar = list_widget.verticalScrollBar()
        scroll_value = int(scroll_bar.value())
    except Exception:
        scroll_bar = None
        scroll_value = None
    try:
        current_item = list_widget.currentItem()
    except Exception:
        current_item = None

    for index in range(count):
        try:
            item = list_widget.item(index)
        except Exception:
            continue
        if item is None:
            continue
        repo = None
        try:
            identity = _text_value(item.data(_Qt.ItemDataRole.UserRole))
        except Exception:
            identity = ""
        if identity:
            repo = repo_index.get(identity.casefold())
        if repo is None and index < len(fallback_repos):
            repo = fallback_repos[index]
        if not isinstance(repo, dict):
            continue

        try:
            old_text = str(item.text() or "")
        except Exception:
            old_text = ""
        header = old_text.split("\n", 1)[0] if old_text else ""
        brief = _repo_list_brief_with_target_language(window, repo)
        new_text = f"{header}\n{brief}" if header else brief
        try:
            if old_text != new_text:
                item.setText(new_text)
        except Exception:
            pass
        _set_repo_item_metadata_with_target_language(window, item, repo)

    try:
        if current_item is not None:
            list_widget.setCurrentItem(current_item)
    except Exception:
        pass
    if scroll_bar is not None and scroll_value is not None:
        try:
            scroll_bar.setValue(scroll_value)
        except Exception:
            pass


def _sync_all_translation_list_items(window) -> None:
    """同步发现、热榜和收藏三个项目列表中的当前语言文本。"""
    repo_index = _repo_index_for_window(window)
    list_attrs = ("repo_list", "trending_list", "fav_list")
    for attr in list_attrs:
        try:
            list_widget = getattr(window, attr, None)
        except Exception:
            list_widget = None
        _sync_translation_list_widget(window, list_widget, repo_index)


def _translation_repos_for_background(window, repos) -> list[dict]:
    """按原有判断找出本次后台翻译对应的项目。"""
    source_repos = [repo for repo in list(repos or []) if isinstance(repo, dict)]
    checker = getattr(window, "_repo_needs_translation", None)
    if not callable(checker):
        return source_repos
    try:
        return [repo for repo in source_repos if checker(repo)]
    except Exception:
        return source_repos


def _store_translation_result_for_target(window, repos, translated) -> None:
    """把后台结果写入目标语言字段，兼容原有中文字段和收藏数据。"""
    if isinstance(translated, str) or not isinstance(translated, (list, tuple)):
        return
    values = list(translated)
    source_repos = [repo for repo in list(repos or []) if isinstance(repo, dict)]
    if not source_repos or not values:
        return
    translation_repos = _translation_repos_for_background(window, source_repos)
    if len(values) == len(source_repos):
        paired_repos = source_repos
    elif len(values) == len(translation_repos):
        paired_repos = translation_repos
    else:
        paired_repos = translation_repos or source_repos

    target_language = _translation_target_language(window)
    storage_field = _translation_storage_field(target_language)
    for repo, value in zip(paired_repos, values):
        translated_text = _text_value(value)
        if not translated_text:
            continue
        repo[storage_field] = translated_text
        if _is_chinese_target_language(target_language):
            repo["description_zh"] = translated_text
        repo["_brief"] = translated_text


def _run_background_translation_with_list_sync(window, original, args, kwargs):
    """拦截翻译任务完成回调，确保列表控件立即显示最新翻译。"""
    source_repos = []
    if args:
        source_repos = args[0]
    elif "repos" in kwargs:
        source_repos = kwargs.get("repos")

    original_runner = getattr(window, "run_in_thread", None)
    if not callable(original_runner):
        return original(window, *args, **kwargs)

    window_dict = getattr(window, "__dict__", {})
    had_instance_runner = "run_in_thread" in window_dict
    old_instance_runner = window_dict.get("run_in_thread")

    def run_in_thread_proxy(
        fn,
        on_done=None,
        on_error=None,
        *extra_args,
        **extra_kwargs,
    ):
        captured = {"result": _TRANSLATION_RESULT_UNSET}

        def tracked_task(*task_args, **task_kwargs):
            result = fn(*task_args, **task_kwargs)
            captured["result"] = result
            return result

        def tracked_done(
            *callback_args,
            _callback=on_done,
            **callback_kwargs,
        ):
            result = captured.get("result", _TRANSLATION_RESULT_UNSET)
            if result is _TRANSLATION_RESULT_UNSET:
                for callback_arg in callback_args:
                    if isinstance(callback_arg, (list, tuple)):
                        result = callback_arg
                        break
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                _store_translation_result_for_target(
                    window,
                    source_repos,
                    result,
                )
                _sync_all_translation_list_items(window)

        def tracked_error(
            *callback_args,
            _callback=on_error,
            **callback_kwargs,
        ):
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                _sync_all_translation_list_items(window)

        return original_runner(
            tracked_task,
            tracked_done if callable(on_done) else on_done,
            tracked_error if callable(on_error) else on_error,
            *extra_args,
            **extra_kwargs,
        )

    window.run_in_thread = run_in_thread_proxy
    try:
        return original(window, *args, **kwargs)
    finally:
        try:
            if had_instance_runner:
                window.run_in_thread = old_instance_runner
            else:
                delattr(window, "run_in_thread")
        except Exception:
            window.run_in_thread = original_runner


