def _normalize_target_language_for_display(value) -> str:
    """兼容旧版本保存的语言名称和区域码。"""
    raw = _text_value(value)
    if not raw:
        return 'zh-CN'
    lowered = raw.casefold().replace('_', '-')
    aliases = {
        '中文': 'zh-CN',
        '简体中文': 'zh-CN',
        '繁体中文': 'zh-TW',
        '繁體中文': 'zh-TW',
        'english': 'en',
        '英语': 'en',
        '日本語': 'ja',
        '日语': 'ja',
        '한국어': 'ko',
        '韩语': 'ko',
        'français': 'fr',
        '法语': 'fr',
        'deutsch': 'de',
        '德语': 'de',
        'español': 'es',
        '西班牙语': 'es',
    }
    if lowered in aliases:
        return aliases[lowered]
    if lowered.startswith('zh-tw'):
        return 'zh-TW'
    if lowered.startswith('zh'):
        return 'zh-CN'
    for prefix, normalized in (
        ('en', 'en'),
        ('ja', 'ja'),
        ('ko', 'ko'),
        ('fr', 'fr'),
        ('de', 'de'),
        ('es', 'es'),
    ):
        if lowered.startswith(prefix):
            return normalized
    return raw


def _set_target_language_combo_guidance(dialog) -> None:
    """把语言选项统一为紧凑的中文显示，并补充可访问提示。"""
    combo = getattr(dialog, 'target_lang_combo', None)
    if combo is None:
        return

    selected = None
    try:
        selected = combo.currentData()
    except Exception:
        pass
    if not selected:
        service = getattr(dialog, 'service', None)
        config = getattr(service, 'config', {})
        if isinstance(config, dict):
            selected = config.get('target_language')
    selected = _normalize_target_language_for_display(selected)

    previous_blocked = False
    try:
        previous_blocked = combo.blockSignals(True)
        combo.clear()
        for label, value in _TARGET_LANGUAGE_DISPLAY_OPTIONS:
            index = combo.count()
            combo.addItem(label, value)
            combo.setItemData(
                index,
                _TARGET_LANGUAGE_DESCRIPTIONS.get(
                    value,
                    '使用所选语言翻译项目简介和 README。',
                ),
                _Qt.ItemDataRole.ToolTipRole,
            )
        selected_index = combo.findData(selected)
        if selected_index < 0:
            selected_index = combo.findData('zh-CN')
        if selected_index >= 0:
            combo.setCurrentIndex(selected_index)
    finally:
        try:
            combo.blockSignals(previous_blocked)
        except Exception:
            pass

    combo.setToolTip(
        '选择项目简介和 README 的翻译语言；不影响顶部的编程语言筛选。'
    )
    combo.setStatusTip('项目内容翻译语言')
    combo.setAccessibleName('项目内容翻译语言')
    combo.setAccessibleDescription(
        '用于选择项目简介和 README 的翻译语言，语言名称使用中文，完整说明放在提示信息中。'
    )
    try:
        combo.view().setToolTip('展开后选择项目内容翻译语言。')
    except Exception:
        pass
    try:
        combo.setMinimumWidth(max(220, combo.minimumSizeHint().width()))
    except Exception:
        pass

    try:
        labels = dialog.findChildren(QLabel)
    except Exception:
        labels = []
    for label in labels:
        try:
            if _text_value(label.text()) != '翻译目标语言':
                continue
            label.setText('项目内容翻译语言')
            label.setToolTip(
                '用于翻译项目简介和 README，不是项目编程语言筛选。'
            )
            label.setAccessibleName('项目内容翻译语言')
        except Exception:
            continue


