def _apply_main_filter_guidance(window) -> None:
    '''明确顶部编程语言筛选和项目内容翻译语言的区别。'''
    combo = getattr(window, 'lang_combo', None)
    if combo is not None:
        language_options = globals().get('LANG_OPTIONS') or ()
        for index in range(combo.count()):
            try:
                option_label = ''
                option_value = ''
                try:
                    option = language_options[index]
                except (IndexError, TypeError, KeyError):
                    option = None
                if isinstance(option, (list, tuple)):
                    if option:
                        option_label = _text_value(option[0])
                    if len(option) > 1:
                        option_value = _text_value(option[1])

                label = option_label or _text_value(combo.itemText(index))
                value = _text_value(combo.itemData(index)) or option_value
                if not value:
                    combo.setItemText(index, '全部语言（不限）')
                    combo.setItemData(index, '', _Qt.ItemDataRole.UserRole)
                    tip = '显示全部编程语言的项目。'
                else:
                    combo.setItemText(index, label or value)
                    combo.setItemData(index, value, _Qt.ItemDataRole.UserRole)
                    tip = f'仅显示主要编程语言为“{label or value}”的项目。'
                combo.setItemData(index, tip, _Qt.ItemDataRole.ToolTipRole)
            except Exception:
                continue
        combo.setToolTip(
            '这里筛选的是项目使用的编程语言，不是详情页翻译语言；翻译语言请打开“设置”。'
        )
        combo.setStatusTip('项目编程语言筛选')
        combo.setAccessibleName('项目编程语言筛选')
        combo.setAccessibleDescription(
            '用于筛选项目使用的主要编程语言，不会改变项目简介和 README 的翻译语言。'
        )
        try:
            combo.view().setToolTip('选择项目使用的编程语言。')
        except Exception:
            pass

    view_combo = getattr(window, 'view_combo', None)
    if view_combo is not None:
        for index in range(view_combo.count()):
            try:
                value = _text_value(view_combo.itemData(index)).casefold()
                label = _VIEW_DISPLAY_LABELS.get(value)
                if not label:
                    continue
                view_combo.setItemText(index, label)
                view_combo.setItemData(
                    index,
                    f'切换到“{label}”页面。',
                    _Qt.ItemDataRole.ToolTipRole,
                )
            except Exception:
                continue
        view_combo.setToolTip('选择要查看的项目页面。')
        view_combo.setAccessibleName('项目页面')

    settings_button = getattr(window, 'settings_btn', None)
    if settings_button is not None:
        settings_button.setToolTip(
            '打开设置，在“项目内容翻译语言”中选择简介和 README 的翻译语言。'
        )
        settings_button.setStatusTip('打开设置')


