def _translation_storage_field_with_language_variant(target_language: str) -> str:
    # 繁体中文使用独立字段，避免覆盖简体中文翻译；其他语言沿用语言代码字段。
    normalized = _normalized_translation_language(target_language)
    if normalized == 'zh_tw':
        return 'description_zh_tw'
    if _is_chinese_target_language(target_language):
        return 'description_zh'
    return f'description_{normalized}'


_translation_storage_field = _translation_storage_field_with_language_variant

_DETAIL_TRANSLATION_FIELD_MISSING = object()


def _restore_detail_translation_field(repo, field: str, previous) -> None:
    if not isinstance(repo, dict):
        return
    if previous is _DETAIL_TRANSLATION_FIELD_MISSING:
        repo.pop(field, None)
    else:
        repo[field] = previous


_ORIGINAL_STORE_TRANSLATION_RESULT_FOR_SINGLE_LANGUAGE = (
    _store_translation_result_for_target
)


def _store_translation_result_for_single_language(window, repos, translated) -> None:
    # 旧版后台翻译会把所有语言都额外写入 description_zh 和 _brief，先保存再恢复，
    # 防止切换到英文后污染中文缓存，也防止繁体中文覆盖简体中文。
    target_language = _translation_target_language(window)
    storage_field = _translation_storage_field(target_language)
    preserve_legacy_fields = storage_field != 'description_zh'
    snapshots = []
    if preserve_legacy_fields:
        for repo in list(repos or []):
            if not isinstance(repo, dict):
                continue
            snapshots.append(
                (
                    repo,
                    repo.get('description_zh', _DETAIL_TRANSLATION_FIELD_MISSING),
                    repo.get('_brief', _DETAIL_TRANSLATION_FIELD_MISSING),
                )
            )
    try:
        _ORIGINAL_STORE_TRANSLATION_RESULT_FOR_SINGLE_LANGUAGE(
            window,
            repos,
            translated,
        )
    finally:
        if preserve_legacy_fields:
            for repo, previous_description_zh, previous_brief in snapshots:
                _restore_detail_translation_field(
                    repo,
                    'description_zh',
                    previous_description_zh,
                )
                _restore_detail_translation_field(repo, '_brief', previous_brief)


_store_translation_result_for_target = _store_translation_result_for_single_language


def _set_target_language_combo_guidance_single_language(dialog) -> None:
    # 复用原有选项重建逻辑，再统一覆盖提示文字和最小宽度。
    _ORIGINAL_SET_TARGET_LANGUAGE_COMBO_GUIDANCE_FOR_SINGLE_LANGUAGE(dialog)
