def _detail_translation_context_is_current(window, request_id, repo) -> bool:
    # 旧任务被切换项目取消后，不再把结果写回新项目详情页。
    current_request_id = getattr(window, '_detail_request_id', None)
    if current_request_id is not None and current_request_id != request_id:
        return False
    current_repo = getattr(window, 'current_repo', None)
    if current_repo is not None and current_repo is not repo:
        return False
    return True


def _restore_detail_translation_compat_fields(
    repo,
    previous_description_zh,
    previous_brief,
    storage_field,
) -> None:
    if storage_field != 'description_zh':
        _restore_detail_translation_field(
            repo,
            'description_zh',
            previous_description_zh,
        )
    _restore_detail_translation_field(repo, '_brief', previous_brief)


def _sync_detail_translation_result_for_target(
    window,
    repo,
    result,
    target_language,
    previous_description_zh,
    previous_brief,
) -> None:
    if not isinstance(repo, dict):
        return
    storage_field = _translation_storage_field(target_language)
    translated_text = ''
    if isinstance(result, dict):
        translated_text = _text_value(result.get('description_zh'))
        if not translated_text:
            translated_text = _text_value(result.get(storage_field))
        if translated_text:
            repo[storage_field] = translated_text
    _restore_detail_translation_compat_fields(
        repo,
        previous_description_zh,
        previous_brief,
        storage_field,
    )

    if _detail_translation_context_is_current(
        window,
        getattr(window, '_detail_request_id', None),
        repo,
    ):
        current_target_language = _translation_target_language(window)
    else:
        current_target_language = target_language
    if (
        _normalized_translation_language(current_target_language)
        == _normalized_translation_language(target_language)
    ):
        display_text = _text_value(repo.get(storage_field))
    else:
        display_text = _repo_description_for_target(window, repo)
    if not display_text and isinstance(result, dict):
        display_text = _text_value(result.get('description'))
    if not display_text:
        display_text = _text_value(repo.get('description'))
    label = getattr(window, 'desc_label', None)
    if label is not None and display_text:
        try:
            label.setText(display_text)
        except Exception:
            pass


def _start_detail_translation_for_target_language(
    self,
    repo,
    request_id,
    source_readme,
):
    # 翻译服务本身已按 service.config 的目标语言工作，这里只适配详情页的
    # 结果字段和初始简介，避免原始恢复代码把非中文结果固定写入 description_zh。
    original_runner = getattr(self, 'run_in_thread', None)
    if not callable(original_runner):
        return _ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_FOR_STATE(
            self,
            repo,
            request_id,
            source_readme,
        )

    target_language = _translation_target_language(self)
    if isinstance(repo, dict):
        previous_description_zh = repo.get(
            'description_zh',
            _DETAIL_TRANSLATION_FIELD_MISSING,
        )
        previous_brief = repo.get('_brief', _DETAIL_TRANSLATION_FIELD_MISSING)
    else:
        previous_description_zh = _DETAIL_TRANSLATION_FIELD_MISSING
        previous_brief = _DETAIL_TRANSLATION_FIELD_MISSING
    storage_field = _translation_storage_field(target_language)

    window_dict = getattr(self, '__dict__', {})
    had_instance_runner = 'run_in_thread' in window_dict
    old_instance_runner = window_dict.get('run_in_thread')

    def run_in_thread_proxy(
        fn,
        on_done=None,
        on_error=None,
        *extra_args,
        **extra_kwargs,
    ):
        captured = {'result': _TRANSLATION_RESULT_UNSET}

        def tracked_task(*task_args, **task_kwargs):
            result = fn(*task_args, **task_kwargs)
            captured['result'] = result
            return result

        def tracked_done(
            *callback_args,
            _callback=on_done,
            **callback_kwargs,
        ):
            result = captured.get('result', _TRANSLATION_RESULT_UNSET)
            if result is _TRANSLATION_RESULT_UNSET:
                for callback_arg in callback_args:
                    if isinstance(callback_arg, dict):
                        result = callback_arg
                        break
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                if _detail_translation_context_is_current(
                    self,
                    request_id,
                    repo,
                ):
                    _sync_detail_translation_result_for_target(
                        self,
                        repo,
                        result,
                        target_language,
                        previous_description_zh,
                        previous_brief,
                    )
                else:
                    _restore_detail_translation_compat_fields(
                        repo,
                        previous_description_zh,
                        previous_brief,
                        storage_field,
                    )

        def tracked_error(
            *callback_args,
            _callback=on_error,
            **callback_kwargs,
        ):
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                _restore_detail_translation_compat_fields(
                    repo,
                    previous_description_zh,
                    previous_brief,
                    storage_field,
                )

        return original_runner(
            tracked_task,
            tracked_done if callable(on_done) else on_done,
            tracked_error if callable(on_error) else on_error,
            *extra_args,
            **extra_kwargs,
        )

    self.run_in_thread = run_in_thread_proxy
    try:
        return _ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_FOR_STATE(
            self,
            repo,
            request_id,
            source_readme,
        )
    finally:
        try:
            if had_instance_runner:
                self.run_in_thread = old_instance_runner
            else:
                delattr(self, 'run_in_thread')
        except Exception:
            self.run_in_thread = original_runner


_ORIGINAL_MAINWINDOW_DETAIL_TRANSLATION_STATE_WRAPPER_FOR_TARGET = (
    MainWindow._start_detail_translation
)


def _start_detail_translation_with_target_language_and_state(
    self,
    repo,
    request_id,
    source_readme,
):
    # 保留详情阶段状态、取消旧任务和超时看门狗逻辑，仅替换翻译结果适配层。
    already_running = bool(getattr(self, '_detail_translation_running', False))
    manage_state = (
        not already_running
        and _detail_state_matches(self, request_id, repo)
    )
    if not manage_state:
        return _start_detail_translation_for_target_language(
            self,
            repo,
            request_id,
            source_readme,
        )
    _prepare_detail_stage(self, 'translation', request_id)
    previous = _set_detail_stage_hints(self, ['translation'])
    before = int(getattr(self, '_async_submit_seq', 0))
    try:
        return _start_detail_translation_for_target_language(
            self,
            repo,
            request_id,
            source_readme,
        )
    finally:
        _restore_detail_stage_hints(self, previous)
        if int(getattr(self, '_async_submit_seq', 0)) == before:
            _complete_unsent_detail_stage(self, 'translation', request_id)


MainWindow._start_detail_translation = (
    _start_detail_translation_with_target_language_and_state
)


