# ------------------------------ 主界面语言联动与翻译服务配置 ------------------------------

from PyQt6.QtWidgets import (
    QComboBox as _QComboBox,
    QFormLayout as _QFormLayout,
    QHBoxLayout as _QHBoxLayout,
    QLabel as _QLabel,
    QLineEdit as _QLineEdit,
    QTabWidget as _QTabWidget,
    QWidget as _QWidget,
)


_TRANSLATION_PROVIDER_OPTIONS = (
    ("自动选择（推荐）", "auto"),
    ("腾讯云翻译", "tencent"),
    ("DeepL", "deepl"),
    ("Google Cloud 翻译", "google"),
    ("OpenAI 兼容接口", "openai_compatible"),
    ("本地规则（离线）", "local"),
)
_TRANSLATION_PROVIDER_VALUES = {value for _, value in _TRANSLATION_PROVIDER_OPTIONS}
_TRANSLATION_PROVIDER_DEFAULT_ENDPOINTS = {
    "deepl": "https://api-free.deepl.com/v2/translate",
    "google": "https://translation.googleapis.com/language/translate/v2",
    "openai_compatible": "https://api.openai.com/v1/chat/completions",
}
_TRANSLATION_DEFAULT_CONFIG = {
    "translation_provider": "auto",
    "translation_api_url": "",
    "translation_api_key": "",
    "translation_model": "",
}


_default_config = globals().get("DEFAULT_CONFIG")
if not isinstance(_default_config, dict):
    _default_config = _RECOVERED_NAMESPACE.get("DEFAULT_CONFIG")
if isinstance(_default_config, dict):
    for _config_key, _config_value in _TRANSLATION_DEFAULT_CONFIG.items():
        _default_config.setdefault(_config_key, _config_value)
    _RECOVERED_NAMESPACE["DEFAULT_CONFIG"] = _default_config
    globals()["DEFAULT_CONFIG"] = _default_config


def _normalize_translation_provider(value) -> str:
    """把旧版本或手工填写的服务名称转换为稳定的服务标识。"""
    raw = _text_value(value).casefold()
    normalized = raw.replace("-", "_").replace(" ", "_")
    aliases = {
        "": "auto",
        "自动": "auto",
        "自动选择": "auto",
        "tencent_cloud": "tencent",
        "腾讯云": "tencent",
        "google_cloud": "google",
        "google_translate": "google",
        "openai": "openai_compatible",
        "chatgpt": "openai_compatible",
        "custom": "openai_compatible",
        "offline": "local",
        "本地": "local",
    }
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in _TRANSLATION_PROVIDER_VALUES else "auto"


def _translation_provider(config=None) -> str:
    """读取当前翻译服务，未知配置统一回到自动模式。"""
    if not isinstance(config, dict):
        config = {}
    return _normalize_translation_provider(config.get("translation_provider"))


def _translation_endpoint(config, provider: str) -> str:
    """返回服务接口地址；空地址使用对应服务的官方默认地址。"""
    provider = _normalize_translation_provider(provider)
    value = _text_value((config or {}).get("translation_api_url"))
    if value:
        if provider == "openai_compatible":
            stripped = value.rstrip("/")
            if stripped.endswith("/chat/completions"):
                return stripped
            if stripped.endswith("/v1"):
                return stripped + "/chat/completions"
            if stripped.endswith("/openai"):
                return stripped + "/v1/chat/completions"
            return stripped + "/v1/chat/completions"
        return value
    return _TRANSLATION_PROVIDER_DEFAULT_ENDPOINTS.get(provider, "")


def _translation_language_code(target_language: str, deepl: bool = False) -> str:
    """把界面语言转换为第三方接口使用的语言代码。"""
    normalized = _normalize_target_language_for_display(target_language)
    if deepl:
        return {
            "zh-CN": "ZH",
            "zh-TW": "ZH",
            "en": "EN",
            "ja": "JA",
            "ko": "KO",
            "fr": "FR",
            "de": "DE",
            "es": "ES",
        }.get(normalized, normalized.split("-", 1)[0].upper())
    return {
        "zh-CN": "zh-CN",
        "zh-TW": "zh-TW",
        "en": "en",
        "ja": "ja",
        "ko": "ko",
        "fr": "fr",
        "de": "de",
        "es": "es",
    }.get(normalized, normalized)


def _translation_response_json(response):
    """统一解析接口响应，并尽量兼容缺少 json 方法的测试响应。"""
    raise_for_status = getattr(response, "raise_for_status", None)
    if callable(raise_for_status):
        raise_for_status()
    json_method = getattr(response, "json", None)
    if callable(json_method):
        return json_method()
    return _json.loads(getattr(response, "text", "") or "{}")


def _translation_result_is_valid(source: str, result) -> bool:
    """判断接口返回值是否像真正译文，过滤错误页和空响应。"""
    translated = _text_value(result)
    if not translated:
        return False
    try:
        return bool(_is_valid_translation(source, translated))
    except Exception:
        return translated != _text_value(source)


def _translate_with_deepl(text: str, source: str, target: str, config, deadline=None) -> str:
    """调用 DeepL 文本翻译接口。"""
    api_key = _text_value((config or {}).get("translation_api_key"))
    if not api_key:
        return ""
    payload = {
        "text": text,
        "target_lang": _translation_language_code(target, deepl=True),
    }
    source_code = _translation_source_code(source)
    if source_code and source_code != "auto":
        payload["source_lang"] = _translation_language_code(source_code, deepl=True)
    headers = {
        "Authorization": f"DeepL-Auth-Key {api_key}",
        "User-Agent": "GitHubOpenSourceBrowser/2.0",
    }
    response = _requests.post(
        _translation_endpoint(config, "deepl"),
        data=payload,
        headers=headers,
        timeout=_translation_timeout(deadline),
        **_translation_request_options(config),
    )
    data = _translation_response_json(response)
    translations = data.get("translations") if isinstance(data, dict) else None
    if not isinstance(translations, list) or not translations:
        return ""
    first = translations[0]
    return _text_value(first.get("text")) if isinstance(first, dict) else ""


def _translate_with_google_cloud(text: str, source: str, target: str, config, deadline=None) -> str:
    """调用 Google Cloud Translation v2 接口。"""
    api_key = _text_value((config or {}).get("translation_api_key"))
    if not api_key:
        return ""
    params = {"key": api_key}
    payload = {
        "q": [text],
        "target": _translation_language_code(target),
        "format": "text",
    }
    source_code = _translation_source_code(source)
    if source_code and source_code != "auto":
        payload["source"] = _translation_language_code(source_code)
    response = _requests.post(
        _translation_endpoint(config, "google"),
        params=params,
        json=payload,
        timeout=_translation_timeout(deadline),
        **_translation_request_options(config),
    )
    data = _translation_response_json(response)
    root = data.get("data", data) if isinstance(data, dict) else {}
    translations = root.get("translations") if isinstance(root, dict) else None
    if not isinstance(translations, list) or not translations:
        return ""
    first = translations[0]
    return _text_value(first.get("translatedText")) if isinstance(first, dict) else ""


def _openai_compatible_content(data) -> str:
    """从兼容 Chat Completions 的响应中提取文本。"""
    if not isinstance(data, dict):
        return ""
    choices = data.get("choices")
    if not isinstance(choices, list) or not choices:
        return _text_value(data.get("output_text"))
    first = choices[0]
    if not isinstance(first, dict):
        return ""
    message = first.get("message")
    if isinstance(message, dict):
        content = message.get("content")
        if isinstance(content, str):
            return _text_value(content)
        if isinstance(content, list):
            parts = []
            for part in content:
                if isinstance(part, dict):
                    value = part.get("text")
                    if value:
                        parts.append(str(value))
            return _text_value("".join(parts))
    return _text_value(first.get("text"))


def _translate_with_openai_compatible(
    text: str,
    source: str,
    target: str,
    config,
    deadline=None,
) -> str:
    """调用 OpenAI 兼容接口，覆盖 OpenAI、DeepSeek 等兼容服务。"""
    config = config or {}
    endpoint = _translation_endpoint(config, "openai_compatible")
    if not endpoint:
        return ""
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "GitHubOpenSourceBrowser/2.0",
    }
    api_key = _text_value(config.get("translation_api_key"))
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    model = _text_value(config.get("translation_model")) or "gpt-4o-mini"
    source_label = _translation_language_code(source) if source else "auto"
    target_label = _translation_language_code(target)
    system_prompt = (
        "你是严谨的技术翻译引擎。只输出译文，不要解释、不要加引号。"
        "保留 Markdown、链接、代码、命令、占位符和换行结构；不要翻译代码和链接中的内容。"
    )
    user_prompt = (
        f"源语言：{source_label}\n目标语言：{target_label}\n"
        "请翻译下面的技术文本：\n"
        f"{text}"
    )
    payload = {
        "model": model,
        "temperature": 0,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
    }
    response = _requests.post(
        endpoint,
        json=payload,
        headers=headers,
        timeout=_translation_timeout(deadline),
        **_translation_request_options(config),
    )
    return _openai_compatible_content(_translation_response_json(response))


_ORIGINAL_TRANSLATE_SHORT_TEXT_WITH_PROVIDER = _translate_short_text_with_status


def _translate_short_text_with_provider(
    text: str,
    source: str,
    target: str,
    config=None,
    deadline=None,
) -> tuple[str, bool]:
    """按设置选择翻译服务；明确服务失败时只回退离线规则，不串用其他网络服务。"""
    text = _text_value(text)
    if not text:
        return "", False
    config = config if isinstance(config, dict) else {}
    provider = _translation_provider(config)
    if provider == "auto":
        return _ORIGINAL_TRANSLATE_SHORT_TEXT_WITH_PROVIDER(
            text,
            source,
            target,
            config,
            deadline,
        )

    translated = ""
    try:
        if provider == "local":
            translated = _local_translate(text, target)
        elif provider == "tencent":
            secret_id, secret_key = _translation_credentials(config)
            if secret_id and secret_key:
                translated = _tencent_translate(
                    text,
                    secret_id,
                    secret_key,
                    _translation_source_code(source),
                    target,
                    config,
                    deadline,
                ) or ""
        elif provider == "deepl":
            translated = _translate_with_deepl(
                text,
                source,
                target,
                config,
                deadline,
            )
        elif provider == "google":
            translated = _translate_with_google_cloud(
                text,
                source,
                target,
                config,
                deadline,
            )
        elif provider == "openai_compatible":
            translated = _translate_with_openai_compatible(
                text,
                source,
                target,
                config,
                deadline,
            )
    except Exception:
        _write_startup_log(
            f"翻译服务 {provider} 请求失败，已回退离线规则",
            _sys.exc_info(),
        )

    if _translation_result_is_valid(text, translated):
        return _text_value(translated), True
    try:
        local_result = _local_translate(text, target)
    except Exception:
        local_result = text
    return _text_value(local_result) or text, False


_translate_short_text_with_status = _translate_short_text_with_provider
