_ORIGINAL_BATCH_TRANSLATE_WITH_PROVIDER = GitHubService.batch_translate
_ORIGINAL_BATCH_CACHE_TRANSLATE_WITH_PROVIDER = _batch_translate_with_cache


def _translation_cache_key_for_provider(target_language, text: str, config=None) -> str:
    """给明确服务增加独立缓存空间，避免更换接口后复用旧译文。"""
    base_key = _translation_cache_key(target_language, text)
    provider = _translation_provider(config)
    if provider == "auto":
        return base_key
    scope = "|".join(
        (
            provider,
            _translation_endpoint(config or {}, provider),
            _text_value((config or {}).get("translation_model")),
        )
    )
    digest = _hashlib.sha1(scope.encode("utf-8", "ignore")).hexdigest()[:16]
    return f"{base_key}::provider::{digest}"


def _batch_translate_with_selected_provider(self, texts: list[str]) -> list[str]:
    """自动模式复用原有批量接口，明确服务使用独立缓存并保持并发轻量。"""
    config = getattr(self, "config", {}) or {}
    if _translation_provider(config) == "auto":
        return _ORIGINAL_BATCH_CACHE_TRANSLATE_WITH_PROVIDER(self, texts)
    if not texts:
        return []
    target_language = _normalize_target_language_for_display(
        config.get("target_language", "zh-CN")
    )
    translated_map = {}
    missing_texts = []
    cache_keys = {}
    for text in list(dict.fromkeys(text for text in texts if _text_value(text))):
        cache_key = _translation_cache_key_for_provider(
            target_language,
            text,
            config,
        )
        cache_keys[text] = cache_key
        cached = _read_translation_cache_value(self, cache_key, text)
        if cached is None:
            missing_texts.append(text)
        else:
            translated_map[text] = cached

    for source in missing_texts:
        try:
            result, _used_external = _translate_text_with_status(
                source,
                "auto",
                target_language,
                config,
            )
        except Exception:
            result = source
        result = _text_value(result) or source
        translated_map[source] = result
        if _translation_result_is_valid(source, result):
            _write_translation_cache_value(self, cache_keys[source], result)

    return [
        translated_map.get(text, text) if _text_value(text) else text
        for text in texts
    ]


GitHubService.batch_translate = _batch_translate_with_selected_provider


_ORIGINAL_SERVICE_TRANSLATE_DESCRIPTION_FOR_PROVIDER = GitHubService.translate_description
_ORIGINAL_SERVICE_TRANSLATE_README_FOR_PROVIDER = (
    GitHubService.translate_readme_markdown_with_status
)


def _provider_translation_cache_scope(config) -> str:
    provider = _translation_provider(config)
    if provider == "auto":
        return ""
    raw = "|".join(
        (
            provider,
            _translation_endpoint(config or {}, provider),
            _text_value((config or {}).get("translation_model")),
        )
    )
    return _hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()[:16]


def _service_translate_description_with_provider_cache(self, text: str, deadline=None) -> str:
    """明确选择第三方服务时使用独立简介缓存，自动模式保持旧行为。"""
    config = getattr(self, "config", {}) or {}
    if _translation_provider(config) == "auto":
        return _ORIGINAL_SERVICE_TRANSLATE_DESCRIPTION_FOR_PROVIDER(
            self,
            text,
            deadline,
        )
    source = _text_value(text)
    if not source:
        return source
    target = _normalize_target_language_for_display(
        config.get("target_language", "zh-CN")
    )
    key = _translation_cache_key_for_provider(target, source, config)
    cached = _read_translation_cache_value(self, key, source)
    if cached:
        return cached
    translated, used_external = _translate_text_with_status(
        source,
        "auto",
        target,
        config,
        deadline,
    )
    result = _text_value(translated) or source
    if used_external and _translation_result_is_valid(source, result):
        _write_translation_cache_value(self, key, result)
    return result


def _service_translate_readme_with_provider_cache(
    self,
    markdown_text: str,
    full_name: str = "",
    branch: str = "main",
    deadline=None,
) -> tuple[str, bool]:
    """明确选择第三方服务时使用独立 README 缓存，避免旧接口结果串用。"""
    config = getattr(self, "config", {}) or {}
    if _translation_provider(config) == "auto":
        return _ORIGINAL_SERVICE_TRANSLATE_README_FOR_PROVIDER(
            self,
            markdown_text,
            full_name,
            branch,
            deadline,
        )
    source = str(markdown_text or "")
    if not source.strip():
        return "", False
    target = _normalize_target_language_for_display(
        config.get("target_language", "zh-CN")
    )
    digest = _hashlib.sha1(source.encode("utf-8", "ignore")).hexdigest()
    scope = _provider_translation_cache_scope(config)
    key = (
        f"readme_md_{README_TRANSLATION_CACHE_VERSION}::{target}::"
        f"{full_name}::{branch}::{digest}::provider::{scope}"
    )
    cached = _read_translation_cache_value(self, key, source)
    if cached:
        return cached, True
    translated, used_external = _translate_readme_markdown_text(
        source,
        target,
        config,
        deadline,
    )
    result = str(translated or source)
    if used_external and _translation_result_is_valid(source, result):
        _write_translation_cache_value(self, key, result)
    return result, bool(used_external)


