def _translation_field_candidates_for_selected_language(target_language: str) -> list[str]:
    """只读取当前语言字段，避免繁体或其他语言误用简体中文缓存。"""
    normalized = _normalized_translation_language(target_language)
    storage = _translation_storage_field(target_language)
    fields = [storage]
    base = normalized.split("_", 1)[0]
    base_field = f"description_{base}"
    if base_field != storage:
        fields.append(base_field)
    return fields


_translation_field_candidates = _translation_field_candidates_for_selected_language
