_ORIGINAL_RUN_BACKGROUND_TRANSLATION_WITH_GENERATION = (
    _run_background_translation_with_list_sync
)


def _run_background_translation_with_generation(
    window,
    original,
    args,
    kwargs,
):
    """后台翻译完成时校验语言代际，丢弃切换语言前提交的旧结果。"""
    job_generation = int(getattr(window, "_translation_language_generation", 0))
    source_repos = args[0] if args else kwargs.get("repos", [])
    original_runner = getattr(window, "run_in_thread", None)
    if not callable(original_runner):
        return original(window, *args, **kwargs)
    window_dict = getattr(window, "__dict__", {})
    had_instance_runner = "run_in_thread" in window_dict
    old_instance_runner = window_dict.get("run_in_thread")

    def run_in_thread_proxy(
        fn,
        on_done=None,
        on_error=None,
        *extra_args,
        **extra_kwargs,
    ):
        captured = {"result": _TRANSLATION_RESULT_UNSET}

        def tracked_task(*task_args, **task_kwargs):
            result = fn(*task_args, **task_kwargs)
            captured["result"] = result
            return result

        def tracked_done(*callback_args, _callback=on_done, **callback_kwargs):
            result = captured.get("result", _TRANSLATION_RESULT_UNSET)
            if result is _TRANSLATION_RESULT_UNSET:
                for callback_arg in callback_args:
                    if isinstance(callback_arg, (list, tuple)):
                        result = callback_arg
                        break
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                if job_generation == int(
                    getattr(window, "_translation_language_generation", 0)
                ):
                    _store_translation_result_for_target(
                        window,
                        source_repos,
                        result,
                    )
                    _sync_all_translation_list_items(window)

        def tracked_error(*callback_args, _callback=on_error, **callback_kwargs):
            try:
                if callable(_callback):
                    return _callback(*callback_args, **callback_kwargs)
                return None
            finally:
                if job_generation == int(
                    getattr(window, "_translation_language_generation", 0)
                ):
                    _sync_all_translation_list_items(window)

        return original_runner(
            tracked_task,
            tracked_done if callable(on_done) else on_done,
            tracked_error if callable(on_error) else on_error,
            *extra_args,
            **extra_kwargs,
        )

    window.run_in_thread = run_in_thread_proxy
    try:
        return original(window, *args, **kwargs)
    finally:
        try:
            if had_instance_runner:
                window.run_in_thread = old_instance_runner
            else:
                delattr(window, "run_in_thread")
        except Exception:
            window.run_in_thread = original_runner


_run_background_translation_with_list_sync = _run_background_translation_with_generation


