    tencent_id = getattr(dialog, "tencent_id_edit", None)
    tencent_key = getattr(dialog, "tencent_key_edit", None)
    if tencent_id is not None:
        labels = dialog._translation_setting_labels
        tencent_label_id = labels.get("tencent_id")
        if tencent_label_id is None:
            for candidate in dialog.findChildren(_QFormLayout):
                for row in range(candidate.rowCount()):
                    if _form_item_widget(
                        candidate,
                        row,
                        _QFormLayout.ItemRole.FieldRole,
                    ) is tencent_id:
                        tencent_label_id = _form_item_widget(
                            candidate,
                            row,
                            _QFormLayout.ItemRole.LabelRole,
                        )
                        break
                if tencent_label_id is not None:
                    break
        if tencent_label_id is not None:
            labels["tencent_id"] = tencent_label_id
        dialog._translation_setting_rows["tencent_id"] = (
            tencent_label_id,
            tencent_id,
        )
    if tencent_key is not None:
        labels = dialog._translation_setting_labels
        tencent_label_key = labels.get("tencent_key")
        if tencent_label_key is None:
            for candidate in dialog.findChildren(_QFormLayout):
                for row in range(candidate.rowCount()):
                    if _form_item_widget(
                        candidate,
                        row,
                        _QFormLayout.ItemRole.FieldRole,
                    ) is tencent_key:
                        tencent_label_key = _form_item_widget(
                            candidate,
                            row,
                            _QFormLayout.ItemRole.LabelRole,
                        )
                        break
                if tencent_label_key is not None:
                    break
        if tencent_label_key is not None:
            labels["tencent_key"] = tencent_label_key
        dialog._translation_setting_rows["tencent_key"] = (
            tencent_label_key,
            tencent_key,
        )

    for key, widget in (
        ("api_url", api_url_edit),
        ("api_key", api_key_edit),
        ("model", model_edit),
    ):
        dialog._translation_setting_rows[key] = (
            dialog._translation_setting_labels.get(key),
            widget,
        )
