    tabs = dialog.findChildren(_QTabWidget)
    for tab_widget in tabs:
        page = tencent_id
        while page is not None:
            try:
                tab_index = tab_widget.indexOf(page)
            except Exception:
                tab_index = -1
            if tab_index >= 0:
                tab_widget.setTabText(tab_index, "翻译服务")
                break
            page = page.parentWidget()


