def _main_content_language_value(window) -> str:
    combo = getattr(window, "contentLanguageCombo", None)
    value = None
    if combo is not None:
        try:
            value = combo.currentData()
        except Exception:
            value = None
    if not value:
        config = getattr(getattr(window, "service", None), "config", {}) or {}
        value = config.get("target_language", "zh-CN")
    value = _normalize_target_language_for_display(value)
    return value if value in _TARGET_LANGUAGE_VALUES else "zh-CN"


def _refresh_translation_for_current_view(window, generation: int) -> None:
    if generation != int(getattr(window, "_translation_language_generation", 0)):
        return
    _sync_all_translation_list_items(window)
    mode = ""
    try:
        mode = _text_value(window.view_combo.currentData()).casefold()
    except Exception:
        pass
    try:
        if mode == "discover":
            repos = _list_fallback_repos(window, getattr(window, "repo_list", None))
            if repos:
                window._start_background_translate(
                    repos,
                    getattr(window, "_search_request_id", None),
                )
        elif mode == "trending":
            repos = _list_fallback_repos(window, getattr(window, "trending_list", None))
            if repos:
                window._start_background_trending_translate(
                    repos,
                    getattr(window, "_trending_request_id", None),
                )
        elif mode == "favorites":
            repos = _list_fallback_repos(window, getattr(window, "fav_list", None))
            if repos:
                window._start_background_favorite_translate(
                    repos,
                    getattr(window, "_search_request_id", None),
                )
    except Exception:
        _write_startup_log("切换翻译语言后安排列表翻译失败", _sys.exc_info())

    repo = getattr(window, "current_repo", None)
    readme = _text_value(getattr(window, "_detail_readme_markdown", ""))
    if isinstance(repo, dict):
        label = getattr(window, "desc_label", None)
        if label is not None:
            try:
                label.setText(_repo_description_for_target(window, repo) or "暂无描述")
            except Exception:
                pass
        if readme:
            try:
                window._translate_current_detail()
            except Exception:
                _write_startup_log("切换翻译语言后安排详情翻译失败", _sys.exc_info())


def _on_content_language_changed(window, _index=None) -> None:
    combo = getattr(window, "contentLanguageCombo", None)
    if combo is None:
        return
    target = _main_content_language_value(window)
    service = getattr(window, "service", None)
    config = getattr(service, "config", None)
    if not isinstance(config, dict):
        return
    previous = _normalize_target_language_for_display(
        config.get("target_language", "zh-CN")
    )
    config["target_language"] = target
    if previous == target:
        _sync_all_translation_list_items(window)
        return
    generation = int(getattr(window, "_translation_language_generation", 0)) + 1
    window._translation_language_generation = generation
    try:
        save_config = getattr(service, "save_config", None)
        if callable(save_config):
            save_config()
    except Exception:
        _write_startup_log("保存主界面翻译语言失败", _sys.exc_info())
    try:
        invalidate = getattr(window, "_invalidate_detail_request", None)
        if callable(invalidate):
            invalidate()
    except Exception:
        _write_startup_log("切换翻译语言时取消旧详情任务失败", _sys.exc_info())
    _sync_all_translation_list_items(window)
    _QTimer.singleShot(
        0,
        lambda: _refresh_translation_for_current_view(window, generation),
    )


def _install_main_content_language_selector(window) -> None:
    """在项目编程语言筛选旁增加独立的翻译语言选项，避免两者混淆。"""
    if getattr(window, "contentLanguageCombo", None) is not None:
        return
    language_filter = getattr(window, "lang_combo", None)
    if language_filter is None or language_filter.parentWidget() is None:
        return
    root = language_filter.parentWidget()
    root_layout = root.layout()
    toolbar = None
    if root_layout is not None:
        for index in range(root_layout.count()):
            item = root_layout.itemAt(index)
            candidate = item.layout() if item is not None else None
            if candidate is not None and candidate.indexOf(language_filter) >= 0:
                toolbar = candidate
                break
    if toolbar is None:
        return
    language_index = toolbar.indexOf(language_filter)
    if language_index < 0:
        return

    selector = _QWidget(root)
    selector.setObjectName("contentLanguageSelector")
    selector_layout = _QHBoxLayout(selector)
    selector_layout.setContentsMargins(0, 0, 0, 0)
    selector_layout.setSpacing(4)
    label = _QLabel("翻译：", selector)
    label.setObjectName("contentLanguageLabel")
    label.setToolTip("项目简介和 README 的目标语言")
    combo = _QComboBox(selector)
    combo.setObjectName("contentLanguageCombo")
    combo.setMinimumWidth(88)
    combo.setMaximumWidth(116)
    for text, value in _TARGET_LANGUAGE_DISPLAY_OPTIONS:
        combo.addItem(text, value)
    selected = _main_content_language_value(window)
    selected_index = combo.findData(selected)
    if selected_index >= 0:
        combo.setCurrentIndex(selected_index)
    combo.setToolTip(
        "选择项目简介和 README 的翻译语言；左侧“全部语言”仍用于筛选项目编程语言。"
    )
    combo.setStatusTip("项目内容翻译语言")
    combo.setAccessibleName("项目内容翻译语言")
    combo.setAccessibleDescription(
        "控制项目简介和 README 的翻译语言，不改变项目编程语言筛选。"
    )
    selector_layout.addWidget(label)
    selector_layout.addWidget(combo)
    toolbar.insertWidget(language_index + 1, selector)
    window.contentLanguageSelector = selector
    window.contentLanguageLabel = label
    window.contentLanguageCombo = combo
    window.translation_language_combo = combo
    window._translation_language_generation = int(
        getattr(window, "_translation_language_generation", 0)
    )
    combo.currentIndexChanged.connect(
        lambda index: _on_content_language_changed(window, index)
    )
    settings_button = getattr(window, "settings_btn", None)
    if settings_button is not None:
        settings_button.setToolTip(
            "打开设置配置翻译服务；目标语言跟随顶部“翻译”选项。"
        )


