# ------------------------------ 增强设置与翻译运行时实现 ------------------------------
# 本段集中处理翻译服务安全边界、缓存、代理、设置导入导出和启动选项，
# 通过覆盖恢复代码中的方法保持旧版本数据和界面调用方式兼容。

import copy as _copy
from PyQt6.QtCore import QRunnable as _QRunnable, pyqtSignal as _pyqtSignal
from PyQt6.QtWidgets import (
    QCheckBox as _QCheckBox,
    QFileDialog as _QFileDialog,
    QMessageBox as _QMessageBox,
    QPushButton as _QPushButton,
    QSpinBox as _QSpinBox,
    QDoubleSpinBox as _QDoubleSpinBox,
)


_ENHANCED_DEFAULT_CONFIG = {
    "translation_cache_enabled": True,
    "translation_timeout_seconds": 12.0,
    "translation_retry_count": 1,
    "readme_image_enabled": True,
    "readme_image_timeout": 2.5,
    "startup_auto_load": True,
    "proxy_mode": "none",
}

_default_config = globals().get("DEFAULT_CONFIG")
if not isinstance(_default_config, dict):
    _default_config = _RECOVERED_NAMESPACE.get("DEFAULT_CONFIG")
if not isinstance(_default_config, dict):
    _default_config = {}
for _enhanced_key, _enhanced_value in _ENHANCED_DEFAULT_CONFIG.items():
    _default_config.setdefault(_enhanced_key, _copy.deepcopy(_enhanced_value))
DEFAULT_CONFIG = _default_config
_RECOVERED_NAMESPACE["DEFAULT_CONFIG"] = DEFAULT_CONFIG


def _config_bool(value, fallback: bool) -> bool:
    """把配置中的布尔值统一为稳定结果。"""
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value or "").strip().casefold()
    if text in {"1", "true", "yes", "on", "y", "是", "开启", "启用"}:
        return True
    if text in {"0", "false", "no", "off", "n", "否", "关闭", "禁用"}:
        return False
    return bool(fallback)


def _config_float(value, fallback: float, minimum: float, maximum: float) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        number = float(fallback)
    if not _math.isfinite(number):
        number = float(fallback)
    return min(max(number, float(minimum)), float(maximum))


def _config_int(value, fallback: int, minimum: int, maximum: int) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError):
        number = int(fallback)
    return min(max(number, int(minimum)), int(maximum))


def _normalize_proxy_mode(value, proxy_value="") -> str:
    """兼容旧版代理字段，并把代理模式限制为三种明确状态。"""
    raw = str(value or "").strip().casefold().replace("-", "_")
    aliases = {
        "": "custom" if str(proxy_value or "").strip() else "none",
        "auto": "system",
        "system_proxy": "system",
        "跟随系统": "system",
        "跟随系统代理": "system",
        "system": "system",
        "none": "none",
        "off": "none",
        "disable": "none",
        "不使用代理": "none",
        "custom": "custom",
        "manual": "custom",
        "自定义": "custom",
        "自定义代理": "custom",
    }
    return aliases.get(raw, "custom" if str(proxy_value or "").strip() else "none")


def _normalize_proxy_value(value) -> str:
    """规范代理地址；未填写协议时默认按 HTTP 代理处理。"""
    raw = str(value or "").strip()
    if not raw:
        return ""
    if "://" not in raw:
        raw = "http://" + raw
    try:
        parsed = _urlparse(raw)
    except Exception:
        return ""
    if parsed.scheme.casefold() not in {"http", "https", "socks5", "socks5h"}:
        return ""
    if not parsed.hostname:
        return ""
    return raw


def _normalize_enhanced_config(config):
    """补齐和校验新增配置，同时保持旧配置字段不丢失。"""
    if not isinstance(config, dict):
        config = {}
    for key, value in _ENHANCED_DEFAULT_CONFIG.items():
        config.setdefault(key, _copy.deepcopy(value))
    config["translation_provider"] = _normalize_translation_provider(
        config.get("translation_provider")
    )
    target_language = _normalize_target_language_for_display(
        config.get("target_language", "zh-CN")
    )
    config["target_language"] = (
        target_language if target_language in _TARGET_LANGUAGE_VALUES else "zh-CN"
    )
    config["translation_timeout_seconds"] = _config_float(
        config.get("translation_timeout_seconds"),
        _ENHANCED_DEFAULT_CONFIG["translation_timeout_seconds"],
        1.0,
        60.0,
    )
    config["translation_retry_count"] = _config_int(
        config.get("translation_retry_count"),
        _ENHANCED_DEFAULT_CONFIG["translation_retry_count"],
        0,
        3,
    )
    config["readme_image_timeout"] = _config_float(
        config.get("readme_image_timeout"),
        _ENHANCED_DEFAULT_CONFIG["readme_image_timeout"],
        0.75,
        10.0,
    )
    config["translation_cache_enabled"] = _config_bool(
        config.get("translation_cache_enabled"),
        True,
    )
    config["readme_image_enabled"] = _config_bool(
        config.get("readme_image_enabled"),
        True,
    )
    config["startup_auto_load"] = _config_bool(
        config.get("startup_auto_load"),
        True,
    )
    config["proxy"] = _normalize_proxy_value(config.get("proxy"))
    config["proxy_mode"] = _normalize_proxy_mode(
        config.get("proxy_mode"),
        config.get("proxy"),
    )
    if config["proxy_mode"] == "custom" and not config.get("proxy"):
        config["proxy_mode"] = "none"
    return config


def _proxy_mapping_for_config(config) -> dict:
    """返回 requests 使用的自定义代理映射。"""
    config = config if isinstance(config, dict) else {}
    mode = _normalize_proxy_mode(config.get("proxy_mode"), config.get("proxy"))
    if mode != "custom":
        return {}
    proxy = _normalize_proxy_value(config.get("proxy"))
    if not proxy:
        return {}
    return {"http": proxy, "https": proxy}


def _apply_session_network_config(session, config) -> None:
    """给 GitHub、翻译和图片请求统一应用代理与 SSL 设置。"""
    config = _normalize_enhanced_config(config if isinstance(config, dict) else {})
    mode = config.get("proxy_mode", "none")
    try:
        session.trust_env = mode == "system"
    except Exception:
        pass
    try:
        session.proxies = _proxy_mapping_for_config(config)
    except Exception:
        pass
    try:
        session.verify = _config_bool(config.get("ssl_verify"), True)
    except Exception:
        pass


def _apply_http_network_config(client, config=None) -> None:
    """让旧 HttpClient 的 session 也严格遵循新代理模式。"""
    if client is None:
        return
    if isinstance(config, dict):
        client.config = config
    session = getattr(client, "session", None)
    if session is not None:
        _apply_session_network_config(session, getattr(client, "config", config or {}))


_ORIGINAL_HTTPCLIENT_INIT_FOR_ENHANCED_CONFIG = HttpClient.__init__
_ORIGINAL_HTTPCLIENT_UPDATE_FOR_ENHANCED_CONFIG = HttpClient.update_config


def _httpclient_init_with_enhanced_config(self, config):
    normalized = _normalize_enhanced_config(config if isinstance(config, dict) else {})
    _ORIGINAL_HTTPCLIENT_INIT_FOR_ENHANCED_CONFIG(self, normalized)
    self.config = normalized
    _apply_http_network_config(self, normalized)


HttpClient.__init__ = _httpclient_init_with_enhanced_config


def _httpclient_update_with_enhanced_config(self, config):
    normalized = _normalize_enhanced_config(config if isinstance(config, dict) else {})
    result = _ORIGINAL_HTTPCLIENT_UPDATE_FOR_ENHANCED_CONFIG(self, normalized)
    self.config = normalized
    _apply_http_network_config(self, normalized)
    return result


HttpClient.update_config = _httpclient_update_with_enhanced_config


_ORIGINAL_GITHUBSERVICE_INIT_FOR_ENHANCED_CONFIG = GitHubService.__init__


def _githubservice_init_with_enhanced_config(self, config_path):
    _ORIGINAL_GITHUBSERVICE_INIT_FOR_ENHANCED_CONFIG(self, config_path)
    config = getattr(self, "config", None)
    normalized = _normalize_enhanced_config(config if isinstance(config, dict) else {})
    self.config = normalized
    http = getattr(self, "http", None)
    if http is not None:
        try:
            http.update_config(normalized)
        except Exception:
            _apply_http_network_config(http, normalized)


GitHubService.__init__ = _githubservice_init_with_enhanced_config


# ------------------------------ 翻译请求、重试和取消 ------------------------------

_TRANSLATION_RUNTIME_STATE = _threading.local()
_TRANSLATION_TIMEOUT_DEFAULT = 12.0
_TRANSLATION_TIMEOUT_MIN = 0.25
_TRANSLATION_TIMEOUT_CAP = 60.0
_TRANSLATION_RETRY_MAX = 3


def _translation_config_from_runtime(config=None):
    runtime_config = getattr(_TRANSLATION_RUNTIME_STATE, "config", None)
    if isinstance(config, dict):
        return _normalize_enhanced_config(config)
    if isinstance(runtime_config, dict):
        return _normalize_enhanced_config(runtime_config)
    return _normalize_enhanced_config({})


def _translation_deadline(config=None, deadline=None):
    config = _translation_config_from_runtime(config)
    configured = _config_float(
        config.get("translation_timeout_seconds"),
        _TRANSLATION_TIMEOUT_DEFAULT,
        1.0,
        _TRANSLATION_TIMEOUT_CAP,
    )
    now = _time.monotonic()
    if deadline is None:
        return now + configured
    try:
        supplied = float(deadline)
    except (TypeError, ValueError):
        return now + configured
    return min(supplied, now + configured)


def _translation_cancel_requested() -> bool:
    event = getattr(_TRANSLATION_RUNTIME_STATE, "cancel_event", None)
    return bool(event is not None and event.is_set())


class _TranslationCancelled(Exception):
    """翻译任务被用户切换页面或关闭窗口时使用的内部异常。"""


def _check_translation_budget(deadline=None) -> None:
    if _translation_cancel_requested():
        raise _TranslationCancelled("翻译任务已取消")
    if deadline is not None and deadline <= _time.monotonic():
        raise TimeoutError("翻译请求超时")


def _set_translation_status(
    provider: str,
    success: bool,
    used_external: bool,
    message: str,
) -> None:
    _TRANSLATION_RUNTIME_STATE.last_status = {
        "provider": provider,
        "success": bool(success),
        "used_external": bool(used_external),
        "message": str(message or ""),
    }


def _translation_timeout(deadline=None) -> tuple[float, float]:
    """根据当前配置和剩余截止时间生成连接、读取超时。"""
    config = _translation_config_from_runtime()
    configured = _config_float(
        config.get("translation_timeout_seconds"),
        _TRANSLATION_TIMEOUT_DEFAULT,
        1.0,
        _TRANSLATION_TIMEOUT_CAP,
    )
    remaining = configured
    if deadline is not None:
        try:
            remaining = min(configured, float(deadline) - _time.monotonic())
        except (TypeError, ValueError):
            remaining = configured
    if remaining <= 0:
        raise TimeoutError("翻译请求超时")
    if remaining < _TRANSLATION_TIMEOUT_MIN * 2:
        connect = max(0.05, remaining * 0.35)
        read = max(0.05, remaining - connect)
        return connect, read
    connect = min(3.0, max(_TRANSLATION_TIMEOUT_MIN, remaining * 0.35))
    read = max(_TRANSLATION_TIMEOUT_MIN, remaining - connect)
    return connect, read


def _translation_request_options(config=None) -> dict:
    """兼容旧接口的请求参数生成器；实际请求使用独立 Session。"""
    config = _translation_config_from_runtime(config)
    options = {
        "verify": _config_bool(config.get("ssl_verify"), True),
    }
    proxies = _proxy_mapping_for_config(config)
    if proxies:
        options["proxies"] = proxies
    return options


def _translation_request(method: str, url: str, config=None, **kwargs):
    """用独立 Session 发起翻译请求，确保不使用模式下彻底绕开系统代理。"""
    config = _translation_config_from_runtime(config)
    _check_translation_budget(kwargs.get("deadline"))
    deadline = kwargs.pop("deadline", None)
    session = _requests.Session()
    _apply_session_network_config(session, config)
    try:
        kwargs.setdefault("timeout", _translation_timeout(deadline))
        return session.request(method, url, **kwargs)
    finally:
        try:
            session.close()
        except Exception:
            pass


def _translation_retry_count(config) -> int:
    return _config_int(
        (config or {}).get("translation_retry_count"),
        1,
        0,
        _TRANSLATION_RETRY_MAX,
    )


def _translation_call_with_retry(call, source: str, provider: str, config, deadline=None):
    """在同一个总截止时间内重试当前服务，绝不自动切换到其他第三方。"""
    attempts = _translation_retry_count(config) + 1
    last_error = None
    for attempt in range(attempts):
        try:
            _check_translation_budget(deadline)
            result = call(deadline)
            if _translation_result_is_valid(source, result):
                _set_translation_status(provider, True, True, "翻译服务测试成功")
                return _text_value(result), True
            last_error = ValueError("接口返回空译文或无效译文")
        except _TranslationCancelled:
            raise
        except Exception as exc:
            last_error = exc
        if attempt + 1 >= attempts:
            break
        wait_seconds = min(0.2 * (attempt + 1), 0.8)
        event = getattr(_TRANSLATION_RUNTIME_STATE, "cancel_event", None)
        if event is not None and event.wait(wait_seconds):
            raise _TranslationCancelled("翻译任务已取消")
        if deadline is not None and deadline - _time.monotonic() <= 0:
            break
    if last_error is not None:
        _TRANSLATION_RUNTIME_STATE.last_error = last_error
    return "", False


def _translation_credential_pair(config):
    config = config if isinstance(config, dict) else {}
    secret_id = _text_value(
        config.get("tencent_secret_id") or config.get("tencent_id")
    )
    secret_key = _text_value(
        config.get("tencent_secret_key") or config.get("tencent_key")
    )
    return secret_id, secret_key


def _tencent_language_code(value, target=False) -> str:
    if target:
        helper = _RECOVERED_NAMESPACE.get("_tencent_target_code")
    else:
        helper = _RECOVERED_NAMESPACE.get("_translation_source_code")
    try:
        result = helper(value) if callable(helper) else value
    except Exception:
        result = value
    return _text_value(result) or ("zh" if target else "en")


def _tencent_translate_with_enhanced_config(
    text: str,
    secret_id: str,
    secret_key: str,
    source="en",
    target="zh-CN",
    config=None,
    deadline=None,
):
    """调用腾讯云标准 TC3 签名接口，使用统一代理、SSL 和超时配置。"""
    config = _translation_config_from_runtime(config)
    secret_id = _text_value(secret_id)
    secret_key = _text_value(secret_key)
    if not secret_id or not secret_key:
        return ""
    host = "tmt.tencentcloudapi.com"
    service_name = "tmt"
    action = "TextTranslate"
    version = "2018-03-21"
    region = _text_value(config.get("tencent_region")) or "ap-beijing"
    payload = {
        "SourceText": str(text or ""),
        "Source": _tencent_language_code(source),
        "Target": _tencent_language_code(target, target=True),
        "ProjectId": 0,
    }
    authorization, body, timestamp = _translator.tc3_authorization(
        secret_id,
        secret_key,
        host,
        service_name,
        action,
        version,
        region,
        payload,
    )
    response = _translation_request(
        "POST",
        "https://" + host,
        config,
        data=body.encode("utf-8"),
        headers={
            "Authorization": authorization,
            "Content-Type": "application/json; charset=utf-8",
            "Host": host,
            "X-TC-Action": action,
            "X-TC-Version": version,
            "X-TC-Region": region,
            "X-TC-Timestamp": timestamp,
        },
        deadline=deadline,
    )
    data = _translation_response_json(response)
    root = data.get("Response", data) if isinstance(data, dict) else {}
    return _text_value(root.get("TargetText")) if isinstance(root, dict) else ""


