_translate_with_openai_compatible = _translate_with_openai_compatible_enhanced


def _provider_has_required_credentials(provider: str, config) -> bool:
    config = config if isinstance(config, dict) else {}
    if provider == "tencent":
        return all(_translation_credential_pair(config))
    if provider in {"deepl", "google"}:
        return bool(_text_value(config.get("translation_api_key")))
    if provider == "openai_compatible":
        return bool(
            _text_value(config.get("translation_api_key"))
            or _text_value(config.get("translation_api_url"))
        )
    return True


def _translate_short_text_with_provider_enhanced(
    text: str,
    source: str,
    target: str,
    config=None,
    deadline=None,
) -> tuple[str, bool]:
    """按明确服务翻译；自动模式只用本地规则，不隐式访问第三方。"""
    text = _text_value(text)
    if not text:
        _set_translation_status("local", True, False, "空文本无需翻译")
        return "", False
    config = _translation_config_from_runtime(config)
    provider = _translation_provider(config)
    target = _normalize_target_language_for_display(target)
    deadline = _translation_deadline(config, deadline)
    previous_config = getattr(_TRANSLATION_RUNTIME_STATE, "config", None)
    previous_deadline = getattr(_TRANSLATION_RUNTIME_STATE, "deadline", None)
    try:
        _TRANSLATION_RUNTIME_STATE.config = config
        _TRANSLATION_RUNTIME_STATE.deadline = deadline
        if provider in {"auto", "local"}:
            result = _local_translate(text, target)
            result = _text_value(result) or text
            _set_translation_status(
                provider,
                True,
                False,
                "自动模式仅使用本地规则" if provider == "auto" else "已使用本地规则",
            )
            return result, False
        if not _provider_has_required_credentials(provider, config):
            _set_translation_status(provider, False, False, "当前服务缺少必要密钥或接口地址")
            return text, False

        def call(current_deadline):
            if provider == "tencent":
                secret_id, secret_key = _translation_credential_pair(config)
                return _tencent_translate_with_enhanced_config(
                    text,
                    secret_id,
                    secret_key,
                    _translation_source_code(source),
                    target,
                    config,
                    current_deadline,
                )
            if provider == "deepl":
                return _translate_with_deepl_enhanced(
                    text, source, target, config, current_deadline
                )
            if provider == "google":
                return _translate_with_google_cloud_enhanced(
                    text, source, target, config, current_deadline
                )
            if provider == "openai_compatible":
                return _translate_with_openai_compatible_enhanced(
                    text, source, target, config, current_deadline
                )
            return ""

        translated, used_external = _translation_call_with_retry(
            call,
            text,
            provider,
            config,
            deadline,
        )
        if used_external:
            return translated, True
        error = getattr(_TRANSLATION_RUNTIME_STATE, "last_error", None)
        message = "当前服务失败，已回退本地规则"
        if isinstance(error, TimeoutError):
            message = "当前服务超时，已回退本地规则"
        _set_translation_status(provider, False, False, message)
        local_result = _local_translate(text, target)
        return _text_value(local_result) or text, False
    except _TranslationCancelled:
        _set_translation_status(provider, False, False, "翻译任务已取消")
        return text, False
    except Exception:
        _write_startup_log(
            f"翻译服务 {provider} 执行失败，已回退本地规则",
            _sys.exc_info(),
        )
        _set_translation_status(provider, False, False, "翻译服务异常，已回退本地规则")
        try:
            local_result = _local_translate(text, target)
        except Exception:
            local_result = text
        return _text_value(local_result) or text, False
    finally:
        if previous_config is None:
            try:
                del _TRANSLATION_RUNTIME_STATE.config
            except AttributeError:
                pass
        else:
            _TRANSLATION_RUNTIME_STATE.config = previous_config
        if previous_deadline is None:
            try:
                del _TRANSLATION_RUNTIME_STATE.deadline
            except AttributeError:
                pass
        else:
            _TRANSLATION_RUNTIME_STATE.deadline = previous_deadline


