_restore_markdown_blocks = _translator.restore_markdown_blocks

# 字节码内部占位符（ZXQGOSB{n}TOKEN）会被腾讯翻译拆成带空格的
# "ZXQGOSB 0TOKEN"，其自身恢复逻辑匹配不上而残留泄漏。外层保护层已覆盖
# 代码块/URL/HTML/行内代码等，这里把字节码内部保护降级为 no-op，
# 由外层统一占位，避免 ZXQGOSB 生成。
_protect_markdown_fragment = _translator.protect_markdown_fragment_noop
