_ORIGINAL_TRANSLATE_README_MARKDOWN_FOR_ENHANCED = _translate_readme_markdown_text


def _translate_readme_markdown_with_enhanced_runtime(
    markdown_text: str,
    target="zh-CN",
    config=None,
    deadline=None,
) -> tuple[str, bool]:
    """保留原有 Markdown 结构处理，同时注入统一超时、取消、服务配置和占位保护。"""
    source = str(markdown_text or "")
    if not source.strip():
        return "", False
    config = _translation_config_from_runtime(config)
    deadline = _translation_deadline(config, deadline)
    protected_text, placeholders = _protect_markdown_blocks(source)
    previous_config = getattr(_TRANSLATION_RUNTIME_STATE, "config", None)
    previous_deadline = getattr(_TRANSLATION_RUNTIME_STATE, "deadline", None)
    try:
        _TRANSLATION_RUNTIME_STATE.config = config
        _TRANSLATION_RUNTIME_STATE.deadline = deadline
        result = _ORIGINAL_TRANSLATE_README_MARKDOWN_FOR_ENHANCED(
            protected_text,
            target,
            config,
            deadline,
        )
        if isinstance(result, tuple):
            raw_translated = str(result[0] or source)
            used_external = bool(result[1])
        else:
            raw_translated = str(result or source)
            used_external = bool(
                getattr(_TRANSLATION_RUNTIME_STATE, "last_status", {}).get("used_external")
            )
        restored = _restore_markdown_blocks(raw_translated, placeholders)
        if placeholders:
            present = set(_PLACEHOLDER_RESIDUAL.findall(raw_translated))
            required = {_placeholder_token(i) for i in range(len(placeholders))}
            if present != required:
                _write_startup_log(
                    "README 译文占位符缺失或数量不符，已回退原文",
                )
                return source, False
            if _PLACEHOLDER_RESIDUAL.search(restored):
                _write_startup_log(
                    "README 译文占位符未完整恢复，已回退原文",
                )
                return source, False
        if _LEGACY_PLACEHOLDER_RESIDUAL.search(raw_translated):
            _write_startup_log(
                "README 译文残留旧版占位符（ZXQGOSB），已回退原文",
            )
            return source, False
        return restored, used_external
    except _TranslationCancelled:
        return source, False
    except Exception:
        _write_startup_log("README 翻译失败，已保留原文", _sys.exc_info())
        return source, False
    finally:
        if previous_config is None:
            try:
                del _TRANSLATION_RUNTIME_STATE.config
            except AttributeError:
                pass
        else:
            _TRANSLATION_RUNTIME_STATE.config = previous_config
        if previous_deadline is None:
            try:
                del _TRANSLATION_RUNTIME_STATE.deadline
            except AttributeError:
                pass
        else:
            _TRANSLATION_RUNTIME_STATE.deadline = previous_deadline


