def _translation_cache_is_enabled(service_or_config) -> bool:
    if isinstance(service_or_config, dict):
        config = service_or_config
    else:
        config = getattr(service_or_config, "config", {}) or {}
    return _config_bool(config.get("translation_cache_enabled"), True)


def _translation_cache_scope(config) -> str:
    config = _translation_config_from_runtime(config)
    provider = _translation_provider(config)
    if provider == "auto":
        return "local-auto-v2"
    credentials = (
        _text_value(config.get("translation_api_key"))
        or "|".join(_translation_credential_pair(config))
    )
    scope_source = "|".join(
        (
            provider,
            _translation_endpoint(config, provider),
            _text_value(config.get("translation_model")),
            _hashlib.sha256(credentials.encode("utf-8", "ignore")).hexdigest()[:16],
        )
    )
    return provider + "-" + _hashlib.sha1(scope_source.encode("utf-8", "ignore")).hexdigest()[:16]


def _translation_cache_key_for_provider_enhanced(target_language, text: str, config=None) -> str:
    base_key = _translation_cache_key(target_language, text)
    scope = _translation_cache_scope(config or {})
    return f"{base_key}::provider::{scope}"


_translation_cache_key_for_provider = _translation_cache_key_for_provider_enhanced


