def _read_translation_cache_value_with_switch(self, key: str, source: str):
    if not _translation_cache_is_enabled(self):
        return None
    return _ORIGINAL_READ_TRANSLATION_CACHE_FOR_ENHANCED(self, key, source)


def _write_translation_cache_value_with_switch(self, key: str, value: str) -> None:
    if not _translation_cache_is_enabled(self):
        return
    _ORIGINAL_WRITE_TRANSLATION_CACHE_FOR_ENHANCED(self, key, value)


