def _translation_cache_stats_for_service(service) -> dict:
    database = getattr(service, "db", None)
    stats_method = getattr(database, "get_translation_cache_stats", None)
    if callable(stats_method):
        try:
            result = stats_method()
            return {
                "count": int(result.get("count", 0)),
                "bytes": int(result.get("bytes", 0)),
            }
        except Exception:
            pass
    return {"count": 0, "bytes": 0}


def _clear_translation_cache_for_service(service) -> None:
    database = getattr(service, "db", None)
    clear_method = getattr(database, "clear_translation_cache", None)
    if callable(clear_method):
        try:
            clear_method()
        except Exception:
            pass
    cache = getattr(service, "cache", None)
    data = getattr(cache, "data", None)
    lock = getattr(cache, "_lock", None)
    try:
        if isinstance(data, dict):
            if callable(getattr(lock, "__enter__", None)):
                with lock:
                    data.clear()
            else:
                data.clear()
            path = _text_value(getattr(cache, "path", ""))
            if path:
                _Path(path).parent.mkdir(parents=True, exist_ok=True)
                _Path(path).write_text("{}", encoding="utf-8")
    except Exception:
        _write_startup_log("清理翻译文件缓存失败", _sys.exc_info())
    for path_value in (
        getattr(service, "translation_cache_path", None),
        getattr(service, "translation_cache_file", None),
    ):
        try:
            if path_value and _Path(path_value).is_file():
                _Path(path_value).write_text("{}", encoding="utf-8")
        except Exception:
            pass


def _format_cache_bytes(value) -> str:
    try:
        number = max(0, int(value))
    except (TypeError, ValueError):
        number = 0
    units = ("B", "KB", "MB", "GB")
    size = float(number)
    for unit in units:
        if size < 1024 or unit == units[-1]:
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024
    return f"{number} B"


def _service_translate_description_with_enhanced_cache(self, text: str, deadline=None) -> str:
    source = _text_value(text)
    if not source:
        return source
    config = _normalize_enhanced_config(getattr(self, "config", {}) or {})
    target = _normalize_target_language_for_display(config.get("target_language", "zh-CN"))
    key = _translation_cache_key_for_provider_enhanced(target, source, config)
    if _translation_cache_is_enabled(config):
        cached = _read_translation_cache_value_with_switch(self, key, source)
        if cached:
            return cached
    translated, _used_external = _translate_short_text_with_provider_enhanced(
        source,
        "auto",
        target,
        config,
        deadline,
    )
    result = _text_value(translated) or source
    if _translation_cache_is_enabled(config) and _translation_result_is_valid(source, result):
        _write_translation_cache_value_with_switch(self, key, result)
    return result


def _service_translate_readme_with_enhanced_cache(
    self,
    markdown_text: str,
    full_name: str = "",
    branch: str = "main",
    deadline=None,
) -> tuple[str, bool]:
    source = str(markdown_text or "")
    if not source.strip():
        return "", False
    config = _normalize_enhanced_config(getattr(self, "config", {}) or {})
    target = _normalize_target_language_for_display(config.get("target_language", "zh-CN"))
    digest = _hashlib.sha1(source.encode("utf-8", "ignore")).hexdigest()
    key = (
        f"readme_md_{README_TRANSLATION_CACHE_VERSION}::{target}::"
        f"{full_name}::{branch}::{digest}::provider::{_translation_cache_scope(config)}"
    )
    if _translation_cache_is_enabled(config):
        cached = _read_translation_cache_value_with_switch(self, key, source)
        if cached:
            return cached, True
    translated, used_external = _translate_readme_markdown_with_enhanced_runtime(
        source,
        target,
        config,
        deadline,
    )
    result = str(translated or source)
    if _translation_cache_is_enabled(config) and _translation_result_is_valid(source, result):
        _write_translation_cache_value_with_switch(self, key, result)
    return result, bool(used_external)


