def _batch_translate_with_enhanced_cache(self, texts: list[str]) -> list[str]:
    if not texts:
        return []
    config = _normalize_enhanced_config(getattr(self, "config", {}) or {})
    target = _normalize_target_language_for_display(config.get("target_language", "zh-CN"))
    translated_map = {}
    key_map = {}
    missing = []
    for text in list(dict.fromkeys(text for text in texts if _text_value(text))):
        key = _translation_cache_key_for_provider_enhanced(target, text, config)
        key_map[text] = key
        cached = (
            _read_translation_cache_value_with_switch(self, key, text)
            if _translation_cache_is_enabled(config)
            else None
        )
        if cached is None:
            missing.append(text)
        else:
            translated_map[text] = cached
    for source in missing:
        result, _used_external = _translate_short_text_with_provider_enhanced(
            source,
            "auto",
            target,
            config,
        )
        result = _text_value(result) or source
        translated_map[source] = result
        if (
            _translation_cache_is_enabled(config)
            and _translation_result_is_valid(source, result)
        ):
            _write_translation_cache_value_with_switch(self, key_map[source], result)
    return [
        translated_map.get(text, text) if _text_value(text) else text
        for text in texts
    ]


GitHubService.batch_translate = _batch_translate_with_enhanced_cache


