def _find_form_with_widget(dialog, target):
    if target is None:
        return None
    for form in dialog.findChildren(_QFormLayout):
        for row in range(form.rowCount()):
            for role in (
                _QFormLayout.ItemRole.FieldRole,
                _QFormLayout.ItemRole.SpanningRole,
                _QFormLayout.ItemRole.LabelRole,
            ):
                widget = _form_item_widget(form, row, role)
                if widget is target:
                    return form
    return None


def _form_row_of_widget(form, target):
    if form is None or target is None:
        return -1
    for row in range(form.rowCount()):
        if _form_item_widget(form, row, _QFormLayout.ItemRole.FieldRole) is target:
            return row
        if _form_item_widget(form, row, _QFormLayout.ItemRole.SpanningRole) is target:
            return row
    return -1


def _make_button_row(parent, buttons):
    row = _QWidget(parent)
    layout = _QHBoxLayout(row)
    layout.setContentsMargins(0, 0, 0, 0)
    layout.setSpacing(6)
    for button in buttons:
        layout.addWidget(button)
    layout.addStretch(1)
    return row


def _dialog_config(dialog) -> dict:
    service = getattr(dialog, "service", None)
    config = getattr(service, "config", None)
    return _normalize_enhanced_config(config if isinstance(config, dict) else {})


def _setting_status(dialog, message: str) -> None:
    label = getattr(dialog, "translation_test_status", None)
    if label is not None:
        label.setText(str(message))
    status = getattr(dialog, "status_label", None)
    if status is not None:
        try:
            status.setText(str(message))
        except Exception:
            pass


