def _set_dialog_secret_visibility(dialog, hidden: bool) -> None:
    for name in (
        "tencent_id_edit",
        "tencent_key_edit",
        "translation_api_key_edit",
    ):
        widget = getattr(dialog, name, None)
        if widget is None:
            continue
        try:
            widget.setEchoMode(
                _QLineEdit.EchoMode.Password if hidden else _QLineEdit.EchoMode.Normal
            )
        except Exception:
            pass


def _clear_dialog_secret_fields(dialog) -> None:
    for name in (
        "tencent_id_edit",
        "tencent_key_edit",
        "translation_api_key_edit",
    ):
        widget = getattr(dialog, name, None)
        if widget is not None:
            try:
                widget.clear()
            except Exception:
                pass
    _setting_status(dialog, "密钥字段已清除，点击保存后生效")


def _update_translation_cache_stats(dialog) -> None:
    label = getattr(dialog, "translation_cache_stats_label", None)
