def _settings_payload_from_dialog(dialog) -> dict:
    config = _dialog_config(dialog)
    _sync_dialog_target_language_from_main_window(dialog)
    provider_combo = getattr(dialog, "translation_provider_combo", None)
    if provider_combo is not None:
        config["translation_provider"] = _normalize_translation_provider(
            provider_combo.currentData()
        )
    for key, attr in (
        ("translation_api_url", "translation_api_url_edit"),
        ("translation_api_key", "translation_api_key_edit"),
        ("translation_model", "translation_model_edit"),
        ("tencent_secret_id", "tencent_id_edit"),
        ("tencent_secret_key", "tencent_key_edit"),
    ):
        widget = getattr(dialog, attr, None)
        if widget is not None:
            config[key] = _text_value(widget.text())
    timeout_spin = getattr(dialog, "translation_timeout_spin", None)
    if timeout_spin is not None:
        config["translation_timeout_seconds"] = timeout_spin.value()
    retry_spin = getattr(dialog, "translation_retry_spin", None)
    if retry_spin is not None:
        config["translation_retry_count"] = retry_spin.value()
    cache_checkbox = getattr(dialog, "translation_cache_checkbox", None)
    if cache_checkbox is not None:
        config["translation_cache_enabled"] = cache_checkbox.isChecked()
    proxy_combo = getattr(dialog, "proxy_mode_combo", None)
    if proxy_combo is not None:
        config["proxy_mode"] = _normalize_proxy_mode(proxy_combo.currentData(), "")
    proxy_edit = getattr(dialog, "proxy_edit", None)
    if proxy_edit is not None:
        config["proxy"] = _text_value(proxy_edit.text())
    ssl_checkbox = getattr(dialog, "ssl_checkbox", None)
    if ssl_checkbox is not None:
        config["ssl_verify"] = ssl_checkbox.isChecked()
    startup_checkbox = getattr(dialog, "startup_auto_load_checkbox", None)
    if startup_checkbox is not None:
        config["startup_auto_load"] = startup_checkbox.isChecked()
    image_checkbox = getattr(dialog, "readme_image_checkbox", None)
    if image_checkbox is not None:
        config["readme_image_enabled"] = image_checkbox.isChecked()
    image_timeout = getattr(dialog, "readme_image_timeout_spin", None)
    if image_timeout is not None:
        config["readme_image_timeout"] = image_timeout.value()
    return _normalize_enhanced_config(config)


def _persist_service_config(service, config=None) -> None:
    if service is None:
        return
    if config is not None:
        service.config = _normalize_enhanced_config(config)
    else:
        service.config = _normalize_enhanced_config(getattr(service, "config", {}) or {})
    http = getattr(service, "http", None)
    if http is not None:
        try:
            http.update_config(service.config)
        except Exception:
            _apply_http_network_config(http, service.config)
    saver = getattr(service, "save_config", None)
    if callable(saver):
        try:
            saver()
        except Exception:
            _write_startup_log("保存增强设置失败", _sys.exc_info())


def _apply_config_to_dialog(dialog) -> None:
    config = _dialog_config(dialog)
    combo = getattr(dialog, "translation_provider_combo", None)
    if combo is not None:
        index = combo.findData(config.get("translation_provider", "auto"))
        if index >= 0:
            combo.setCurrentIndex(index)
    for key, attr in (
        ("translation_api_url", "translation_api_url_edit"),
        ("translation_api_key", "translation_api_key_edit"),
        ("translation_model", "translation_model_edit"),
        ("tencent_secret_id", "tencent_id_edit"),
        ("tencent_secret_key", "tencent_key_edit"),
        ("proxy", "proxy_edit"),
    ):
        widget = getattr(dialog, attr, None)
        if widget is not None:
            widget.setText(_text_value(config.get(key)))
    timeout_spin = getattr(dialog, "translation_timeout_spin", None)
    if timeout_spin is not None:
        timeout_spin.setValue(config.get("translation_timeout_seconds", 12.0))
    retry_spin = getattr(dialog, "translation_retry_spin", None)
    if retry_spin is not None:
        retry_spin.setValue(config.get("translation_retry_count", 1))
    cache_checkbox = getattr(dialog, "translation_cache_checkbox", None)
    if cache_checkbox is not None:
        cache_checkbox.setChecked(config.get("translation_cache_enabled", True))
    proxy_combo = getattr(dialog, "proxy_mode_combo", None)
    if proxy_combo is not None:
        index = proxy_combo.findData(config.get("proxy_mode", "none"))
        if index >= 0:
            proxy_combo.setCurrentIndex(index)
    ssl_checkbox = getattr(dialog, "ssl_checkbox", None)
    if ssl_checkbox is not None:
        ssl_checkbox.setChecked(config.get("ssl_verify", True))
    startup_checkbox = getattr(dialog, "startup_auto_load_checkbox", None)
    if startup_checkbox is not None:
        startup_checkbox.setChecked(config.get("startup_auto_load", True))
    image_checkbox = getattr(dialog, "readme_image_checkbox", None)
    if image_checkbox is not None:
        image_checkbox.setChecked(config.get("readme_image_enabled", True))
    image_timeout = getattr(dialog, "readme_image_timeout_spin", None)
    if image_timeout is not None:
        image_timeout.setValue(config.get("readme_image_timeout", 2.5))
    _set_dialog_secret_visibility(dialog, True)
    _refresh_translation_setting_visibility_enhanced(dialog)
    _refresh_proxy_setting_visibility(dialog)
    _update_translation_cache_stats(dialog)


def _export_settings_to_path(dialog, path) -> bool:
    config = _settings_payload_from_dialog(dialog)
    secret_keys = {
        "github_token",
        "oauth_client_id",
        "tencent_secret_id",
        "tencent_secret_key",
        "translation_api_key",
        "favorites",
        "download_history",
    }
    payload = {
        key: _copy.deepcopy(value)
        for key, value in config.items()
        if key not in secret_keys
    }
    try:
        target = _Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(
            _json.dumps(
                {"format": "github-open-source-browser-settings", "version": 1, "settings": payload},
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        _setting_status(dialog, f"设置已导出：{target.name}")
        return True
    except Exception:
        _setting_status(dialog, "设置导出失败，请检查文件路径")
        _write_startup_log("设置导出失败", _sys.exc_info())
        return False


def _import_settings_from_path(dialog, path) -> bool:
    try:
        data = _json.loads(_Path(path).read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            raise ValueError("设置文件不是对象")
        imported = data.get("settings", data)
        if not isinstance(imported, dict):
            raise ValueError("设置内容不是对象")
        current = _dialog_config(dialog)
        protected = {
            "github_token",
            "oauth_client_id",
            "tencent_secret_id",
            "tencent_secret_key",
            "translation_api_key",
            "favorites",
            "download_history",
        }
        allowed = set(DEFAULT_CONFIG) - protected
        for key, value in imported.items():
            if key in allowed:
                current[key] = value
        current = _normalize_enhanced_config(current)
        _persist_service_config(getattr(dialog, "service", None), current)
        _apply_config_to_dialog(dialog)
        _setting_status(dialog, "设置已导入，密钥和令牌保持当前值")
        return True
    except Exception:
        _setting_status(dialog, "设置导入失败，请选择有效的 JSON 设置文件")
        _write_startup_log("设置导入失败", _sys.exc_info())
        return False


def _restore_default_settings(dialog) -> None:
    current = _dialog_config(dialog)
    defaults = _copy.deepcopy(DEFAULT_CONFIG)
    protected = {
        "github_token",
        "oauth_client_id",
        "tencent_secret_id",
        "tencent_secret_key",
        "translation_api_key",
        "favorites",
        "download_history",
    }
    for key in protected:
        if key in current:
            defaults[key] = _copy.deepcopy(current[key])
    _persist_service_config(getattr(dialog, "service", None), defaults)
    _apply_config_to_dialog(dialog)
    _setting_status(dialog, "设置已恢复默认，密钥、收藏和下载记录已保留")


def _open_settings_export_dialog(dialog) -> None:
    path, _filter = _QFileDialog.getSaveFileName(
        dialog,
        "导出设置",
        "github-open-source-browser-settings.json",
        "JSON 设置文件 (*.json)",
    )
    if path:
        _export_settings_to_path(dialog, path)


def _open_settings_import_dialog(dialog) -> None:
    path, _filter = _QFileDialog.getOpenFileName(
        dialog,
        "导入设置",
        "",
        "JSON 设置文件 (*.json)",
    )
    if path:
        _import_settings_from_path(dialog, path)


def _install_enhanced_network_settings(dialog):
    form = _find_form_with_widget(dialog, getattr(dialog, "proxy_edit", None))
    if form is None or getattr(dialog, "proxy_mode_combo", None) is not None:
        return
    config = _dialog_config(dialog)
