class _TranslationTestSignals(_QObject):
    finished = _pyqtSignal(bool, str)


class _TranslationTestRunnable(_QRunnable):
    def __init__(self, dialog, config):
        super().__init__()
        self.dialog = dialog
        self.config = config
        self.signals = _TranslationTestSignals(dialog)
        self.setAutoDelete(True)

    def run(self):
        try:
            target = _normalize_target_language_for_display(
                self.config.get("target_language", "zh-CN")
            )
            deadline = _time.monotonic() + _config_float(
                self.config.get("translation_timeout_seconds"),
                12.0,
                1.0,
                60.0,
            ) + 1.0
            translated, used_external = _translate_short_text_with_provider_enhanced(
                "Hello GitHub",
                "en",
                target,
                self.config,
                deadline,
            )
            status = getattr(_TRANSLATION_RUNTIME_STATE, "last_status", {})
            provider = _translation_provider(self.config)
            if provider in {"auto", "local"}:
                self.signals.finished.emit(True, "测试成功：已使用本地规则，不访问第三方接口")
            elif used_external and translated:
                self.signals.finished.emit(True, f"测试成功：{provider} 已返回译文")
            else:
                self.signals.finished.emit(
                    False,
                    str(status.get("message") or "测试失败：已回退本地规则"),
                )
        except Exception as exc:
            self.signals.finished.emit(False, f"测试失败：{exc}")


def _start_translation_service_test(dialog) -> None:
    button = getattr(dialog, "translation_test_button", None)
    if button is not None:
        button.setEnabled(False)
    _setting_status(dialog, "正在测试当前翻译服务……")
    config = _settings_payload_from_dialog(dialog)
    runner = _TranslationTestRunnable(dialog, config)
    dialog._translation_test_runnable = runner

    def finished(success, message):
        if button is not None:
            button.setEnabled(True)
        _setting_status(dialog, ("✓ " if success else "✗ ") + str(message))
        dialog._translation_test_runnable = None

    runner.signals.finished.connect(finished)
    _QThreadPool.globalInstance().start(runner)


_ORIGINAL_SETTINGS_DIALOG_INIT_FOR_ENHANCED_SETTINGS = SettingsDialog.__init__


def _settings_dialog_init_with_enhanced_settings(self, *args, **kwargs):
    _ORIGINAL_SETTINGS_DIALOG_INIT_FOR_ENHANCED_SETTINGS(self, *args, **kwargs)
    if getattr(self, "_enhanced_settings_installed", False):
        return
    self._enhanced_settings_installed = True
    try:
        translation_form = _find_form_with_widget(
            self,
            getattr(self, "translation_provider_combo", None),
        )
        if translation_form is not None:
            _install_enhanced_translation_settings(self, translation_form)
            provider_combo = getattr(self, "translation_provider_combo", None)
            if provider_combo is not None:
                provider_combo.currentIndexChanged.connect(
                    lambda _index: _refresh_translation_setting_visibility_enhanced(self)
                )
            _refresh_translation_setting_visibility_enhanced(self)
        _install_enhanced_network_settings(self)
        _install_enhanced_other_settings(self)
        _apply_config_to_dialog(self)
    except Exception:
        _write_startup_log("增强设置页初始化失败", _sys.exc_info())


SettingsDialog.__init__ = _settings_dialog_init_with_enhanced_settings


_ORIGINAL_SETTINGS_DIALOG_ACCEPT_FOR_ENHANCED_SETTINGS = SettingsDialog.accept


def _settings_dialog_accept_with_enhanced_settings(self):
    config = _settings_payload_from_dialog(self)
    service = getattr(self, "service", None)
    if service is not None:
        service.config = config
    result = _ORIGINAL_SETTINGS_DIALOG_ACCEPT_FOR_ENHANCED_SETTINGS(self)
    # 旧保存逻辑只认识旧字段，保存后再次写入新增字段确保重启不丢设置。
    if service is not None:
        service.config = _normalize_enhanced_config(getattr(service, "config", config))
        _persist_service_config(service, service.config)
    return result


SettingsDialog.accept = _settings_dialog_accept_with_enhanced_settings


# ------------------------------ 后台翻译任务使用可取消事件 ------------------------------

_ORIGINAL_RUN_IN_THREAD_FOR_TRANSLATION_CONTEXT = MainWindow.run_in_thread


def _run_in_thread_with_translation_context(self, fn, on_done=None, on_error=None):
    """在现有可取消任务外再绑定线程本地取消事件，不改变原有回调协议。"""
    def wrapped():
        # 通过当前窗口的活动任务集合找到刚提交的最新任务；找不到时仍可正常执行。
        event = None
        try:
            _ensure_async_task_state(self)
            with self._async_task_lock:
                candidates = list(self._active_async_tasks)
            if candidates:
                latest = max(
                    candidates,
                    key=lambda item: int(getattr(item, "context", (0, 0, 0))[0] or 0),
                )
                event = getattr(latest, "cancel_event", None)
        except Exception:
            event = None
        previous = getattr(_TRANSLATION_RUNTIME_STATE, "cancel_event", None)
        _TRANSLATION_RUNTIME_STATE.cancel_event = event
        try:
            return fn()
        finally:
            if previous is None:
                try:
                    del _TRANSLATION_RUNTIME_STATE.cancel_event
                except AttributeError:
                    pass
            else:
                _TRANSLATION_RUNTIME_STATE.cancel_event = previous

    return _ORIGINAL_RUN_IN_THREAD_FOR_TRANSLATION_CONTEXT(
        self,
        wrapped,
        on_done,
        on_error,
    )


MainWindow.run_in_thread = _run_in_thread_with_translation_context


# ------------------------------ 启动自动加载开关 ------------------------------

_ORIGINAL_MAINWINDOW_INIT_FOR_ENHANCED_STARTUP = MainWindow.__init__


def _mainwindow_init_with_enhanced_startup(self, *args, **kwargs):
    service = args[0] if args else kwargs.get("service")
    config = getattr(service, "config", {}) if service is not None else {}
    config = _normalize_enhanced_config(config if isinstance(config, dict) else {})
    if config.get("startup_auto_load", True):
        return _ORIGINAL_MAINWINDOW_INIT_FOR_ENHANCED_STARTUP(self, *args, **kwargs)

    original_refresh = MainWindow.refresh_repos
    original_mirror = MainWindow._start_mirror_autotest
    original_release = MainWindow._start_release_notify

    def skip_refresh(_window, *refresh_args, **refresh_kwargs):
        return None

    def skip_mirror(_window, *mirror_args, **mirror_kwargs):
        return None

    def skip_release(_window, *release_args, **release_kwargs):
        return None

    MainWindow.refresh_repos = skip_refresh
    MainWindow._start_mirror_autotest = skip_mirror
    MainWindow._start_release_notify = skip_release
    try:
        result = _ORIGINAL_MAINWINDOW_INIT_FOR_ENHANCED_STARTUP(self, *args, **kwargs)
    finally:
        MainWindow.refresh_repos = original_refresh
        MainWindow._start_mirror_autotest = original_mirror
        MainWindow._start_release_notify = original_release
    try:
        _QTimer.singleShot(
            0,
            lambda: self.statusBar().showMessage(
                "已跳过启动自动加载，请点击“刷新”加载项目"
            )
            if getattr(self, "statusBar", None) is not None
            else None,
        )
    except Exception:
        pass
    return result


MainWindow.__init__ = _mainwindow_init_with_enhanced_startup

